-- ════════════════════════════════════════════════════════
-- 250 — Huitième recensement : les ajouts aux fiches existantes,
--       lots 01 à 04 (seize lignes de gamme, neuf paragraphes)
-- ────────────────────────────────────────────────────────
-- D'OÙ ILS VIENNENT. Le recensement a trouvé des marques que l'atlas
-- n'avait pas et qui n'y auront pas de fiche, parce qu'elles
-- appartiennent à une maison qui en a déjà une : une ligne de son
-- catalogue (`gamme`), ou la marque d'un tiers qu'elle roule (`mention`,
-- une phrase de son histoire et le nom dans `brands.mentions`, que lit la
-- recherche depuis la 238). Chaque rattachement a été éprouvé sur des
-- pages avant d'être écrit.
--
-- ── CE QUI ENTRE ────────────────────────────────────────
--   Lignes de gamme   Cachitos (1502 Cigars) ; San Lotano (A.J.
--                     Fernandez) ; Lunatic et JFR (Aganorsa Leaf) ; La
--                     Bohème (Aging Room) ; Rancho Luna et Tatascan
--                     (Aladino) ; La Rosa de Sandiego (American
--                     Caribbean Cigars) ; Casa Cuba et Fuente Fuente
--                     OpusX The Lost City (Arturo Fuente) ; San
--                     Cristobal (Ashton) ; Back2Back (Davidoff) ;
--                     Ambrosia, Blackened, Chateau Real et Factory
--                     Smokes (Drew Estate)
--   Mentions          Diesel, Man O'War, Artesano del Tobacco, Viva La
--                     Vida, Henk, Nasser Cigars et Reposado (A.J.
--                     Fernandez) ; La Tribu (Aganorsa Leaf) ; The
--                     Circus (American Caribbean Cigars) ; Paradiso
--                     (Ashton) ; La Chaveta (Casa de Alegria) ;
--                     Silencio (Cohiba USA) ; Playboy (Don Diego) ;
--                     Gilbert de Montsalvat, Conspiracy et EPC (E.P.
--                     Carrillo) ; Altezas Reales 1871 (El Titan de
--                     Bronze)
--
-- ── CE QUE LA RELECTURE A ÉCARTÉ ────────────────────────
-- Plus de cinq ans sans trace, ou arrêtée : La Mia (rien après 2013,
-- et ligne de Casa Fernandez, sans lien avec A.J. Fernandez), Wynwood
-- Hills (derniers textes de 2018 et 2019), The Repeater (aucune vente
-- datée), MUWAT (arrêtée en janvier 2022). Ce qu'une fiche disait déjà
-- reste où il est : Bouncer, Parcero, Buena Vista, Beast, Liga
-- Undercrown, Bahia Blu, Bahia Maduro, Rosa Nicaragua, Flor de
-- D'Crossier et Ferruh Karakasli ne sont pas répétés ; ADV est la forme
-- courte qu'ADVentura emploie elle-même. Silencio n'est pas une ligne de
-- Cohiba USA mais le nom européen de toute la marque : il passe en
-- paragraphe.
--
-- ── À CORRIGER DANS LES FICHES HÔTES ────────────────────
-- Trois fiches disent encore ce que les lignes ajoutées contredisent :
-- Ashton (chaque cigare roulé chez Fuente, alors que San Cristobal l'est
-- à Estelí, chez les Garcia de My Father) ; Aging Room (tout roulé à la
-- Tabacalera Palma, alors que La Bohème l'est chez A.J. Fernandez) ; CLE
-- Cigar Company (Danlí). Le paragraphe ou la ligne l'écrit tel quel, et
-- la correction du champ `factory` viendra avec celle de Vegas de
-- Santiago.
--
-- ── DIVERGENCES ÉCRITES ─────────────────────────────────
-- Cachitos, 2018 ou 2019, usine Plasencia puis Barreda Cigars ; JFR,
-- 2005 au tri, 2011 à l'article de 2019 (2011 est écrit) ; Rancho Luna
-- et Tatascan, CLE Cigar Company puis JRE Tobacco (2015 ou 2016) ;
-- Casa Cuba, medium ou medium-corsée selon Cigar Coop en 2014 ou un
-- détaillant en octobre 2026 ; Back2Back, présentée en juillet 2018 ou
-- lancée en octobre 2018 ; Gilbert de Montsalvat, chez Casa Carrillo
-- pour l'édition 15 Years et à Tabacalera Diaz Cabrera pour la Signature.
--
-- Rejouable : chaque ajout est gardé par un LOCATE (le paragraphe, le
-- fragment de source) ou par le nom de la ligne ; la gamme est relue en
-- base et réécrite en littéral dans chaque langue ; sceaux `machine`.
-- ════════════════════════════════════════════════════════

-- ── 1502 Cigars — gamme : Cachitos ──
UPDATE `brands` SET
  `gamme` = '[{"name":"1502 Emerald","color":"#2E6B4A","force":"Medium","story":"L''émeraude — la ligne d''entrée, par la couleur.","vitolas":[],"wrapper":"Non divulguée"},{"name":"1502 Ruby","color":"#8B1A1A","force":"Medium-Full","story":"Le rubis.","vitolas":[],"wrapper":"Non divulguée"},{"name":"1502 Black Gold","color":"#2E2E2E","force":"Full","story":"L''or noir — le plus corsé des trois.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Cachitos","color":"#8B5A2B","force":null,"wrapper":"Nicaragua, Connecticut Shade","vitolas":[],"story":"Ligne de Global Premium Cigars que Enrique Sánchez Icaza dit séparée de la marque 1502 : un petit-robusto 4½ x 50, cape nicaraguayenne sur liant hondurien, présenté à l''IPCPR de 2018, mais daté de 2019 par cigarandspirits.com en avril 2025. Une seconde version à cape Connecticut Shade (4 x 50), roulée chez Barreda Cigars à Estelí, est sortie en avril 2025 ; l''usine nommée en 2018 était Plasencia."}]',
  `gamme_en` = '[{"name":"1502 Emerald","color":"#2E6B4A","force":"Medium","story":"The emerald — the entry line, by colour.","vitolas":[],"wrapper":"Undisclosed"},{"name":"1502 Ruby","color":"#8B1A1A","force":"Medium-Full","story":"The ruby.","vitolas":[],"wrapper":"Undisclosed"},{"name":"1502 Black Gold","color":"#2E2E2E","force":"Full","story":"Black gold — the fullest of the three.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Cachitos","color":"#8B5A2B","force":null,"wrapper":"Nicaragua, Connecticut Shade","vitolas":[],"story":"A Global Premium Cigars line that Enrique Sánchez Icaza says is separate from the 1502 brand: a 4½ x 50 petit-robusto with a Nicaraguan wrapper over a Honduran binder, presented at the 2018 IPCPR but dated to 2019 by cigarandspirits.com in April 2025. A second version with a Connecticut Shade wrapper (4 x 50), rolled at Barreda Cigars in Estelí, came out in April 2025; the factory named in 2018 was Plasencia."}]',
  `gamme_es` = '[{"name":"1502 Emerald","color":"#2E6B4A","force":"Medium","story":"La esmeralda — la línea de entrada, por el color.","vitolas":[],"wrapper":"No divulgada"},{"name":"1502 Ruby","color":"#8B1A1A","force":"Medium-Full","story":"El rubí.","vitolas":[],"wrapper":"No divulgada"},{"name":"1502 Black Gold","color":"#2E2E2E","force":"Full","story":"El oro negro — el más fuerte de los tres.","vitolas":[],"wrapper":"No divulgada"},{"name":"Cachitos","color":"#8B5A2B","force":null,"wrapper":"Nicaragua, Connecticut Shade","vitolas":[],"story":"Línea de Global Premium Cigars que, según Enrique Sánchez Icaza, está separada de la marca 1502: un petit-robusto de 4½ x 50, con capa nicaragüense sobre capote hondureño, presentado en la IPCPR de 2018, pero fechado en 2019 por cigarandspirits.com en abril de 2025. Una segunda versión con capa Connecticut Shade (4 x 50), torcida en Barreda Cigars, en Estelí, salió en abril de 2025; la fábrica nombrada en 2018 era Plasencia."}]',
  `gamme_de` = '[{"name":"1502 Emerald","color":"#2E6B4A","force":"Medium","story":"Der Smaragd — die Einstiegslinie, nach Farbe.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"1502 Ruby","color":"#8B1A1A","force":"Medium-Full","story":"Der Rubin.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"1502 Black Gold","color":"#2E2E2E","force":"Full","story":"Schwarzes Gold — die kräftigste der drei.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Cachitos","color":"#8B5A2B","force":null,"wrapper":"Nicaragua, Connecticut Shade","vitolas":[],"story":"Eine Linie von Global Premium Cigars, die Enrique Sánchez Icaza als getrennt von der Marke 1502 bezeichnet: ein Petit-Robusto im Format 4½ x 50 mit nicaraguanischem Deckblatt über honduranischem Umblatt, vorgestellt auf der IPCPR 2018, von cigarandspirits.com im April 2025 jedoch auf 2019 datiert. Eine zweite Version mit Deckblatt Connecticut Shade (4 x 50), bei Barreda Cigars in Estelí gerollt, erschien im April 2025; die 2018 genannte Fabrik war Plasencia."}]',
  `gamme_zh` = '[{"name":"1502 Emerald","color":"#2E6B4A","force":"Medium","story":"祖母绿——按颜色排序的入门款。","vitolas":[],"wrapper":"未公开"},{"name":"1502 Ruby","color":"#8B1A1A","force":"Medium-Full","story":"红宝石。","vitolas":[],"wrapper":"未公开"},{"name":"1502 Black Gold","color":"#2E2E2E","force":"Full","story":"黑金——三者中最浓的一款。","vitolas":[],"wrapper":"未公开"},{"name":"Cachitos","color":"#8B5A2B","force":null,"wrapper":"尼加拉瓜，Connecticut Shade","vitolas":[],"story":"Global Premium Cigars旗下产品线，Enrique Sánchez Icaza称其独立于1502品牌：petit-robusto规格，4½ x 50，茄衣产自尼加拉瓜，茄套产自洪都拉斯，于2018年在IPCPR上亮相，但cigarandspirits.com在2025年4月将其记为2019年。第二个版本采用Connecticut Shade茄衣（4 x 50），在Estelí的Barreda Cigars卷制，于2025年4月推出；2018年所提及的工厂为Plasencia。"}]',
  `gamme_ar` = '[{"name":"1502 Emerald","color":"#2E6B4A","force":"Medium","story":"الزمرّد — خطّ الدخول، باللون.","vitolas":[],"wrapper":"غير معلن"},{"name":"1502 Ruby","color":"#8B1A1A","force":"Medium-Full","story":"الياقوت.","vitolas":[],"wrapper":"غير معلن"},{"name":"1502 Black Gold","color":"#2E2E2E","force":"Full","story":"الذهب الأسود — الأقوى بين الثلاثة.","vitolas":[],"wrapper":"غير معلن"},{"name":"Cachitos","color":"#8B5A2B","force":null,"wrapper":"نيكاراغوا، Connecticut Shade","vitolas":[],"story":"خط من Global Premium Cigars يقول Enrique Sánchez Icaza إنه منفصل عن علامة 1502: petit-robusto بمقاس 4½ x 50، غلافه نيكاراغوي فوق غلاف داخلي هندوراسي، عُرض في IPCPR لعام 2018، لكنّ cigarandspirits.com أرّخه بعام 2019 في أبريل 2025. وصدرت نسخة ثانية بغلاف Connecticut Shade (4 x 50)، لُفّت لدى Barreda Cigars في Estelí، في أبريل 2025؛ وكان المصنع الذي ذُكر اسمه عام 2018 هو Plasencia."}]',
  `source` = IF(LOCATE('globalpremiumcigars.com « Our Cigars » (lue en octobre 2026 ', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'globalpremiumcigars.com « Our Cigars » (lue en octobre 2026 : Cachitos parmi les cigares de la maison ; cape Nicaragua, liant Honduras, tripe Nicaragua et Honduras) ; cigar-coop.com « Cigar News: 1502 Cigars to Release Cachitos at 2018 IPCPR » (juillet 2018 : nouvelle ligne de Global Premium Cigars, séparée de la marque 1502 selon Enrique Sánchez Icaza ; format 4½ x 50 ; fabriquée à l''usine Plasencia d''Estelí ; présentée à l''IPCPR de 2018) ; cigarandspirits.com « GPC Expands CACHITOS Line-Up with Connecticut Release » (9 avril 2025 : version Connecticut, 4 x 50, faite à l''usine Barreda d''Estelí ; marque introduite en 2019) ; cigar-coop.com « PCA 2025: Global Premium Cigars 1502 » (30 avril 2025 : Cachitos lancée en 2018 par Global Premium Cigars ; seconde version à cape Connecticut Shade)')),
  `updated_at` = NOW()
 WHERE `name` = '1502 Cigars';

-- ── A.J. Fernandez — paragraphe : Reposado, Henk, Artesano del Tobacco, Diesel, Man O'War, Nasser Cigars, Viva La Vida, gamme : San Lotano ──
UPDATE `brands` SET
  `history` = IF(LOCATE('En octobre 2026, Fernández roule aussi des noms qui ne sont ', `history`) > 0, `history`, CONCAT(`history`, '

', 'En octobre 2026, Fernández roule aussi des noms qui ne sont pas les siens. Diesel et Man O''War, lancées en 2009 pour Cigars International, sortent de ses ateliers ; Diesel est passée en 2021 chez Forged Cigar Company, et sa ligne Uncaged, en boutique depuis août 2026, est faite par Fernández à Estelí. Artesano del Tobacco (aussi écrit Artesano del Tabaco) est aux frères Billy et Gus Fakih, qui y ont lancé Viva La Vida en 2019. Henk est à Heiko Poerz, monté avec Fernández et Didier Houvenaghel ; Nasser Cigars, à Jeffrey Nasser, de Pétion-Ville : son The Goat est roulé par Fernández. Reposado : mélange de Fernández selon Cigars Direct, qui ne dit pas à qui est le nom.')),
  `history_en` = IF(LOCATE('As of October 2026, Fernández also rolls names that are not ', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'As of October 2026, Fernández also rolls names that are not his own. Diesel and Man O''War, launched in 2009 for Cigars International, come out of his factories; Diesel moved in 2021 to Forged Cigar Company, and its Uncaged line, in shops since August 2026, is made by Fernández in Estelí. Artesano del Tobacco (also written Artesano del Tabaco) belongs to the brothers Billy and Gus Fakih, who launched Viva La Vida under that name in 2019. Henk belongs to Heiko Poerz, set up with Fernández and Didier Houvenaghel; Nasser Cigars belongs to Jeffrey Nasser, of Pétion-Ville: its The Goat is rolled by Fernández. Reposado: a Fernández blend according to Cigars Direct, which does not say whose name it is.')),
  `history_es` = IF(LOCATE('En octubre de 2026, Fernández también tuerce nombres que no ', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'En octubre de 2026, Fernández también tuerce nombres que no son suyos. Diesel y Man O''War, lanzadas en 2009 para Cigars International, salen de sus fábricas; Diesel pasó en 2021 a Forged Cigar Company, y su línea Uncaged, en tiendas desde agosto de 2026, la hace Fernández en Estelí. Artesano del Tobacco (escrito también Artesano del Tabaco) pertenece a los hermanos Billy y Gus Fakih, que lanzaron Viva La Vida bajo ese nombre en 2019. Henk pertenece a Heiko Poerz, montado con Fernández y Didier Houvenaghel; Nasser Cigars, a Jeffrey Nasser, de Pétion-Ville: su The Goat lo tuerce Fernández. Reposado: mezcla de Fernández según Cigars Direct, que no dice de quién es el nombre.')),
  `history_de` = IF(LOCATE('Im Oktober 2026 dreht Fernández auch Namen, die nicht seine ', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Im Oktober 2026 dreht Fernández auch Namen, die nicht seine eigenen sind. Diesel und Man O''War, 2009 für Cigars International auf den Markt gebracht, kommen aus seinen Fabriken; Diesel ist 2021 zu Forged Cigar Company gewechselt, und Diesels Linie Uncaged, seit August 2026 in den Geschäften, wird von Fernández in Estelí gefertigt. Artesano del Tobacco (auch Artesano del Tabaco geschrieben) gehört den Brüdern Billy und Gus Fakih, die unter diesem Namen 2019 Viva La Vida einführten. Henk gehört Heiko Poerz und wurde mit Fernández und Didier Houvenaghel aufgebaut; Nasser Cigars gehört Jeffrey Nasser aus Pétion-Ville: Sein The Goat wird von Fernández gedreht. Reposado: eine Mischung von Fernández laut Cigars Direct, das nicht angibt, wem der Name gehört.')),
  `history_zh` = IF(LOCATE('截至2026年10月，Fernández还为并非属于自己的名号卷制雪茄。Diesel与Man O''War于2009年为C', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', '截至2026年10月，Fernández还为并非属于自己的名号卷制雪茄。Diesel与Man O''War于2009年为Cigars International推出，均出自其工厂；Diesel于2021年转至Forged Cigar Company旗下，其Uncaged产品线自2026年8月起在门店有售，由Fernández在Estelí制作。Artesano del Tobacco（亦写作Artesano del Tabaco）归Billy与Gus Fakih兄弟所有，他们于2019年在该名号下推出Viva La Vida。Henk归Heiko Poerz所有，由其与Fernández及Didier Houvenaghel共同组建；Nasser Cigars归来自Pétion-Ville的Jeffrey Nasser所有，其The Goat由Fernández卷制。Reposado：据Cigars Direct称是Fernández的配方，而Cigars Direct并未说明这个名号归谁所有。')),
  `history_ar` = IF(LOCATE('حتى أكتوبر 2026، يلفّ Fernández كذلك أسماءً ليست له. أما الا', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'حتى أكتوبر 2026، يلفّ Fernández كذلك أسماءً ليست له. أما الاسمان Diesel وMan O''War، اللذان أُطلقا عام 2009 لصالح Cigars International، فيخرجان من مصانعه؛ وانتقل Diesel عام 2021 إلى Forged Cigar Company، وخطه Uncaged، المتوفر في المتاجر منذ أغسطس 2026، يصنعه Fernández في Estelí. ويعود الاسم Artesano del Tobacco (ويُكتب أيضًا Artesano del Tabaco) إلى الأخوين Billy وGus Fakih، اللذين أطلقا تحت هذا الاسم Viva La Vida عام 2019. ويعود Henk إلى Heiko Poerz، وقد أُنشئ بالاشتراك مع Fernández وDidier Houvenaghel؛ ويعود Nasser Cigars إلى Jeffrey Nasser من Pétion-Ville، ويلفّ Fernández The Goat الخاص به. أما Reposado فمزيج من تركيب Fernández بحسب Cigars Direct، التي لا تذكر لمن يعود الاسم.')),
  `gamme` = '[{"name":"New World","color":"#5C4033","force":"Full","story":"L''assemblage qui a fait connaître la maison sous son propre nom. Cape mexicaine sombre, fumée épaisse, notes de café brûlé et de poivre noir — puissant sans être agressif, ce qui est précisément la signature de la maison.","vitolas":["Robusto","Toro"],"wrapper":"San Andrés Maduro"},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","story":"Le registre médium de la maison, plus boisé et plus sec. Celui qu''on donne à qui trouve New World trop dense, et qui montre que la force n''a jamais été le sujet.","vitolas":["Toro"],"wrapper":"Habano Rosado"},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","story":"2016 — une ligne de la maison, que le recensement de cet atlas prenait pour une marque à part.","vitolas":[],"wrapper":"Habano d''Équateur"},{"name":"Días de Gloria","color":"#4A3728","force":"Full","story":"2020 — les jours de gloire : un puro nicaraguayen des fermes de la maison.","vitolas":[],"wrapper":"Puro nicaraguayen"},{"name":"Sosa","color":"#6B4226","force":"Medium-Full","story":"Les marques de la famille Sosa — Sosa Classic, Imperio Cubano —, rachetées en décembre 2016 et roulées au Nicaragua depuis janvier 2017. Elles sortaient jusque-là de la fabrique n° 4 d''Arturo Fuente, où Juan Sosa assemble depuis 1997. Le recensement de cet atlas prenait Sosa pour une maison dominicaine.","vitolas":[],"wrapper":"Non divulguée"},{"name":"San Lotano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano, Connecticut ou Maduro","vitolas":[],"story":"Relancée à l''été 2010 d''après Wikipedia, du nom, dit Fernández, d''une marque de sa famille à Cuba avant la révolution. En octobre 2022, la marque compte quatre lignes — Requiem Habano, Requiem Connecticut, Requiem Maduro et The Bull — que Cuenca Cigars range du médium-corsé au corsé."}]',
  `gamme_en` = '[{"name":"New World","color":"#5C4033","force":"Full","story":"The blend that made the house known under its own name. Dark Mexican wrapper, thick smoke, notes of burnt coffee and black pepper — powerful without being aggressive, which is precisely the signature of the house.","vitolas":["Robusto","Toro"],"wrapper":"San Andrés Maduro"},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","story":"The medium register of the house, drier and woodier. The one to hand to anyone who finds New World too dense, and proof that strength was never the point.","vitolas":["Toro"],"wrapper":"Habano Rosado"},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","story":"2016 — a line of the house, which this atlas''s census took for a separate brand.","vitolas":[],"wrapper":"Ecuadorian Habano"},{"name":"Días de Gloria","color":"#4A3728","force":"Full","story":"2020 — the days of glory: a Nicaraguan puro from the house''s farms.","vitolas":[],"wrapper":"Nicaraguan puro"},{"name":"Sosa","color":"#6B4226","force":"Medium-Full","story":"The Sosa family''s brands — Sosa Classic, Imperio Cubano —, bought in December 2016 and rolled in Nicaragua since January 2017. Until then they came out of Arturo Fuente''s factory no. 4, where Juan Sosa has blended since 1997. This atlas''s census took Sosa for a Dominican house.","vitolas":[],"wrapper":"Undisclosed"},{"name":"San Lotano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano, Connecticut or Maduro","vitolas":[],"story":"Relaunched in summer 2010 according to Wikipedia, under the name, says Fernández, of a brand of his family in Cuba before the revolution. As of October 2022, the brand has four lines — Requiem Habano, Requiem Connecticut, Requiem Maduro and The Bull — which Cuenca Cigars classes from medium-full to full."}]',
  `gamme_es` = '[{"name":"New World","color":"#5C4033","force":"Full","story":"La liga que dio a conocer la casa bajo su propio nombre. Capa mexicana oscura, humo espeso, notas de café tostado y pimienta negra — potente sin ser agresivo, que es precisamente la firma de la casa.","vitolas":["Robusto","Toro"],"wrapper":"San Andrés Maduro"},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","story":"El registro medio de la casa, más seco y más amaderado. El que se ofrece a quien encuentra New World demasiado denso, y que demuestra que la fuerza nunca fue el asunto.","vitolas":["Toro"],"wrapper":"Habano Rosado"},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","story":"2016 — una línea de la casa, que el censo de este atlas tomaba por una marca aparte.","vitolas":[],"wrapper":"Habano de Ecuador"},{"name":"Días de Gloria","color":"#4A3728","force":"Full","story":"2020 — los días de gloria: un puro nicaragüense de las fincas de la casa.","vitolas":[],"wrapper":"Puro nicaragüense"},{"name":"Sosa","color":"#6B4226","force":"Medium-Full","story":"Las marcas de la familia Sosa — Sosa Classic, Imperio Cubano —, compradas en diciembre de 2016 y liadas en Nicaragua desde enero de 2017. Salían hasta entonces de la fábrica n.º 4 de Arturo Fuente, donde Juan Sosa liga desde 1997. El censo de este atlas tomaba Sosa por una casa dominicana.","vitolas":[],"wrapper":"No divulgada"},{"name":"San Lotano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano, Connecticut o Maduro","vitolas":[],"story":"Relanzada en el verano de 2010 según Wikipedia, con el nombre, dice Fernández, de una marca de su familia en Cuba antes de la revolución. En octubre de 2022, la marca cuenta con cuatro líneas — Requiem Habano, Requiem Connecticut, Requiem Maduro y The Bull — que Cuenca Cigars clasifica de medio-fuerte a fuerte."}]',
  `gamme_de` = '[{"name":"New World","color":"#5C4033","force":"Full","story":"Der Blend, der das Haus unter eigenem Namen bekannt machte. Dunkles mexikanisches Deckblatt, dichter Rauch, Noten von geröstetem Kaffee und schwarzem Pfeffer — kraftvoll, ohne aggressiv zu sein, und genau das ist die Handschrift des Hauses.","vitolas":["Robusto","Toro"],"wrapper":"San Andrés Maduro"},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","story":"Das mittlere Register des Hauses, trockener und holziger. Die Zigarre für alle, denen New World zu dicht ist — und der Beweis, dass es nie um Stärke ging.","vitolas":["Toro"],"wrapper":"Habano Rosado"},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","story":"2016 — eine Linie des Hauses, die die Zählung dieses Atlas für eine eigene Marke hielt.","vitolas":[],"wrapper":"Ecuadorianisches Habano"},{"name":"Días de Gloria","color":"#4A3728","force":"Full","story":"2020 — die Tage des Ruhms: ein nicaraguanischer Puro von den Farmen des Hauses.","vitolas":[],"wrapper":"Nicaraguanischer Puro"},{"name":"Sosa","color":"#6B4226","force":"Medium-Full","story":"Die Marken der Familie Sosa — Sosa Classic, Imperio Cubano —, im Dezember 2016 gekauft und seit Januar 2017 in Nicaragua gerollt. Bis dahin kamen sie aus der Fabrik Nr. 4 von Arturo Fuente, wo Juan Sosa seit 1997 blendet. Die Zählung dieses Atlas hielt Sosa für ein dominikanisches Haus.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"San Lotano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano / Connecticut / Maduro","vitolas":[],"story":"Neu aufgelegt im Sommer 2010 laut Wikipedia, unter dem Namen, so Fernández, einer Marke seiner Familie auf Kuba vor der Revolution. Im Oktober 2022 zählt die Marke vier Linien — Requiem Habano, Requiem Connecticut, Requiem Maduro und The Bull —, die Cuenca Cigars von mittelkräftig bis kräftig einstuft."}]',
  `gamme_zh` = '[{"name":"New World","color":"#5C4033","force":"Full","story":"让这家企业以自己名义为人所知的配方。深色墨西哥茄衣，烟雾厚实，带焦咖啡与黑胡椒气息——浓郁而不咄咄逼人，这正是这家企业的签名。","vitolas":["Robusto","Toro"],"wrapper":"San Andrés Maduro"},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","story":"这家企业的中度之作，更干、更偏木质。适合觉得新世界过于厚重的人，也证明力度从来不是重点。","vitolas":["Toro"],"wrapper":"Habano Rosado"},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","story":"2016年——公司的一条线，本图集的普查曾把它当作独立品牌。","vitolas":[],"wrapper":"厄瓜多尔 Habano"},{"name":"Días de Gloria","color":"#4A3728","force":"Full","story":"2020年——光荣岁月：来自公司自家农场的尼加拉瓜纯料。","vitolas":[],"wrapper":"尼加拉瓜纯料"},{"name":"Sosa","color":"#6B4226","force":"Medium-Full","story":"索萨家族的品牌——Sosa Classic、Imperio Cubano——2016年12月买下，2017年1月起在尼加拉瓜卷制。此前出自 Arturo Fuente 的四号厂，胡安·索萨自1997年起在那里调配。本图集的普查曾把 Sosa 当作一家多米尼加公司。","vitolas":[],"wrapper":"未公开"},{"name":"San Lotano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano、Connecticut或Maduro","vitolas":[],"story":"据Wikipedia，该系列于2010年夏季重新推出，其名称据Fernández称取自其家族在革命前于古巴拥有的品牌。2022年10月，该品牌共有四条产品线——Requiem Habano、Requiem Connecticut、Requiem Maduro与The Bull——Cuenca Cigars将其力度划为从中等偏浓到浓郁。"}]',
  `gamme_ar` = '[{"name":"New World","color":"#5C4033","force":"Full","story":"الخلطة التي عرّفت بالدار باسمها هي. غلاف مكسيكي داكن، دخان كثيف، ونفحات قهوة محروقة وفلفل أسود — قوّة دون عدوانية، وهذا تحديداً توقيع الدار.","vitolas":["Robusto","Toro"],"wrapper":"San Andrés Maduro"},{"name":"Bellas Artes","color":"#8B6914","force":"Medium","story":"المستوى المتوسط للدار، أكثر جفافاً وخشبية. يُقدَّم لمن يجد نيو وورلد ثقيلاً، ويثبت أن القوّة لم تكن يوماً هي الغاية.","vitolas":["Toro"],"wrapper":"Habano Rosado"},{"name":"Enclave","color":"#8B3A1E","force":"Medium-Full","story":"2016 — خطّ من خطوط الدار، كان إحصاء هذا الأطلس يحسبه علامة مستقلّة.","vitolas":[],"wrapper":"هابانو إكوادوري"},{"name":"Días de Gloria","color":"#4A3728","force":"Full","story":"2020 — أيّام المجد: سيجار نيكاراغوي خالص من مزارع الدار.","vitolas":[],"wrapper":"نيكاراغوي خالص"},{"name":"Sosa","color":"#6B4226","force":"Medium-Full","story":"علامات عائلة سوسا — Sosa Classic وImperio Cubano — اشتُريت في كانون الأوّل/ديسمبر 2016 وتُلفّ في نيكاراغوا منذ كانون الثاني/يناير 2017. كانت تخرج حتى ذلك الحين من مصنع Arturo Fuente رقم 4، حيث يمزج خوان سوسا منذ 1997. وكان إحصاء هذا الأطلس يحسب Sosa دارًا دومينيكية.","vitolas":[],"wrapper":"غير معلن"},{"name":"San Lotano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano، Connecticut أو Maduro","vitolas":[],"story":"أُعيد إطلاقه في صيف 2010 بحسب Wikipedia، بالاسم الذي يقول Fernández إنه اسم علامة كانت لعائلته في كوبا قبل الثورة. وفي أكتوبر 2022، تضم العلامة أربعة خطوط — Requiem Habano وRequiem Connecticut وRequiem Maduro وThe Bull — تصنّفها Cuenca Cigars من متوسط-قوي إلى قوي."}]',
  `mentions` = '["Reposado","Henk","Artesano del Tobacco","Diesel","Man O''War","Nasser Cigars","Viva La Vida"]',
  `source` = IF(LOCATE('en.wikipedia.org « A. J. Fernandez Cigars » (lue en octobre ', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'en.wikipedia.org « A. J. Fernandez Cigars » (lue en octobre 2026 : Man O''War introduite aux États-Unis en 2009 et Diesel lancée la même année, faites par A.J. Fernandez pour la vente de Cigars International ; San Lotano relancée à l''été 2010) ; cigar-coop.com « Summer of 21 Report: Forged Cigar Company » (15 septembre 2021 : Diesel parmi les cinq marques passées à Forged Cigar Company, mélangée par A.J. Fernandez à Estelí) ; cigaraficionado.com « Diesel Uncaged Line in Cigar Shops Now » (14 août 2026 : ligne Uncaged de Diesel annoncée par Scandinavian Tobacco Group, faite à Estelí par A.J. Fernandez, en boutique en août) ; bespokeunit.com « Man O'' War Armada » (8 mai 2017, mise à jour en novembre 2024 : Man O''War produite par A.J. Fernandez à son usine d''Ocotal) ; cigarscity.com « Man O'' War Cigars » (lue en octobre 2026 : plusieurs formats en stock, mélange attribué à A.J. Fernandez) ; cigaraficionado.com « Former NYC Retailers Create Cigar Brand » (30 mai 2019 : Artesano del Tabaco aux frères Billy et Gus Fakih ; Viva la Vida lancée aux États-Unis en mars 2019, faite par A.J. Fernandez en Nicaragua) ; premiumcigars.org « Playing the Long Game: Artesano del Tobacco » (17 juin 2026 : marque des frères Fakih, cigares d''A.J. Fernandez à Estelí ; lignes Viva La Vida, El Pulpo et Viva La Vida Connecticut) ; luxurycigarclub.com « Henk Maori » (lue en octobre 2026 : Henk, marque de Heiko Poerz, montée avec l''aide d''A.J. Fernandez et de Didier Houvenaghel ; stock roulé en 2020) ; cigarworld.de « Henk Maori Haka » (lue en octobre 2026, version anglaise du site : A.J. Fernández partenaire, tabac nicaraguayen, roulé à la main en longfiller) ; oakglentobacconist.com « Nasser The Goat by AJ Fernandez » (3 novembre 2024 : Jeff Nasser, propriétaire du lounge de Pétion-Ville en Haïti ; mélange fait et distribué par A.J. Fernandez) ; kohnhed.com « Krazy Katman''s Bargain Basement Vol. 10 ~ AJ Fernandez Nasser the Goat Maduro » (28 août 2026 : The Goat de Nasser roulé à Tabacalera AJ Fernandez Cigars de Nicaragua, Estelí) ; cigarsdirect.com « Reposado 96 Stock Blend » (lue en octobre 2026 : trois versions, mélange d''Abdel J. Fernandez, faites à Estelí ; propriétaire du nom non dit) ; cigarworld.de « Reposado » (lue en octobre 2026, version anglaise du site : trois versions Estate Blend, Connecticut, Maduro et Colorado, classées sous Nicaragua) ; cigaraficionado.com « San Lotano Series From A.J. Fernandez Gets New Packaging » (18 octobre 2022 : quatre lignes, Requiem Habano, Requiem Connecticut, Requiem Maduro et The Bull ; marque d''A.J. Fernandez Cigar Co.) ; cigaraficionado.com « San Lotano » (page de marque, lue en octobre 2026 : le nom vient, dit Fernandez, de la marque de sa famille à Cuba avant la révolution) ; cuencacigars.com « Discover the Rich Flavors of AJ Fernandez San Lotano Cigars » (1er août 2024 : cape Habano du Brésil, Maduro San Andrés ou Connecticut d''Équateur ; médium-corsé à corsé)')),
  `updated_at` = NOW()
 WHERE `name` = 'A.J. Fernandez';

-- ── Aganorsa Leaf — paragraphe : La Tribu, gamme : Lunatic, JFR ──
UPDATE `brands` SET
  `history` = IF(LOCATE('La Tribu appartient à Atlantic Cigar Company, détaillant amé', `history`) > 0, `history`, CONCAT(`history`, '

', 'La Tribu appartient à Atlantic Cigar Company, détaillant américain : un blog la disait en août 2013 vendue, à sa connaissance, par ce seul détaillant, avec une cape Habano d''Équateur. En octobre 2026, la page d''Atlantic Cigar donne une La Tribu Robusto de République dominicaine, et attribue à Aganorsa Leaf la Serie de Couleurs. Son Noir, un Toro 6 x 56 de tabac nicaraguayen, vient de cigares restés un an dans la salle de vieillissement d''Aganorsa Leaf, orphelins à la suite de ce que le détaillant appelle des histoires de politique du cigare.')),
  `history_en` = IF(LOCATE('La Tribu belongs to Atlantic Cigar Company, an American reta', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'La Tribu belongs to Atlantic Cigar Company, an American retailer: a blog said in August 2013 that it was sold, as far as the blog knew, by that retailer alone, with an Ecuadorian Habano wrapper. In October 2026, the Atlantic Cigar page gives a La Tribu Robusto from the Dominican Republic, and attributes the Serie de Couleurs to Aganorsa Leaf. Its Noir, a Toro 6 x 56 of Nicaraguan tobacco, comes from cigars that stayed a year in Aganorsa Leaf''s ageing room, orphaned as a result of what the retailer calls stories of cigar politics.')),
  `history_es` = IF(LOCATE('La Tribu pertenece a Atlantic Cigar Company, minorista estad', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'La Tribu pertenece a Atlantic Cigar Company, minorista estadounidense: un blog decía en agosto de 2013 que la vendía, hasta donde sabía, únicamente ese minorista, con una capa Habano de Ecuador. En octubre de 2026, la página de Atlantic Cigar ofrece un La Tribu Robusto de República Dominicana y atribuye a Aganorsa Leaf la Serie de Couleurs. Su Noir, un Toro 6 x 56 de tabaco nicaragüense, procede de puros que permanecieron un año en la sala de envejecimiento de Aganorsa Leaf, huérfanos a raíz de lo que el minorista llama historias de política del puro.')),
  `history_de` = IF(LOCATE('La Tribu gehört Atlantic Cigar Company, einem US-amerikanisc', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'La Tribu gehört Atlantic Cigar Company, einem US-amerikanischen Einzelhändler: Ein Blog gab im August 2013 an, La Tribu werde nach seinem Wissen nur von diesem einen Einzelhändler verkauft, mit einem Habano-Deckblatt aus Ecuador. Im Oktober 2026 führt die Seite von Atlantic Cigar eine La Tribu Robusto aus der Dominikanischen Republik auf und schreibt Aganorsa Leaf die Serie de Couleurs zu. Ihr Noir, ein Toro 6 x 56 aus nicaraguanischem Tabak, stammt von Zigarren, die ein Jahr im Reiferaum von Aganorsa Leaf lagen und infolge dessen, was der Händler Geschichten der Zigarrenpolitik nennt, verwaist sind.')),
  `history_zh` = IF(LOCATE('La Tribu归Atlantic Cigar Company所有，这是一家美国零售商：一个博客在2013年八月称，据其', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', 'La Tribu归Atlantic Cigar Company所有，这是一家美国零售商：一个博客在2013年八月称，据其所知，La Tribu仅由这一家零售商销售，茄衣为厄瓜多尔Habano。2026年十月，Atlantic Cigar的页面列出一款来自多米尼加共和国的La Tribu Robusto，并将Serie de Couleurs归于Aganorsa Leaf。其Noir为Toro 6 x 56，采用尼加拉瓜烟草，来自在Aganorsa Leaf的醇化室中存放了一年的雪茄，这些雪茄因零售商所说的雪茄政治方面的那些事而成了孤儿。')),
  `history_ar` = IF(LOCATE('تعود La Tribu إلى Atlantic Cigar Company، وهي تاجر تجزئة أمر', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'تعود La Tribu إلى Atlantic Cigar Company، وهي تاجر تجزئة أمريكي: ذكرت مدونة في أغسطس 2013 أنها تُباع، على حد علم المدونة، لدى هذا التاجر وحده، بغلاف Habano من الإكوادور. وفي أكتوبر 2026، تعرض صفحة Atlantic Cigar سيجار La Tribu Robusto من جمهورية الدومينيكان، وتنسب Serie de Couleurs إلى Aganorsa Leaf. أما Noir فيها، وهو Toro 6 x 56 من تبغ نيكاراغوي، فيأتي من سيجار بقي سنة في غرفة التعتيق التابعة لـ Aganorsa Leaf، وقد صار يتيمًا إثر ما يسميه التاجر قصص سياسة السيجار.')),
  `gamme` = '[{"name":"Aganorsa Leaf Original","color":"#7B3F00","force":"Full","story":"Cent pour cent tabac maison, de la tripe à la cape. C''est l''argument entier de la marque : goûter le terroir de Jalapa sans intermédiaire, en pleine force.","vitolas":["Robusto"],"wrapper":"Corojo 99"},{"name":"Signature Selection","color":"#A0522D","force":"Medium","story":"Le même tabac dans un assemblage plus retenu, où le sucré de la feuille passe devant la puissance. Le meilleur point d''entrée dans le style de la maison.","vitolas":["Toro"],"wrapper":"Corojo 99"},{"name":"Condega","color":"#6B4226","force":"Medium","story":"Une marque rachetée en 2002 avec Tropical Tobacco, achetée à Pedro Martín — le nom d''une ville et d''un terroir entre Estelí et Jalapa. Le recensement de cet atlas la prenait pour une maison.","vitolas":[],"wrapper":"Puro nicaraguayen"},{"name":"Lunatic","color":"#A0522D","force":null,"wrapper":"Corojo Aganorsa, San Andrés","vitolas":[],"story":"Extension de JFR apparue en 2015, d''après deux articles (juin 2019, novembre 2023). En octobre 2026, le site de la maison présente Lunatic Torch, cape Corojo d''Aganorsa et pied brosse, force 3,5 sur 5 selon la maison, en Imagine (5 1/2 x 50), Visionaries (6 1/2 x 52), Dreamlands (6 1/2 x 60) et Mad Folk (4 3/4 x 70) ; la version Maduro, cape San Andrés, a reçu un 10 x 100 annoncé avant le PCA 2023, et les perfectos Loco datent de 2019."},{"name":"JFR","color":"#6B4226","force":null,"wrapper":"San Andrés, Connecticut","vitolas":[],"story":"Le nom abrège Just for Retailers ; la ligne existe depuis 2011, selon un article du 12 juin 2019. En octobre 2026, le site de la maison en montre deux versions sur tripe de la maison : JFR Maduro, cape San Andrés du Mexique, force 4 sur 5 selon la maison, du Robusto au 770 L.E. de 7 x 70, et JFR Connecticut, cape Connecticut d''Équateur, dont un Junior de 4 1/2 x 46 est présenté en avril 2024."}]',
  `gamme_en` = '[{"name":"Aganorsa Leaf Original","color":"#7B3F00","force":"Full","story":"One hundred per cent house tobacco, from filler to wrapper. That is the whole argument of the brand: to taste the Jalapa terroir without an intermediary, at full strength.","vitolas":["Robusto"],"wrapper":"Corojo 99"},{"name":"Signature Selection","color":"#A0522D","force":"Medium","story":"The same tobacco in a more restrained blend, where the sweetness of the leaf comes ahead of the power. The best way into the style of the house.","vitolas":["Toro"],"wrapper":"Corojo 99"},{"name":"Condega","color":"#6B4226","force":"Medium","story":"A brand bought in 2002 with Tropical Tobacco, purchased from Pedro Martín — the name of a town and a terroir between Estelí and Jalapa. This atlas''s census took it for a house.","vitolas":[],"wrapper":"Nicaraguan puro"},{"name":"Lunatic","color":"#A0522D","force":null,"wrapper":"Corojo Aganorsa, San Andrés","vitolas":[],"story":"An extension of JFR that appeared in 2015, according to two articles (June 2019, November 2023). In October 2026, the company''s website presents Lunatic Torch, with a Corojo wrapper from Aganorsa and a brush foot, strength 3.5 out of 5 according to the company, in Imagine (5 1/2 x 50), Visionaries (6 1/2 x 52), Dreamlands (6 1/2 x 60) and Mad Folk (4 3/4 x 70); the Maduro version, with a San Andrés wrapper, received a 10 x 100 announced before PCA 2023, and the Loco perfectos date from 2019."},{"name":"JFR","color":"#6B4226","force":null,"wrapper":"San Andrés, Connecticut","vitolas":[],"story":"The name abbreviates Just for Retailers; the line has existed since 2011, according to an article of 12 June 2019. In October 2026, the company''s website shows two versions on the company''s filler: JFR Maduro, with a San Andrés wrapper from Mexico, strength 4 out of 5 according to the company, from the Robusto to the 770 L.E. of 7 x 70, and JFR Connecticut, with a Connecticut wrapper from Ecuador, of which a Junior of 4 1/2 x 46 is presented in April 2024."}]',
  `gamme_es` = '[{"name":"Aganorsa Leaf Original","color":"#7B3F00","force":"Full","story":"Cien por cien tabaco de la casa, de la tripa a la capa. Ese es el argumento entero de la marca: probar el terruño de Jalapa sin intermediario, a plena fuerza.","vitolas":["Robusto"],"wrapper":"Corojo 99"},{"name":"Signature Selection","color":"#A0522D","force":"Medium","story":"El mismo tabaco en una liga más contenida, donde el dulzor de la hoja pasa por delante de la potencia. La mejor puerta de entrada al estilo de la casa.","vitolas":["Toro"],"wrapper":"Corojo 99"},{"name":"Condega","color":"#6B4226","force":"Medium","story":"Una marca comprada en 2002 con Tropical Tobacco, adquirida a Pedro Martín — el nombre de un pueblo y de un terruño entre Estelí y Jalapa. El censo de este atlas la tomaba por una casa.","vitolas":[],"wrapper":"Puro nicaragüense"},{"name":"Lunatic","color":"#A0522D","force":null,"wrapper":"Corojo Aganorsa, San Andrés","vitolas":[],"story":"Extensión de JFR aparecida en 2015, según dos artículos (junio de 2019, noviembre de 2023). En octubre de 2026, el sitio web de la empresa presenta Lunatic Torch, con capa Corojo de Aganorsa y pie de brocha, fuerza 3,5 sobre 5 según la empresa, en Imagine (5 1/2 x 50), Visionaries (6 1/2 x 52), Dreamlands (6 1/2 x 60) y Mad Folk (4 3/4 x 70); la versión Maduro, con capa San Andrés, recibió un 10 x 100 anunciado antes de la PCA 2023, y los perfectos Loco datan de 2019."},{"name":"JFR","color":"#6B4226","force":null,"wrapper":"San Andrés, Connecticut","vitolas":[],"story":"El nombre abrevia Just for Retailers; la línea existe desde 2011, según un artículo del 12 de junio de 2019. En octubre de 2026, el sitio web de la empresa muestra dos versiones sobre tripa de la empresa: JFR Maduro, con capa San Andrés de México, fuerza 4 sobre 5 según la empresa, del Robusto al 770 L.E. de 7 x 70, y JFR Connecticut, con capa Connecticut de Ecuador, de la que se presenta un Junior de 4 1/2 x 46 en abril de 2024."}]',
  `gamme_de` = '[{"name":"Aganorsa Leaf Original","color":"#7B3F00","force":"Full","story":"Hundert Prozent hauseigener Tabak, von der Einlage bis zum Deckblatt. Das ist das ganze Argument der Marke: das Terroir von Jalapa ohne Zwischenhändler schmecken, in voller Kraft.","vitolas":["Robusto"],"wrapper":"Corojo 99"},{"name":"Signature Selection","color":"#A0522D","force":"Medium","story":"Derselbe Tabak in einem zurückhaltenderen Blend, in dem die Süße des Blattes vor der Kraft steht. Der beste Einstieg in den Stil des Hauses.","vitolas":["Toro"],"wrapper":"Corojo 99"},{"name":"Condega","color":"#6B4226","force":"Medium","story":"Eine Marke, 2002 mit Tropical Tobacco gekauft, erworben von Pedro Martín — der Name einer Stadt und eines Terroirs zwischen Estelí und Jalapa. Die Zählung dieses Atlas hielt sie für ein Haus.","vitolas":[],"wrapper":"Nicaraguanischer Puro"},{"name":"Lunatic","color":"#A0522D","force":null,"wrapper":"Corojo Aganorsa, San Andrés","vitolas":[],"story":"Erweiterung von JFR, die 2015 erschien, laut zwei Artikeln (Juni 2019, November 2023). Im Oktober 2026 präsentiert die Website des Unternehmens Lunatic Torch mit Corojo-Deckblatt von Aganorsa und Besenfuß, Stärke 3,5 von 5 nach Angaben des Unternehmens, in Imagine (5 1/2 x 50), Visionaries (6 1/2 x 52), Dreamlands (6 1/2 x 60) und Mad Folk (4 3/4 x 70); die Version Maduro mit Deckblatt San Andrés erhielt ein 10 x 100, das vor der PCA 2023 angekündigt wurde, und die Perfectos Loco stammen aus dem Jahr 2019."},{"name":"JFR","color":"#6B4226","force":null,"wrapper":"San Andrés, Connecticut","vitolas":[],"story":"Der Name ist eine Abkürzung für Just for Retailers; die Linie besteht seit 2011, laut einem Artikel vom 12. Juni 2019. Im Oktober 2026 zeigt die Website des Unternehmens zwei Versionen auf Einlage des Unternehmens: JFR Maduro mit Deckblatt San Andrés aus Mexiko, Stärke 4 von 5 nach Angaben des Unternehmens, vom Robusto bis zum 770 L.E. in 7 x 70, und JFR Connecticut mit Deckblatt Connecticut aus Ecuador, von der ein Junior in 4 1/2 x 46 im April 2024 vorgestellt wird."}]',
  `gamme_zh` = '[{"name":"Aganorsa Leaf Original","color":"#7B3F00","force":"Full","story":"从茄芯到茄衣，百分之百自家烟叶。这就是这个品牌的全部主张：不经中间人，以全力度品尝哈拉帕的风土。","vitolas":["Robusto"],"wrapper":"Corojo 99"},{"name":"Signature Selection","color":"#A0522D","force":"Medium","story":"同样的烟叶，配方更收敛，烟叶的甜感走在力度之前。进入这家风格的最佳入口。","vitolas":["Toro"],"wrapper":"Corojo 99"},{"name":"Condega","color":"#6B4226","force":"Medium","story":"2002年随 Tropical Tobacco 从佩德罗·马丁手中买下的品牌——一个介于埃斯特利与哈拉帕之间的城镇与产区之名。本图集的普查曾把它当作一家公司。","vitolas":[],"wrapper":"尼加拉瓜纯料"},{"name":"Lunatic","color":"#A0522D","force":null,"wrapper":"Corojo Aganorsa、San Andrés","vitolas":[],"story":"JFR的延伸系列，据两篇文章（2019年六月、2023年十一月）称于2015年问世。2026年十月，该公司官网展示Lunatic Torch：茄衣为Aganorsa的Corojo，刷状脚，据公司称力度为5级制中的3.5级，规格有Imagine（5 1/2 x 50）、Visionaries（6 1/2 x 52）、Dreamlands（6 1/2 x 60）与Mad Folk（4 3/4 x 70）；Maduro版本采用San Andrés茄衣，推出了一款在PCA 2023前宣布的10 x 100，而Loco perfecto可追溯至2019年。"},{"name":"JFR","color":"#6B4226","force":null,"wrapper":"San Andrés、Connecticut","vitolas":[],"story":"名称是Just for Retailers的缩写；据2019年六月12日的一篇文章，该产品线自2011年起存在。2026年十月，该公司官网展示了两个采用该公司茄芯的版本：JFR Maduro，茄衣为产自墨西哥的San Andrés，据公司称力度为5级制中的4级，规格从Robusto到7 x 70的770 L.E.；以及JFR Connecticut，茄衣为产自厄瓜多尔的Connecticut，其中一款4 1/2 x 46的Junior于2024年四月亮相。"}]',
  `gamme_ar` = '[{"name":"Aganorsa Leaf Original","color":"#7B3F00","force":"Full","story":"تبغ الدار مئة في المئة، من الحشوة إلى الغلاف. وهذه حجّة العلامة كاملةً: تذوّق أرض خالابا دون وسيط، وبكامل القوّة.","vitolas":["Robusto"],"wrapper":"Corojo 99"},{"name":"Signature Selection","color":"#A0522D","force":"Medium","story":"التبغ نفسه في خلطة أكثر تحفّظاً، تتقدّم فيها حلاوة الورقة على القوّة. وهو أفضل مدخل إلى أسلوب الدار.","vitolas":["Toro"],"wrapper":"Corojo 99"},{"name":"Condega","color":"#6B4226","force":"Medium","story":"علامةٌ اشتُريت سنة 2002 مع Tropical Tobacco من بيدرو مارتين — اسم بلدة وأرضٍ بين إستيلي وخالابا. وكان إحصاء هذا الأطلس يحسبها دارًا.","vitolas":[],"wrapper":"نيكاراغوي خالص"},{"name":"Lunatic","color":"#A0522D","force":null,"wrapper":"Corojo Aganorsa، San Andrés","vitolas":[],"story":"امتداد لـ JFR ظهر عام 2015، وفقًا لمقالين (يونيو 2019، نوفمبر 2023). وفي أكتوبر 2026، يعرض موقع الشركة Lunatic Torch، بغلاف Corojo من Aganorsa وقدم مبرومة، وبقوة 3.5 من 5 بحسب الشركة، بمقاسات Imagine (5 1/2 x 50) وVisionaries (6 1/2 x 52) وDreamlands (6 1/2 x 60) وMad Folk (4 3/4 x 70)؛ أما نسخة Maduro بغلاف San Andrés فقد حصلت على مقاس 10 x 100 أُعلن عنه قبل PCA 2023، وتعود سيجار Loco من نوع perfecto إلى عام 2019."},{"name":"JFR","color":"#6B4226","force":null,"wrapper":"San Andrés، Connecticut","vitolas":[],"story":"يختصر الاسم عبارة Just for Retailers؛ والخط قائم منذ عام 2011، بحسب مقال بتاريخ 12 يونيو 2019. وفي أكتوبر 2026، يعرض موقع الشركة نسختين على حشوة الشركة: JFR Maduro بغلاف San Andrés من المكسيك، وقوة 4 من 5 بحسب الشركة، من Robusto إلى 770 L.E. بمقاس 7 x 70، وJFR Connecticut بغلاف Connecticut من الإكوادور، يُعرض منه Junior بمقاس 4 1/2 x 46 في أبريل 2024."}]',
  `mentions` = '["La Tribu"]',
  `source` = IF(LOCATE('cigar-coop.com « Cigar Review: JFR Lunatic Maduro 10 x 100 b', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « Cigar Review: JFR Lunatic Maduro 10 x 100 by Aganorsa Leaf » (2023-11-27 : fabricant Aganorsa Leaf, ex-Casa Fernandez, usine Agricola Ganadera Norteña à Estelí ; Lunatic née en 2015 comme extension de JFR ; Lunatic Maduro 10 x 100 en cape San Andrés, annoncé avant le PCA 2023) ; cigar-coop.com « Aganorsa Leaf Adds JFR Connecticut Junior » (2024-04-29 : Aganorsa Leaf produit JFR ; Junior 4 1/2 x 46 présenté au PCA 2024, cape Connecticut d''Équateur, tripe nicaraguayenne) ; blindmanspuff.com « Cigar News: Aganorsa Leaf Announces JFR Lunatic Loco » (2019-06-12 : JFR signifie Just for Retailers et existe depuis 2011, Lunatic depuis 2015 ; perfectos Lunatic Loco, cape Corojo Maduro cultivée à Jalapa) ; aganorsaleaf.com « Accueil » (consulté 2026-10-07 : JFR Maduro, JFR Connecticut et Lunatic Torch au catalogue de la maison ; JFR Connecticut en cape Connecticut d''Équateur sur sous-cape et tripe de la maison) ; aganorsaleaf.com « JFR Maduro » (consulté 2026-10-07 : cape San Andrés du Mexique, tripe nicaraguayenne, force 4 sur 5, formats Robusto à 770 L.E.) ; aganorsaleaf.com « Lunatic Torch » (consulté 2026-10-07 : cape Corojo d''Aganorsa, pied brosse, force 3,5 sur 5, quatre formats) ; atlanticcigar.com « La Tribu Serie de Couleurs NOIR Toro 10-Pack » (consulté 2026-10-07 : Noir 6 x 56 du Nicaragua attribué à Aganorsa Leaf, cigares restés un an dans sa salle de vieillissement, orphelins après des histoires de politique du cigare ; Bleu, Rouge et Verte listés avec le même nom) ; atlanticcigar.com « La Tribu Robusto 20-Pack » (consulté 2026-10-07 : La Tribu développée par Atlantic Cigar Company, origine République dominicaine, cape Habano d''Équateur) ; kohnhed.com « Cigar Review- La Tribu by Atlantic Cigars » (2013-08-30 : cape Habano d''Équateur, vendue à la connaissance du blogueur par le seul Atlantic)')),
  `updated_at` = NOW()
 WHERE `name` = 'Aganorsa Leaf';

-- ── Aging Room — gamme : La Bohème ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Quattro","color":"#8B4513","force":"Medium-Full","story":"La gamme la plus large, aux vitoles nommées en vocabulaire musical — Nodal est musicien de formation. Format carré à la base, ce qui est rare.","vitolas":["Maestro","Concerto","Espressivo"],"wrapper":"Habano"},{"name":"Small Batch","color":"#6B4226","force":"Full","story":"Les séries courtes de la maison, désignées par un code plutôt que par un nom. C''est la gamme qui a fait connaître la marque.","vitolas":["M356","F55"],"wrapper":"Habano"},{"name":"Bin No. 1","color":"#4A2C1A","force":"Medium-Full","story":"Bâtie sur des tabacs de 1999 et 2001 gardés de la vallée du Cibao. Le nom désigne le casier de vieillissement — la marque entière tient dans cette idée.","vitolas":["Bin No. 1"],"wrapper":"Dominicain"},{"name":"Pelo de Oro","color":"#A0522D","force":"Medium","story":"Du nom d''une variété cubaine ancienne, difficile à cultiver et longtemps abandonnée pour cette raison. Lancée en 2016.","vitolas":["Rondo","Mezzo"],"wrapper":"Pelo de Oro"},{"name":"La Bohème","color":"#6B4226","force":"Medium-Full","wrapper":"Connecticut hybride","vitolas":[],"story":"Lancée en 2014 chez Boutique Blends et roulée alors à la Tabacalera Palma, elle revient en janvier 2025 sous le nom Aging Room La Bohème, avec un mélange nouveau fait par A.J. Fernandez au Nicaragua, présenté en décembre 2024 comme medium à full. Cape hybride de graines Broadleaf et Habano cultivées dans la vallée du Connecticut, sous-cape et tripe nicaraguayennes : quatre formats nommés d''après l''opéra de Puccini, Mimi (3 1/2 x 46), Pittore (5 1/8 x 52), Poeta (5 3/4 x 54) et Musico (6 1/4 x 60)."}]',
  `gamme_en` = '[{"name":"Quattro","color":"#8B4513","force":"Medium-Full","story":"The widest range, its vitolas named in musical vocabulary — Nodal trained as a musician. Box-pressed at the base, which is uncommon.","vitolas":["Maestro","Concerto","Espressivo"],"wrapper":"Habano"},{"name":"Small Batch","color":"#6B4226","force":"Full","story":"The house''s short runs, designated by a code rather than a name. This is the range that made the brand known.","vitolas":["M356","F55"],"wrapper":"Habano"},{"name":"Bin No. 1","color":"#4A2C1A","force":"Medium-Full","story":"Built on tobaccos from 1999 and 2001 held back from the Cibao Valley. The name is the ageing bin — the whole brand is in that idea.","vitolas":["Bin No. 1"],"wrapper":"Dominican"},{"name":"Pelo de Oro","color":"#A0522D","force":"Medium","story":"Named for an old Cuban variety, hard to grow and long abandoned for that reason. Launched in 2016.","vitolas":["Rondo","Mezzo"],"wrapper":"Pelo de Oro"},{"name":"La Bohème","color":"#6B4226","force":"Medium-Full","wrapper":"Hybrid Connecticut","vitolas":[],"story":"Launched in 2014 at Boutique Blends and rolled at the time at Tabacalera Palma, it returns in January 2025 under the name Aging Room La Bohème, with a new blend made by A.J. Fernandez in Nicaragua, presented in December 2024 as medium to full. A hybrid wrapper of Broadleaf and Habano seeds grown in the Connecticut Valley, with Nicaraguan binder and filler: four formats named after Puccini''s opera, Mimi (3 1/2 x 46), Pittore (5 1/8 x 52), Poeta (5 3/4 x 54) and Musico (6 1/4 x 60)."}]',
  `gamme_es` = '[{"name":"Quattro","color":"#8B4513","force":"Medium-Full","story":"La gama más amplia, con vitolas nombradas en vocabulario musical: Nodal es músico de formación. De base cuadrada, lo que es raro.","vitolas":["Maestro","Concerto","Espressivo"],"wrapper":"Habano"},{"name":"Small Batch","color":"#6B4226","force":"Full","story":"Las series cortas de la casa, designadas por un código y no por un nombre. Es la gama que dio a conocer la marca.","vitolas":["M356","F55"],"wrapper":"Habano"},{"name":"Bin No. 1","color":"#4A2C1A","force":"Medium-Full","story":"Construida sobre tabacos de 1999 y 2001 guardados del valle del Cibao. El nombre designa el cajón de añejamiento: la marca entera cabe en esa idea.","vitolas":["Bin No. 1"],"wrapper":"Dominicana"},{"name":"Pelo de Oro","color":"#A0522D","force":"Medium","story":"Del nombre de una variedad cubana antigua, difícil de cultivar y por eso mucho tiempo abandonada. Lanzada en 2016.","vitolas":["Rondo","Mezzo"],"wrapper":"Pelo de Oro"},{"name":"La Bohème","color":"#6B4226","force":"Medium-Full","wrapper":"Connecticut híbrida","vitolas":[],"story":"Lanzada en 2014 en Boutique Blends y torcida entonces en la Tabacalera Palma, vuelve en enero de 2025 con el nombre Aging Room La Bohème, con una mezcla nueva hecha por A.J. Fernandez en Nicaragua, presentada en diciembre de 2024 como de fuerza media a fuerte. Capa híbrida de semillas Broadleaf y Habano cultivadas en el valle de Connecticut, capote y tripa nicaragüenses: cuatro formatos que llevan el nombre de la ópera de Puccini, Mimi (3 1/2 x 46), Pittore (5 1/8 x 52), Poeta (5 3/4 x 54) y Musico (6 1/4 x 60)."}]',
  `gamme_de` = '[{"name":"Quattro","color":"#8B4513","force":"Medium-Full","story":"Die breiteste Linie, ihre Vitolas nach musikalischem Vokabular benannt — Nodal ist ausgebildeter Musiker. Im Ansatz box-pressed, was selten ist.","vitolas":["Maestro","Concerto","Espressivo"],"wrapper":"Habano"},{"name":"Small Batch","color":"#6B4226","force":"Full","story":"Die kurzen Serien des Hauses, mit einem Code statt eines Namens bezeichnet. Diese Linie hat die Marke bekannt gemacht.","vitolas":["M356","F55"],"wrapper":"Habano"},{"name":"Bin No. 1","color":"#4A2C1A","force":"Medium-Full","story":"Auf Tabaken von 1999 und 2001 aufgebaut, die aus dem Cibao-Tal zurückgehalten wurden. Der Name bezeichnet das Reifefach — die ganze Marke steckt in diesem Gedanken.","vitolas":["Bin No. 1"],"wrapper":"Dominikanisch"},{"name":"Pelo de Oro","color":"#A0522D","force":"Medium","story":"Benannt nach einer alten kubanischen Sorte, schwer anzubauen und deshalb lange aufgegeben. 2016 herausgebracht.","vitolas":["Rondo","Mezzo"],"wrapper":"Pelo de Oro"},{"name":"La Bohème","color":"#6B4226","force":"Medium-Full","wrapper":"Connecticut hybrid","vitolas":[],"story":"2014 bei Boutique Blends auf den Markt gebracht und damals in der Tabacalera Palma gerollt, kehrt sie im Januar 2025 unter dem Namen Aging Room La Bohème zurück, mit einer neuen Mischung von A.J. Fernandez in Nicaragua, im Dezember 2024 als mittel bis kräftig vorgestellt. Hybrides Deckblatt aus Broadleaf- und Habano-Saatgut, angebaut im Connecticut-Tal, nicaraguanisches Umblatt und nicaraguanische Einlage: vier Formate, benannt nach Puccinis Oper, Mimi (3 1/2 x 46), Pittore (5 1/8 x 52), Poeta (5 3/4 x 54) und Musico (6 1/4 x 60)."}]',
  `gamme_zh` = '[{"name":"Quattro","color":"#8B4513","force":"Medium-Full","story":"最齐全的一条线，尺寸以音乐术语命名——Nodal 出身音乐科班。基本款为方压形制，这并不多见。","vitolas":["Maestro","Concerto","Espressivo"],"wrapper":"Habano"},{"name":"Small Batch","color":"#6B4226","force":"Full","story":"这家的小批量系列，以代号而非名称标示。正是这条线让品牌为人所知。","vitolas":["M356","F55"],"wrapper":"Habano"},{"name":"Bin No. 1","color":"#4A2C1A","force":"Medium-Full","story":"建立在 1999 与 2001 年从西宝谷留存的烟叶之上。名字指的是陈化格——整个品牌的理念都在这个词里。","vitolas":["Bin No. 1"],"wrapper":"多米尼加"},{"name":"Pelo de Oro","color":"#A0522D","force":"Medium","story":"取自一个古老的古巴烟草品种之名，因难以栽培而长期被弃用。2016 年推出。","vitolas":["Rondo","Mezzo"],"wrapper":"Pelo de Oro"},{"name":"La Bohème","color":"#6B4226","force":"Medium-Full","wrapper":"Connecticut杂交种","vitolas":[],"story":"2014年在Boutique Blends推出，当时在Tabacalera Palma卷制；2025年一月以Aging Room La Bohème之名回归，采用A.J. Fernandez在尼加拉瓜制作的新拼配，2024年十二月被介绍为中等至浓郁。茄衣为杂交茄衣，由Broadleaf与Habano种子在Connecticut谷地种植而成，内包叶与茄芯均产自尼加拉瓜：四种规格以Puccini的歌剧命名，分别为Mimi（3 1/2 x 46）、Pittore（5 1/8 x 52）、Poeta（5 3/4 x 54）与Musico（6 1/4 x 60）。"}]',
  `gamme_ar` = '[{"name":"Quattro","color":"#8B4513","force":"Medium-Full","story":"أوسع السلاسل، ومقاساتها مسمّاة بمفردات موسيقية — فنودال موسيقيّ التكوين. وشكلها الأساسي مكبوس مربّع، وهو قليل.","vitolas":["Maestro","Concerto","Espressivo"],"wrapper":"هابانو"},{"name":"Small Batch","color":"#6B4226","force":"Full","story":"دفعات الدار القصيرة، تُسمّى برمز لا باسم. وهي السلسلة التي عرّفت بالعلامة.","vitolas":["M356","F55"],"wrapper":"هابانو"},{"name":"Bin No. 1","color":"#4A2C1A","force":"Medium-Full","story":"مبنيّ على أتبغة من 1999 و2001 احتُفِظ بها من وادي سيباو. والاسم يعني خانة التعتيق — والعلامة كلّها في هذه الفكرة.","vitolas":["Bin No. 1"],"wrapper":"دومينيكي"},{"name":"Pelo de Oro","color":"#A0522D","force":"Medium","story":"باسم صنف كوبي قديم صعب الزراعة، ولهذا هُجر طويلًا. أُطلقت عام 2016.","vitolas":["Rondo","Mezzo"],"wrapper":"بيلو دي أورو"},{"name":"La Bohème","color":"#6B4226","force":"Medium-Full","wrapper":"Connecticut هجين","vitolas":[],"story":"أُطلقت عام 2014 لدى Boutique Blends ولُفّت آنذاك في Tabacalera Palma، وتعود في يناير 2025 تحت اسم Aging Room La Bohème، بخلطة جديدة صنعها A.J. Fernandez في نيكاراغوا، قُدّمت في ديسمبر 2024 على أنها من المتوسط إلى القوي. غلافها هجين من بذور Broadleaf وHabano المزروعة في وادي Connecticut، واللفافة الداخلية والحشوة من نيكاراغوا: أربعة مقاسات سُمّيت نسبةً إلى أوبرا Puccini، وهي Mimi (3 1/2 x 46) وPittore (5 1/8 x 52) وPoeta (5 3/4 x 54) وMusico (6 1/4 x 60)."}]',
  `source` = IF(LOCATE('cigar-coop.com « La Boheme Reintroduced Under Aging Room Cig', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « La Boheme Reintroduced Under Aging Room Cigars » (2024-12-04 : lancée en 2014 chez Boutique Blends et produite à la Tabacalera Palma ; reprise en janvier 2025 chez A.J. Fernandez au Nicaragua ; cape Connecticut de graines Broadleaf et Habano, tripe nicaraguayenne ; quatre formats nommés d''après l''opéra) ; cigardojo.com « Altadis U.S.A. Reintroduces La Boheme Cigar Under Aging Room Brand » (2024-12-04 : annonce d''Altadis U.S.A., produit présenté comme medium à full) ; cigar-coop.com « Aging Room La Bohème Poeta Cigar Review » (2025-10-21 : fabrique A.J. Fernandez au Nicaragua, Poeta 5 3/4 x 54, marque mise de côté après l''arrivée de Rafael Nodal chez Altadis en 2017) ; cigar-coop.com « PCA 2025: Aging Room Cigars » (2025-05-17 : La Bohème et Quattro Nicaragua roulés chez A.J. Fernandez)')),
  `updated_at` = NOW()
 WHERE `name` = 'Aging Room';

-- ── Aladino — gamme : Rancho Luna, Tatascan ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Aladino Corojo","color":"#8B4513","force":"Medium","story":"Cent pour cent corojo cultivé par la famille : une semence d''avant les hybrides, difficile et peu rentable. Fruits secs, bois, cuir, avec une acidité fine que les variétés modernes ont perdue.","vitolas":["Corona","Robusto"],"wrapper":"Corojo authentique"},{"name":"Aladino Maduro","color":"#3E2723","force":"Full","story":"Paru en 2018. Cape maduro de San Andrés, au Mexique — le seul tabac de la gamme qui ne vienne pas des terres de la famille. Sous-cape corojo hondurienne, tripe du Jamastran. Cacao, café, cèdre et poivre noir.","vitolas":["Toro"],"wrapper":"San Andrés (Mexique)"},{"name":"Rancho Luna","color":"#8B5A2B","force":null,"wrapper":"Habano, Connecticut","vitolas":[],"story":"Présentée en juillet 2015 avec Aladino et Tatascan sous la bannière de CLE Cigar Company, puis reprise par JRE Tobacco avec effet au 1er février 2016, d''après cigar-coop.com. Relancée en janvier 2025 sous le nom Rancho Luna by Aladino, en bundles de vingt : Red à cape Habano et Blue à cape de graine Connecticut, en Toro 6 x 52 roulé à la Fábrica de Puros Aladino ; en octobre 2026, le site de la maison parle de capes Habano et Maduro sur binder de Corojo authentique."},{"name":"Tatascan","color":"#8B5A2B","force":null,"wrapper":"Habano, Connecticut Shade","vitolas":[],"story":"Montrée en juillet 2015 avec Aladino et Rancho Luna sous la bannière de CLE Cigar Company, puis reprise par JRE Tobacco avec effet au 1er février 2016, d''après cigar-coop.com ; en août 2016, huit formats de 5 x 44 à 6 1/2 x 60, cape Habano ou Connecticut Shade sur binder et tripe de Corojo authentique. En octobre 2026, la maison la présente en versions Connecticut, Habano et Yellow (en bundles), comme un cigare de tous les jours ; le chapeau de son logo figure, dit la maison, le grand patron, el jefe."}]',
  `gamme_en` = '[{"name":"Aladino Corojo","color":"#8B4513","force":"Medium","story":"One hundred per cent corojo grown by the family: a seed from before the hybrids, difficult and unprofitable. Dried fruit, wood, leather, with a fine acidity that modern varieties have lost.","vitolas":["Corona","Robusto"],"wrapper":"Authentic Corojo"},{"name":"Aladino Maduro","color":"#3E2723","force":"Full","story":"Released in 2018. A San Andrés maduro wrapper from Mexico — the only tobacco in the range that does not come from the family''s own land. Honduran corojo binder, Jamastran filler. Cocoa, coffee, cedar and black pepper.","vitolas":["Toro"],"wrapper":"San Andrés (Mexico)"},{"name":"Rancho Luna","color":"#8B5A2B","force":null,"wrapper":"Habano, Connecticut","vitolas":[],"story":"Presented in July 2015 with Aladino and Tatascan under the banner of CLE Cigar Company, then taken over by JRE Tobacco with effect from 1 February 2016, according to cigar-coop.com. Relaunched in January 2025 under the name Rancho Luna by Aladino, in bundles of twenty: Red with a Habano wrapper and Blue with a wrapper of Connecticut seed, in a Toro 6 x 52 rolled at the Fábrica de Puros Aladino; in October 2026, the company''s website speaks of Habano and Maduro wrappers over a binder of authentic Corojo."},{"name":"Tatascan","color":"#8B5A2B","force":null,"wrapper":"Habano, Connecticut Shade","vitolas":[],"story":"Shown in July 2015 with Aladino and Rancho Luna under the banner of CLE Cigar Company, then taken over by JRE Tobacco with effect from 1 February 2016, according to cigar-coop.com; in August 2016, eight formats from 5 x 44 to 6 1/2 x 60, with a Habano or Connecticut Shade wrapper over a binder and filler of authentic Corojo. In October 2026, the company presents it in Connecticut, Habano and Yellow versions (in bundles), as an everyday cigar; the hat on its logo stands for, says the company, the big boss, el jefe."}]',
  `gamme_es` = '[{"name":"Aladino Corojo","color":"#8B4513","force":"Medium","story":"Cien por cien corojo cultivado por la familia: una semilla anterior a los híbridos, difícil y poco rentable. Frutos secos, madera, cuero, con una acidez fina que las variedades modernas han perdido.","vitolas":["Corona","Robusto"],"wrapper":"Corojo auténtico"},{"name":"Aladino Maduro","color":"#3E2723","force":"Full","story":"Salió en 2018. Capa maduro de San Andrés, en México: el único tabaco de la gama que no procede de las tierras de la familia. Capote corojo hondureño, tripa de Jamastrán. Cacao, café, cedro y pimienta negra.","vitolas":["Toro"],"wrapper":"San Andrés (México)"},{"name":"Rancho Luna","color":"#8B5A2B","force":null,"wrapper":"Habano, Connecticut","vitolas":[],"story":"Presentada en julio de 2015 con Aladino y Tatascan bajo la bandera de CLE Cigar Company, y luego retomada por JRE Tobacco con efecto desde el 1 de febrero de 2016, según cigar-coop.com. Relanzada en enero de 2025 con el nombre Rancho Luna by Aladino, en bundles de veinte: Red con capa Habano y Blue con capa de semilla Connecticut, en Toro 6 x 52 torcido en la Fábrica de Puros Aladino; en octubre de 2026, el sitio web de la empresa habla de capas Habano y Maduro sobre capote de Corojo auténtico."},{"name":"Tatascan","color":"#8B5A2B","force":null,"wrapper":"Habano, Connecticut Shade","vitolas":[],"story":"Mostrada en julio de 2015 con Aladino y Rancho Luna bajo la bandera de CLE Cigar Company, y luego retomada por JRE Tobacco con efecto desde el 1 de febrero de 2016, según cigar-coop.com; en agosto de 2016, ocho formatos de 5 x 44 a 6 1/2 x 60, con capa Habano o Connecticut Shade sobre capote y tripa de Corojo auténtico. En octubre de 2026, la empresa la presenta en versiones Connecticut, Habano y Yellow (en bundles), como un puro de todos los días; el sombrero de su logotipo representa, dice la empresa, al gran patrón, el jefe."}]',
  `gamme_de` = '[{"name":"Aladino Corojo","color":"#8B4513","force":"Medium","story":"Hundert Prozent Corojo aus eigenem Anbau: ein Samen aus der Zeit vor den Hybriden, schwierig und wenig einträglich. Trockenfrüchte, Holz, Leder, mit einer feinen Säure, die moderne Sorten verloren haben.","vitolas":["Corona","Robusto"],"wrapper":"Echter Corojo"},{"name":"Aladino Maduro","color":"#3E2723","force":"Full","story":"2018 erschienen. Maduro-Deckblatt aus San Andrés in Mexiko — der einzige Tabak des Sortiments, der nicht vom eigenen Boden stammt. Honduranisches Corojo-Umblatt, Einlage aus dem Jamastran. Kakao, Kaffee, Zeder und schwarzer Pfeffer.","vitolas":["Toro"],"wrapper":"San Andrés (Mexiko)"},{"name":"Rancho Luna","color":"#8B5A2B","force":null,"wrapper":"Habano, Connecticut","vitolas":[],"story":"Im Juli 2015 zusammen mit Aladino und Tatascan unter dem Dach von CLE Cigar Company vorgestellt, dann mit Wirkung zum 1. Februar 2016 von JRE Tobacco übernommen, laut cigar-coop.com. Im Januar 2025 unter dem Namen Rancho Luna by Aladino neu aufgelegt, in Bundles zu zwanzig: Red mit Habano-Deckblatt und Blue mit Deckblatt aus Connecticut-Saatgut, im Toro 6 x 52, gerollt in der Fábrica de Puros Aladino; im Oktober 2026 spricht die Website des Unternehmens von Deckblättern Habano und Maduro über einem Umblatt aus echtem Corojo."},{"name":"Tatascan","color":"#8B5A2B","force":null,"wrapper":"Habano, Connecticut Shade","vitolas":[],"story":"Im Juli 2015 mit Aladino und Rancho Luna unter dem Dach von CLE Cigar Company gezeigt, dann mit Wirkung zum 1. Februar 2016 von JRE Tobacco übernommen, laut cigar-coop.com; im August 2016 acht Formate von 5 x 44 bis 6 1/2 x 60, mit Deckblatt Habano oder Connecticut Shade über Umblatt und Einlage aus echtem Corojo. Im Oktober 2026 präsentiert das Unternehmen sie in den Versionen Connecticut, Habano und Yellow (in Bundles) als Zigarre für jeden Tag; der Hut in ihrem Logo steht, sagt das Unternehmen, für den großen Chef, el jefe."}]',
  `gamme_zh` = '[{"name":"Aladino Corojo","color":"#8B4513","force":"Medium","story":"百分之百家族自种科罗霍：现代杂交品种出现之前的老种，难伺候且收益微薄。风味见干果、木质与皮革，带一缕现代品种已失去的细致酸度。","vitolas":["Corona","Robusto"],"wrapper":"纯正科罗霍"},{"name":"Aladino Maduro","color":"#3E2723","force":"Full","story":"2018 年推出。采用墨西哥圣安德烈斯马杜罗茄衣，是全系列中唯一并非产自家族土地的烟叶。茄套为洪都拉斯科罗霍，茄芯取自哈马斯特兰谷。可可、咖啡、雪松与黑胡椒。","vitolas":["Toro"],"wrapper":"圣安德烈斯（墨西哥）"},{"name":"Rancho Luna","color":"#8B5A2B","force":null,"wrapper":"Habano、Connecticut","vitolas":[],"story":"2015年七月与Aladino、Tatascan一同在CLE Cigar Company旗下亮相，随后自2016年二月1日起由JRE Tobacco接手，据cigar-coop.com称。2025年一月以Rancho Luna by Aladino之名重新推出，为二十支装的bundles：Red采用Habano茄衣，Blue采用Connecticut种子茄衣，规格为Toro 6 x 52，在Fábrica de Puros Aladino卷制；2026年十月，该公司官网提到的是Habano与Maduro茄衣，配纯正Corojo内包叶。"},{"name":"Tatascan","color":"#8B5A2B","force":null,"wrapper":"Habano、Connecticut Shade","vitolas":[],"story":"2015年七月与Aladino、Rancho Luna一同在CLE Cigar Company旗下展出，随后自2016年二月1日起由JRE Tobacco接手，据cigar-coop.com称；2016年八月，共有八种规格，从5 x 44到6 1/2 x 60，茄衣为Habano或Connecticut Shade，内包叶与茄芯为纯正Corojo。2026年十月，该公司将其介绍为日常雪茄，版本有Connecticut、Habano与Yellow（bundles装）；其标志上的帽子，据公司称，代表大老板，即el jefe。"}]',
  `gamme_ar` = '[{"name":"Aladino Corojo","color":"#8B4513","force":"Medium","story":"كوروخو خالص من زراعة العائلة: بذرة سابقة للهجائن، صعبة وقليلة المردود. فواكه مجفّفة وخشب وجلد، مع حموضة رقيقة فقدتها الأصناف الحديثة.","vitolas":["Corona","Robusto"],"wrapper":"كوروخو أصيل"},{"name":"Aladino Maduro","color":"#3E2723","force":"Full","story":"صدر عام 2018. غلاف مادورو من سان أندريس في المكسيك — التبغ الوحيد في التشكيلة الذي لا يأتي من أرض العائلة. رابط كوروخو هندوراسي وحشوة من وادي خاماستران. كاكاو وقهوة وأرز وفلفل أسود.","vitolas":["Toro"],"wrapper":"سان أندريس (المكسيك)"},{"name":"Rancho Luna","color":"#8B5A2B","force":null,"wrapper":"Habano، Connecticut","vitolas":[],"story":"قُدّمت في يوليو 2015 مع Aladino وTatascan تحت مظلة CLE Cigar Company، ثم آلت إلى JRE Tobacco اعتبارًا من 1 فبراير 2016، وفقًا لـ cigar-coop.com. وأُعيد إطلاقها في يناير 2025 باسم Rancho Luna by Aladino، في bundles من عشرين: Red بغلاف Habano وBlue بغلاف من بذور Connecticut، من مقاس Toro 6 x 52 لُفّ في Fábrica de Puros Aladino؛ وفي أكتوبر 2026، يتحدث موقع الشركة عن أغلفة Habano وMaduro على لفافة داخلية من Corojo الأصيل."},{"name":"Tatascan","color":"#8B5A2B","force":null,"wrapper":"Habano، Connecticut Shade","vitolas":[],"story":"عُرضت في يوليو 2015 مع Aladino وRancho Luna تحت مظلة CLE Cigar Company، ثم آلت إلى JRE Tobacco اعتبارًا من 1 فبراير 2016، وفقًا لـ cigar-coop.com؛ وفي أغسطس 2016، ثمانية مقاسات من 5 x 44 إلى 6 1/2 x 60، بغلاف Habano أو Connecticut Shade على لفافة داخلية وحشوة من Corojo الأصيل. وفي أكتوبر 2026، تقدمها الشركة بنسخ Connecticut وHabano وYellow (في bundles)، بوصفها سيجارًا لكل يوم؛ وتقول الشركة إن القبعة في شعارها ترمز إلى الرئيس الكبير، el jefe."}]',
  `source` = IF(LOCATE('jretobacco.com « JRE Tobacco » (consulté 2026-10-07 : site d', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'jretobacco.com « JRE Tobacco » (consulté 2026-10-07 : site de la maison, trois marques Aladino, Rancho Luna et Tatascan, exploitation de la vallée de Jamastran) ; jretobacco.com « Tatascan » (consulté 2026-10-07 : capes Connecticut et Habano, versions Connecticut, Habano et Yellow en bundles, cigare de tous les jours, chapeau du logo pour le grand patron) ; jretobacco.com « Rancho Luna » (consulté 2026-10-07 : mélange de Justo et Julio R. Eiroa, capes Habano et Maduro, binder de Corojo authentique, tripe Habano et Corojo authentique) ; cigar-coop.com « Cigar News: CLE Cigars Introduces Aladino, Tatascan, and Rancho Luna Lines » (2015-07-31 : trois lignes présentées à l''IPCPR 2015 par CLE Cigar Company, roulées à Las Lomas par Julio Eiroa) ; cigar-coop.com « Cigar News: Julio Eiroa Launches JRE Tobacco Co. » (2016-01-29 : JRE Tobacco formée par Julio et Justo Eiroa, transfert des trois marques effectif au 1er février) ; cigar-coop.com « Cigar News: JRE Tobacco Showcases Tatascan at 2016 IPCPR » (2016-08-21 : huit formats de 5 x 44 à 6 1/2 x 60, cape Habano ou Connecticut Shade, binder Corojo authentique, tripe Habano et Corojo authentique) ; cigar-coop.com « JRE Tobacco Co Relaunches Rancho Luna » (2025-01-31 : relance à TPE 2025 sous le nom Rancho Luna by Aladino, Red Habano et Blue de graine Connecticut, Toro 6 x 52, Fábrica de Puros Aladino, vallée de Jamastran)')),
  `updated_at` = NOW()
 WHERE `name` = 'Aladino';

-- ── American Caribbean Cigars — paragraphe : The Circus, gamme : La Rosa de Sandiego ──
UPDATE `brands` SET
  `history` = IF(LOCATE('The Circus est une ligne d''El Viejo Continente, marque de Da', `history`) > 0, `history`, CONCAT(`history`, '

', 'The Circus est une ligne d''El Viejo Continente, marque de Daniel Guerrero ; en octobre 2026, le site de la marque la range parmi ses familles, avec Mare Nostrum. Un blog situait en octobre 2021 la production de la marque, dont The Circus Petit (3 1/2 x 44), à la fabrique d''American Caribbean Cigars, à Estelí. Un article de septembre 2023 décrit la fabrique propre de la marque, à Condega, sans y nommer The Circus ; en octobre 2026, Cigarworld.de écrit que Guerrero produit ses cigares dans sa tabacalera au Nicaragua.')),
  `history_en` = IF(LOCATE('The Circus is a line of El Viejo Continente, a brand of Dani', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'The Circus is a line of El Viejo Continente, a brand of Daniel Guerrero; in October 2026, the brand''s website lists it among its families, with Mare Nostrum. In October 2021, a blog placed the brand''s production, including The Circus Petit (3 1/2 x 44), at the American Caribbean Cigars factory in Estelí. An article of September 2023 describes the brand''s own factory, in Condega, without naming The Circus there; in October 2026, Cigarworld.de writes that Guerrero produces his cigars in his tabacalera in Nicaragua.')),
  `history_es` = IF(LOCATE('The Circus es una línea de El Viejo Continente, marca de Dan', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'The Circus es una línea de El Viejo Continente, marca de Daniel Guerrero; en octubre de 2026, el sitio web de la marca la incluye entre sus familias, junto a Mare Nostrum. Un blog situaba en octubre de 2021 la producción de la marca, incluida The Circus Petit (3 1/2 x 44), en la fábrica de American Caribbean Cigars, en Estelí. Un artículo de septiembre de 2023 describe la fábrica propia de la marca, en Condega, sin nombrar allí The Circus; en octubre de 2026, Cigarworld.de escribe que Guerrero produce sus puros en su tabacalera de Nicaragua.')),
  `history_de` = IF(LOCATE('The Circus ist eine Linie von El Viejo Continente, einer Mar', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'The Circus ist eine Linie von El Viejo Continente, einer Marke von Daniel Guerrero; im Oktober 2026 führt die Website der Marke sie unter ihren Familien auf, neben Mare Nostrum. Ein Blog verortete im Oktober 2021 die Produktion der Marke, darunter The Circus Petit (3 1/2 x 44), in der Fabrik von American Caribbean Cigars in Estelí. Ein Artikel vom September 2023 beschreibt die eigene Fabrik der Marke in Condega, ohne dort The Circus zu nennen; im Oktober 2026 schreibt Cigarworld.de, dass Guerrero seine Zigarren in seiner Tabacalera in Nicaragua produziert.')),
  `history_zh` = IF(LOCATE('The Circus是El Viejo Continente旗下的产品线，El Viejo Continente是Dan', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', 'The Circus是El Viejo Continente旗下的产品线，El Viejo Continente是Daniel Guerrero的品牌；2026年十月，该品牌官网将其列入各产品系列，与Mare Nostrum并列。2021年十月，一个博客称该品牌的生产（包括The Circus Petit，3 1/2 x 44）设在American Caribbean Cigars位于Estelí的工厂。2023年九月的一篇文章介绍了该品牌自有的工厂，位于Condega，但文中未在其中提及The Circus；2026年十月，Cigarworld.de写道，Guerrero在其位于尼加拉瓜的tabacalera生产雪茄。')),
  `history_ar` = IF(LOCATE('The Circus خط من El Viejo Continente، وهي علامة تعود إلى Dan', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'The Circus خط من El Viejo Continente، وهي علامة تعود إلى Daniel Guerrero؛ وفي أكتوبر 2026، يدرجه موقع العلامة ضمن عائلاتها، إلى جانب Mare Nostrum. وذكرت مدونة في أكتوبر 2021 أن إنتاج العلامة، ومنه The Circus Petit (3 1/2 x 44)، كان يتم في مصنع American Caribbean Cigars في Estelí. ويصف مقال من سبتمبر 2023 المصنع الخاص بالعلامة في Condega، دون أن يذكر The Circus هناك؛ وفي أكتوبر 2026، تكتب Cigarworld.de أن Guerrero ينتج سيجاره في tabacalera الخاصة به في نيكاراغوا.')),
  `gamme` = '[{"name":"The Bouncer","color":"#4A3728","force":null,"story":"Cape San Andrés du Mexique et sous-cape Sumatra sur tripe nicaraguayenne d''Estelí, Jalapa et Ometepe, présentée à l''IPCPR 2018, selon cigarworld.de et halfwheel.","vitolas":[],"wrapper":"San Andrés (Mexique)"},{"name":"El Viejo Continente","color":"#A0522D","force":null,"story":"Née de la rencontre entre Emiliano Lagos et le tabacologue barcelonais Daniel Guerrero, déclinée en plusieurs habillages (Classic, Maduro, Edición Estelí) sans cape unique clairement établie, et en deux lignes sœurs, Mare Nostrum et The Circus, selon Neptune Cigars.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Maradona Tribute","color":"#A0522D","force":null,"story":"Édition de cinq cents boîtes en hommage à Diego Maradona, tripe nicaraguayenne et hondurienne et sous-cape San Andrés sous la cape équatorienne.","vitolas":[],"wrapper":"Équateur"},{"name":"The Traveler","color":"#A0522D","force":null,"story":"Marque personnelle d''Emiliano Lagos lancée en 2017 en Europe puis aux États-Unis, vitolas nommées d''après des aéroports internationaux, en versions naturelle et maduro, selon Cigar Coop.","vitolas":[],"wrapper":"Non divulguée"},{"name":"El Copey","color":"#C9A96E","force":null,"story":"Seule ligne roulée hors du Nicaragua : faite à la main en République dominicaine, dans une fabrique qu''aucune source consultée ne nomme (cigarworld.de, hacico.de) ; cape Connecticut d''Équateur sur sous-cape et tripe dominicaines, selon cigarworld.de.","vitolas":[],"wrapper":"Connecticut (Équateur)"},{"name":"Bella Mundo","color":"#6B4226","force":null,"story":"Cape brésilienne dite Cubra, sous-cape Sumatra et tripe criollo du Nicaragua, présentée à l''IPCPR 2018, selon Cigar Coop.","vitolas":[],"wrapper":"Brésil (Cubra)"},{"name":"La Rosa de Sandiego","color":"#6B4226","force":null,"wrapper":"Connecticut, Habano, Maduro","vitolas":[],"story":"Trois versions au lancement, d''après un article d''août 2015 : Connecticut d''Équateur (tripe du Nicaragua et de Pennsylvanie), Habano d''Équateur (Piloto Cubano, Ometepe, Estelí) et Maduro à cape San Andrés (tripe dominicaine, d''Estelí et de Jalapa), en Robusto 5 x 52, Toro Gordo 6 x 54 et Immensio XO 6 x 60. Le nom rend hommage à San Diego de los Baños, à Cuba ; cinq mélanges étaient montrés à l''IPCPR 2018, selon un article d''août 2018."}]',
  `gamme_en` = '[{"name":"The Bouncer","color":"#4A3728","force":null,"story":"Mexican San Andrés wrapper and Sumatra binder over Nicaraguan filler from Estelí, Jalapa and Ometepe, presented at the IPCPR 2018, according to cigarworld.de and halfwheel.","vitolas":[],"wrapper":"San Andrés (Mexico)"},{"name":"El Viejo Continente","color":"#A0522D","force":null,"story":"Born of the meeting between Emiliano Lagos and Barcelona-based tobacco specialist Daniel Guerrero, it comes in several dress styles (Classic, Maduro, Edición Estelí) without one clearly established wrapper, and in two sister lines, Mare Nostrum and The Circus, according to Neptune Cigars.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Maradona Tribute","color":"#A0522D","force":null,"story":"A five-hundred-box edition in tribute to Diego Maradona, with Nicaraguan and Honduran filler and a San Andrés binder under the Ecuadorian wrapper.","vitolas":[],"wrapper":"Ecuador"},{"name":"The Traveler","color":"#A0522D","force":null,"story":"Emiliano Lagos''s personal brand, launched in 2017 in Europe and then in the United States, with vitolas named after international airports, in natural and maduro versions, according to Cigar Coop.","vitolas":[],"wrapper":"Undisclosed"},{"name":"El Copey","color":"#C9A96E","force":null,"story":"The only line rolled outside Nicaragua: hand-made in the Dominican Republic, at a factory no source consulted names (cigarworld.de, hacico.de); an Ecuadorian Connecticut wrapper over Dominican binder and filler, according to cigarworld.de.","vitolas":[],"wrapper":"Connecticut (Ecuador)"},{"name":"Bella Mundo","color":"#6B4226","force":null,"story":"Brazilian wrapper known as Cubra, Sumatra binder and Nicaraguan criollo filler, presented at the IPCPR 2018, according to Cigar Coop.","vitolas":[],"wrapper":"Brazil (Cubra)"},{"name":"La Rosa de Sandiego","color":"#6B4226","force":null,"wrapper":"Connecticut, Habano, Maduro","vitolas":[],"story":"Three versions at launch, according to an article of August 2015: Connecticut from Ecuador (filler from Nicaragua and Pennsylvania), Habano from Ecuador (Piloto Cubano, Ometepe, Estelí) and Maduro with a San Andrés wrapper (Dominican filler, from Estelí and Jalapa), in Robusto 5 x 52, Toro Gordo 6 x 54 and Immensio XO 6 x 60. The name pays tribute to San Diego de los Baños, in Cuba; five blends were shown at IPCPR 2018, according to an article of August 2018."}]',
  `gamme_es` = '[{"name":"The Bouncer","color":"#4A3728","force":null,"story":"Capa San Andrés de México y capote de Sumatra sobre tripa nicaragüense de Estelí, Jalapa y Ometepe, presentada en el IPCPR 2018, según cigarworld.de y halfwheel.","vitolas":[],"wrapper":"San Andrés (México)"},{"name":"El Viejo Continente","color":"#A0522D","force":null,"story":"Nacida del encuentro entre Emiliano Lagos y el tabacólogo barcelonés Daniel Guerrero, se presenta en varios vitolados (Classic, Maduro, Edición Estelí) sin una capa única claramente establecida, y en dos líneas hermanas, Mare Nostrum y The Circus, según Neptune Cigars.","vitolas":[],"wrapper":"No divulgada"},{"name":"Maradona Tribute","color":"#A0522D","force":null,"story":"Edición de quinientas cajas en homenaje a Diego Maradona, con tripa nicaragüense y hondureña y capote San Andrés bajo la capa ecuatoriana.","vitolas":[],"wrapper":"Ecuador"},{"name":"The Traveler","color":"#A0522D","force":null,"story":"Marca personal de Emiliano Lagos lanzada en 2017 en Europa y después en Estados Unidos, con vitolas bautizadas con nombres de aeropuertos internacionales, en versiones natural y maduro, según Cigar Coop.","vitolas":[],"wrapper":"No divulgada"},{"name":"El Copey","color":"#C9A96E","force":null,"story":"Única línea elaborada fuera de Nicaragua: hecha a mano en República Dominicana, en una fábrica que ninguna fuente consultada nombra (cigarworld.de, hacico.de); capa Connecticut de Ecuador sobre capote y tripa dominicanos, según cigarworld.de.","vitolas":[],"wrapper":"Connecticut (Ecuador)"},{"name":"Bella Mundo","color":"#6B4226","force":null,"story":"Capa brasileña llamada Cubra, capote de Sumatra y tripa criollo de Nicaragua, presentada en el IPCPR 2018, según Cigar Coop.","vitolas":[],"wrapper":"Brasil (Cubra)"},{"name":"La Rosa de Sandiego","color":"#6B4226","force":null,"wrapper":"Connecticut, Habano, Maduro","vitolas":[],"story":"Tres versiones en el lanzamiento, según un artículo de agosto de 2015: Connecticut de Ecuador (tripa de Nicaragua y de Pensilvania), Habano de Ecuador (Piloto Cubano, Ometepe, Estelí) y Maduro con capa San Andrés (tripa dominicana, de Estelí y de Jalapa), en Robusto 5 x 52, Toro Gordo 6 x 54 e Immensio XO 6 x 60. El nombre rinde homenaje a San Diego de los Baños, en Cuba; en la IPCPR de 2018 se mostraron cinco mezclas, según un artículo de agosto de 2018."}]',
  `gamme_de` = '[{"name":"The Bouncer","color":"#4A3728","force":null,"story":"Mexikanisches San-Andrés-Deckblatt und Sumatra-Umblatt über nicaraguanischer Einlage aus Estelí, Jalapa und Ometepe, 2018 auf der IPCPR vorgestellt, laut cigarworld.de und halfwheel.","vitolas":[],"wrapper":"San Andrés (Mexiko)"},{"name":"El Viejo Continente","color":"#A0522D","force":null,"story":"Entstanden aus der Begegnung zwischen Emiliano Lagos und dem Barceloner Tabakexperten Daniel Guerrero, gibt es sie in mehreren Aufmachungen (Classic, Maduro, Edición Estelí) ohne ein klar festgelegtes einheitliches Deckblatt, sowie in zwei Schwesterlinien, Mare Nostrum und The Circus, laut Neptune Cigars.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Maradona Tribute","color":"#A0522D","force":null,"story":"Eine Edition von fünfhundert Kisten zu Ehren von Diego Maradona, mit nicaraguanischer und honduranischer Einlage und San-Andrés-Umblatt unter dem ecuadorianischen Deckblatt.","vitolas":[],"wrapper":"Ecuador"},{"name":"The Traveler","color":"#A0522D","force":null,"story":"Persönliche Marke von Emiliano Lagos, 2017 in Europa und anschließend in den Vereinigten Staaten lanciert, mit Vitolen, die nach internationalen Flughäfen benannt sind, in natürlicher und Maduro-Version, laut Cigar Coop.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"El Copey","color":"#C9A96E","force":null,"story":"Einzige Linie, die außerhalb Nicaraguas gerollt wird: handgefertigt in der Dominikanischen Republik, in einer Fabrik, die keine der konsultierten Quellen nennt (cigarworld.de, hacico.de); ecuadorianisches Connecticut-Deckblatt über dominikanischem Umblatt und dominikanischer Einlage, laut cigarworld.de.","vitolas":[],"wrapper":"Connecticut (Ecuador)"},{"name":"Bella Mundo","color":"#6B4226","force":null,"story":"Brasilianisches, als Cubra bezeichnetes Deckblatt, Sumatra-Umblatt und nicaraguanische Criollo-Einlage, 2018 auf der IPCPR vorgestellt, laut Cigar Coop.","vitolas":[],"wrapper":"Brasilien (Cubra)"},{"name":"La Rosa de Sandiego","color":"#6B4226","force":null,"wrapper":"Connecticut, Habano, Maduro","vitolas":[],"story":"Drei Versionen zum Start, laut einem Artikel vom August 2015: Connecticut aus Ecuador (Einlage aus Nicaragua und Pennsylvania), Habano aus Ecuador (Piloto Cubano, Ometepe, Estelí) und Maduro mit Deckblatt San Andrés (dominikanische Einlage, aus Estelí und aus Jalapa), in Robusto 5 x 52, Toro Gordo 6 x 54 und Immensio XO 6 x 60. Der Name ist eine Hommage an San Diego de los Baños auf Kuba; fünf Mischungen wurden auf der IPCPR 2018 gezeigt, laut einem Artikel vom August 2018."}]',
  `gamme_zh` = '[{"name":"The Bouncer","color":"#4A3728","force":null,"story":"墨西哥San Andrés茄衣与Sumatra茄套，搭配产自Estelí、Jalapa与Ometepe的尼加拉瓜茄芯，于2018年IPCPR展会推出，据cigarworld.de与halfwheel称。","vitolas":[],"wrapper":"San Andrés（墨西哥）"},{"name":"El Viejo Continente","color":"#A0522D","force":null,"story":"该系列诞生于Emiliano Lagos与巴塞罗那烟草专家Daniel Guerrero的相识，推出多种外观版本（Classic、Maduro、Edición Estelí），并无明确统一的茄衣，另有两条姊妹系列Mare Nostrum与The Circus，据Neptune Cigars称。","vitolas":[],"wrapper":"未公开"},{"name":"Maradona Tribute","color":"#A0522D","force":null,"story":"限量五百箱，以纪念Diego Maradona，茄芯为尼加拉瓜与洪都拉斯烟叶，厄瓜多尔茄衣之下衬有San Andrés茄套。","vitolas":[],"wrapper":"厄瓜多尔"},{"name":"The Traveler","color":"#A0522D","force":null,"story":"Emiliano Lagos的个人品牌，2017年先在欧洲、后在美国推出，雪茄规格以国际机场命名，分天然与maduro两个版本，据Cigar Coop称。","vitolas":[],"wrapper":"未公开"},{"name":"El Copey","color":"#C9A96E","force":null,"story":"唯一一条在尼加拉瓜境外卷制的系列：在多米尼加共和国手工制作，所查阅的资料均未指明工厂名称（cigarworld.de、hacico.de）；据cigarworld.de称，采用厄瓜多尔Connecticut茄衣，搭配多米尼加茄套与茄芯。","vitolas":[],"wrapper":"Connecticut（厄瓜多尔）"},{"name":"Bella Mundo","color":"#6B4226","force":null,"story":"被称为Cubra的巴西茄衣，Sumatra茄套，以及尼加拉瓜criollo茄芯，于2018年IPCPR展会推出，据Cigar Coop称。","vitolas":[],"wrapper":"巴西（Cubra）"},{"name":"La Rosa de Sandiego","color":"#6B4226","force":null,"wrapper":"Connecticut、Habano、Maduro","vitolas":[],"story":"上市时有三个版本，据2015年八月的一篇文章：来自厄瓜多尔的Connecticut（茄芯来自尼加拉瓜与宾夕法尼亚）、来自厄瓜多尔的Habano（Piloto Cubano、Ometepe、Estelí），以及采用San Andrés茄衣的Maduro（茄芯来自多米尼加共和国、Estelí与Jalapa），规格为Robusto 5 x 52、Toro Gordo 6 x 54与Immensio XO 6 x 60。名称向古巴的San Diego de los Baños致敬；据2018年八月的一篇文章，IPCPR 2018上展示了五种拼配。"}]',
  `gamme_ar` = '[{"name":"The Bouncer","color":"#4A3728","force":null,"story":"غلاف San Andrés مكسيكي ورباط من Sumatra فوق حشوة نيكاراغوية من Estelí وJalapa وOmetepe، قُدِّمت في معرض IPCPR عام 2018، بحسب cigarworld.de وhalfwheel.","vitolas":[],"wrapper":"San Andrés (المكسيك)"},{"name":"El Viejo Continente","color":"#A0522D","force":null,"story":"وُلدت من لقاء بين Emiliano Lagos وخبير التبغ البرشلوني Daniel Guerrero، وتُقدَّم بعدة أشكال (Classic وMaduro وEdición Estelí) دون غلاف واحد محدَّد بوضوح، وضمن سلسلتين شقيقتين، Mare Nostrum وThe Circus، بحسب Neptune Cigars.","vitolas":[],"wrapper":"غير معلن"},{"name":"Maradona Tribute","color":"#A0522D","force":null,"story":"إصدار من خمسمائة صندوق تكريمًا لـ Diego Maradona، بحشوة نيكاراغوية وهندوراسية ورباط San Andrés تحت الغلاف الإكوادوري.","vitolas":[],"wrapper":"الإكوادور"},{"name":"The Traveler","color":"#A0522D","force":null,"story":"علامة شخصية لـ Emiliano Lagos، أُطلقت عام 2017 في أوروبا ثم في الولايات المتحدة، بمقاسات سُمّيت بأسماء مطارات دولية، بنسختين طبيعية وmaduro، بحسب Cigar Coop.","vitolas":[],"wrapper":"غير معلن"},{"name":"El Copey","color":"#C9A96E","force":null,"story":"السلسلة الوحيدة التي تُلف خارج نيكاراغوا: تُصنع يدويًا في جمهورية الدومينيكان، في مصنع لم تُسمِّه أي من المصادر المُطالَعة (cigarworld.de، hacico.de)؛ بغلاف Connecticut إكوادوري فوق رباط وحشوة دومينيكانيين، بحسب cigarworld.de.","vitolas":[],"wrapper":"Connecticut (الإكوادور)"},{"name":"Bella Mundo","color":"#6B4226","force":null,"story":"غلاف برازيلي يُعرف باسم Cubra، ورباط من Sumatra وحشوة criollo نيكاراغوية، قُدِّمت في معرض IPCPR عام 2018، بحسب Cigar Coop.","vitolas":[],"wrapper":"البرازيل (Cubra)"},{"name":"La Rosa de Sandiego","color":"#6B4226","force":null,"wrapper":"Connecticut، Habano، Maduro","vitolas":[],"story":"ثلاث نسخ عند الإطلاق، وفقًا لمقال من أغسطس 2015: Connecticut من الإكوادور (حشوة من نيكاراغوا وبنسلفانيا)، وHabano من الإكوادور (Piloto Cubano وOmetepe وEstelí)، وMaduro بغلاف San Andrés (حشوة دومينيكانية، من Estelí ومن Jalapa)، بمقاسات Robusto 5 x 52 وToro Gordo 6 x 54 وImmensio XO 6 x 60. ويُكرّم الاسم San Diego de los Baños في كوبا؛ وعُرضت خمس خلطات في IPCPR 2018، وفقًا لمقال من أغسطس 2018."}]',
  `mentions` = '["Toraño","Leccia Tobacco","Vintage Rock-A-Feller Cigar Group","The Circus"]',
  `source` = IF(LOCATE('pandorascigarbox.com « El Viejo Continente Half Corona Doubl', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'pandorascigarbox.com « El Viejo Continente Half Corona Double Bill: Small But Mighty » (2021-10-08 : The Circus Petit, demi-corona 3 1/2 x 44 à cape Claro d''Équateur, production de la marque située à la fabrique d''American Caribbean Cigars, à Estelí) ; cigarslover.com « El Viejo Continente Maduro Lancero » (2022-03-21 : cigare fait au Nicaragua par le maître assembleur Daniel Guerrero et le fabricant Emiliano Lagos) ; cigarjournal.com « In the Name of the Father: El Viejo Continente Don Juan » (2023-09-14 : fabrique propre d''El Viejo Continente à Condega, ne cite ni The Circus ni Mare Nostrum) ; cigarworld.de « El Viejo Continente » (consulté 2026-10-07 : Daniel Guerrero produit ses cigares dans sa tabacalera au Nicaragua ; The Circus parmi les séries listées) ; elviejocontinente.com « Accueil » (consulté 2026-10-07 : familles Classic, Maduro, Connecticut, Mare Nostrum, The Circus et Special Edition ; le site ne donne pas de lieu de fabrique) ; cigar-coop.com « Cigar News: American Caribbean Cigars Launches La Rosa de Sandiego » (2015-08-30 : trois mélanges, trois formats, roulage chez American Caribbean Cigars à Estelí, hommage à San Diego de los Baños) ; cigar-coop.com « Feature Story: Spotlight on American Caribbean Cigars, Vintage Rock-a-Feller Cigar Group, and The Traveler at the 2018 IPCPR » (2018-08-04 : cinq mélanges de La Rosa de Sandiego montrés à l''IPCPR 2018, fabrique d''Estelí) ; humoytabaco.com « La Rosa de Sandiego » (2024-11-25, source en espagnol : marque lancée par American Caribbean Cigars en 2015, produits faits au Nicaragua)')),
  `updated_at` = NOW()
 WHERE `name` = 'American Caribbean Cigars';

-- ── Arturo Fuente — gamme : Casa Cuba, Fuente Fuente OpusX The Lost City ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Opus X","color":"#8B0000","force":"Full","story":"Lancé en 1995, le grand cigare dominicain. Cape Château de la Fuente — plantation à part, production confidentielle. Notes d''espresso, poivre rouge, cèdre doré, caramel. La Perfección (double figurado) est la forme la plus recherchée. Disponibilité aléatoire, et un prix de revente qui atteint plusieurs fois le prix catalogue : l''un des cigares les plus spéculatifs du marché.","vitolas":["Double Corona","Perfección No.1","Perfección No.2","Fuente Fuente","BBMF","Angel''s Share"],"wrapper":"Château de la Fuente (République dominicaine)"},{"name":"Don Carlos","color":"#A0522D","force":"Medium-Full","story":"Hommage au père, Carlos Fuente Sr. Mi-corsée à corsée, cape camerounaise sur dominicain. L''équilibre de la maison — moins rare que l''Opus X, plus accessible, d''une constance que les amateurs suivent depuis les années 1970. Notes de café, cuir, épices douces. Le format Eye of the Shark, un figurado, est celui que la maison réserve à ses sorties les plus attendues.","vitolas":["Robusto","No.1","No.2","No.3","Eye of the Shark"],"wrapper":"Cameroun"},{"name":"Hemingway","color":"#8B4513","force":"Medium","story":"Lancée dans les années 1980, en formats Perfectos et Classicos. Elle porte le nom de l''écrivain qui vécut à Cuba — un hommage de la maison, sans qu''un goût particulier pour le cigare lui soit attesté. C''est le point d''entrée Arturo Fuente : douce, crémeuse, sans agressivité. Le Masterpiece, neuf pouces, est le plus long cigare de la gamme.","vitolas":["Classic","Short Story","Best Seller","Masterpiece","Signature"],"wrapper":"Cameroun"},{"name":"Añejo","color":"#722F37","force":"Medium-Full","story":"Cape Connecticut Broadleaf maduro vieillie en fûts de cognac — une première à son lancement en 1999. Notes de cognac, chocolat belge, noix de cajou. L''Añejo No.77 Shark, au format figurado, est la vitole que les amateurs de la maison guettent.","vitolas":["No.46","No.48","No.50","No.55","No.60","No.77 Shark"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Casa Cuba","color":"#8B5A2B","force":null,"wrapper":"Havana d''Équateur","vitolas":[],"story":"Lancée fin 2013 en allocation limitée aux détaillants, dit Cigar Coop, et présentée par arturofuente.com comme le dernier mélange de feu Carlos Fuente Sr., pensé pour rappeler les cigares qu''il roulait et fumait jeune avec son père, avec du tabac cubain. Cape Havana d''Équateur sur liant et longfiller dominicains de semence cubaine, roulés à la Tabacalera A. Fuente y Cia. Les formats portent des noms de dominos cubains : Doble Dos 6¾ x 42, Doble Tres 5½ x 44, Doble Cinco 5 x 50, Doble Seis 6 x 52, Doble Cuatro 4½ x 54 et Divine Inspiration 6⅛ x 47. Force dite medium, montant au medium-corsé sur le dernier tiers, par Cigar Coop en 2014, et medium-corsée par un détaillant en octobre 2026."},{"name":"Fuente Fuente OpusX The Lost City","color":"#A0522D","force":"Medium-Full","wrapper":"République dominicaine","vitolas":[],"story":"Édition d''OpusX dont le tabac, entièrement dominicain, a été planté à l''été 2004 au Château de la Fuente pour le tournage du film The Lost City, sorti en 2005 et réalisé par Andy Garcia, puis vieilli cinq ans, selon fuenteagedselection.com, qui la dit medium à corsée. Roulée à la Tabacalera A. Fuente ; une dépêche de juin 2024 la range dans l''allocation annuelle Aged Selection livrée aux détaillants. Formats : Robusto 5¼ x 50, Double Robusto 5¾ x 52, Toro 6¾ x 48, Lancero 7½ x 38 et Carlito''s A 9¼ x 47."}]',
  `gamme_en` = '[{"name":"Opus X","color":"#8B0000","force":"Full","story":"Launched in 1995, the great Dominican cigar. Château de la Fuente wrapper — a plantation apart, confidential output. Espresso, red pepper, golden cedar, caramel. The Perfección (double figurado) is the most sought-after shape. Erratic availability, and a resale price several times the list price: one of the most speculative cigars on the market.","vitolas":["Double Corona","Perfección No.1","Perfección No.2","Fuente Fuente","BBMF","Angel''s Share"],"wrapper":"Château de la Fuente (Dominican Republic)"},{"name":"Don Carlos","color":"#A0522D","force":"Medium-Full","story":"A tribute to the father, Carlos Fuente Sr. Medium to full, Cameroon wrapper over Dominican. The balance point of the house — less scarce than the Opus X, more approachable, with a consistency followers have tracked since the 1970s. Coffee, leather, gentle spice. The Eye of the Shark, a figurado, is the shape the house keeps for its most awaited releases.","vitolas":["Robusto","No.1","No.2","No.3","Eye of the Shark"],"wrapper":"Cameroon"},{"name":"Hemingway","color":"#8B4513","force":"Medium","story":"Launched in the 1980s, in Perfecto and Classico shapes. It carries the name of the writer who lived in Cuba — a tribute from the house, with no particular taste for cigars attested to him. This is the way into Arturo Fuente: mild, creamy, without aggression. The Masterpiece, nine inches, is the longest cigar in the range.","vitolas":["Classic","Short Story","Best Seller","Masterpiece","Signature"],"wrapper":"Cameroon"},{"name":"Añejo","color":"#722F37","force":"Medium-Full","story":"Connecticut Broadleaf maduro wrapper aged in cognac casks — a first when it launched in 1999. Cognac, Belgian chocolate, cashew. The Añejo No.77 Shark, a figurado, is the vitola the house''s followers watch for.","vitolas":["No.46","No.48","No.50","No.55","No.60","No.77 Shark"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Casa Cuba","color":"#8B5A2B","force":null,"wrapper":"Ecuadorian Havana","vitolas":[],"story":"Launched in late 2013 in a limited allocation to retailers, says Cigar Coop, and presented by arturofuente.com as the last blend of the late Carlos Fuente Sr., designed to recall the cigars he rolled and smoked in his youth with his father, with Cuban tobacco. Ecuadorian Havana wrapper over a Dominican binder and longfiller of Cuban seed, rolled at the Tabacalera A. Fuente y Cia. The formats carry the names of Cuban dominoes: Doble Dos 6¾ x 42, Doble Tres 5½ x 44, Doble Cinco 5 x 50, Doble Seis 6 x 52, Doble Cuatro 4½ x 54 and Divine Inspiration 6⅛ x 47. Strength described as medium, rising to medium-full over the final third, by Cigar Coop in 2014, and as medium-full by a retailer in October 2026."},{"name":"Fuente Fuente OpusX The Lost City","color":"#A0522D","force":"Medium-Full","wrapper":"Dominican Republic","vitolas":[],"story":"An edition of OpusX whose tobacco, entirely Dominican, was planted in the summer of 2004 at the Château de la Fuente for the shooting of the film The Lost City, released in 2005 and directed by Andy Garcia, then aged for five years, according to fuenteagedselection.com, which calls it medium to full. Rolled at the Tabacalera A. Fuente; a news report of June 2024 places it in the annual Aged Selection allocation delivered to retailers. Formats: Robusto 5¼ x 50, Double Robusto 5¾ x 52, Toro 6¾ x 48, Lancero 7½ x 38 and Carlito''s A 9¼ x 47."}]',
  `gamme_es` = '[{"name":"Opus X","color":"#8B0000","force":"Full","story":"Lanzado en 1995, el gran puro dominicano. Capa Château de la Fuente, plantación aparte y producción confidencial. Espresso, pimienta roja, cedro dorado, caramelo. La Perfección (doble figurado) es la forma más buscada. Disponibilidad errática y un precio de reventa que multiplica varias veces el de catálogo: uno de los puros más especulativos del mercado.","vitolas":["Double Corona","Perfección No.1","Perfección No.2","Fuente Fuente","BBMF","Angel''s Share"],"wrapper":"Château de la Fuente (República Dominicana)"},{"name":"Don Carlos","color":"#A0522D","force":"Medium-Full","story":"Homenaje al padre, Carlos Fuente Sr. Medio-fuerte, capa Camerún sobre dominicano. El punto de equilibrio de la casa: menos escaso que el Opus X, más accesible, con una regularidad que los aficionados siguen desde los años setenta. Café, cuero, especias suaves. El Eye of the Shark, un figurado, es el formato que la casa reserva a sus salidas más esperadas.","vitolas":["Robusto","No.1","No.2","No.3","Eye of the Shark"],"wrapper":"Camerún"},{"name":"Hemingway","color":"#8B4513","force":"Medium","story":"Lanzada en los años ochenta, en formatos Perfectos y Clásicos. Lleva el nombre del escritor que vivió en Cuba: un homenaje de la casa, sin que se le acredite un gusto particular por el puro. Es la puerta de entrada a Arturo Fuente: suave, cremosa, sin agresividad. El Masterpiece, de nueve pulgadas, es el puro más largo de la gama.","vitolas":["Classic","Short Story","Best Seller","Masterpiece","Signature"],"wrapper":"Camerún"},{"name":"Añejo","color":"#722F37","force":"Medium-Full","story":"Capa Connecticut Broadleaf maduro envejecida en barricas de coñac, una primicia cuando se lanzó en 1999. Coñac, chocolate belga, anacardo. El Añejo No.77 Shark, de formato figurado, es la vitola que acechan los seguidores de la casa.","vitolas":["No.46","No.48","No.50","No.55","No.60","No.77 Shark"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Casa Cuba","color":"#8B5A2B","force":null,"wrapper":"Havana de Ecuador","vitolas":[],"story":"Lanzada a finales de 2013 en una asignación limitada para los minoristas, dice Cigar Coop, y presentada por arturofuente.com como la última mezcla del difunto Carlos Fuente Sr., pensada para evocar los puros que torcía y fumaba de joven con su padre, con tabaco cubano. Capa Havana de Ecuador sobre capote y longfiller dominicanos de semilla cubana, torcidos en la Tabacalera A. Fuente y Cia. Los formatos llevan nombres de dominós cubanos: Doble Dos 6¾ x 42, Doble Tres 5½ x 44, Doble Cinco 5 x 50, Doble Seis 6 x 52, Doble Cuatro 4½ x 54 y Divine Inspiration 6⅛ x 47. Fuerza descrita como medium, que sube a medium-full en el último tercio, por Cigar Coop en 2014, y como medium-full por un minorista en octubre de 2026."},{"name":"Fuente Fuente OpusX The Lost City","color":"#A0522D","force":"Medium-Full","wrapper":"República Dominicana","vitolas":[],"story":"Edición de OpusX cuyo tabaco, íntegramente dominicano, se plantó en el verano de 2004 en el Château de la Fuente para el rodaje de la película La ciudad perdida, estrenada en 2005 y dirigida por Andy Garcia, y después envejeció cinco años, según fuenteagedselection.com, que la califica de medium a fuerte. Torcida en la Tabacalera A. Fuente; una noticia de junio de 2024 la sitúa en la asignación anual Aged Selection entregada a los minoristas. Formatos: Robusto 5¼ x 50, Double Robusto 5¾ x 52, Toro 6¾ x 48, Lancero 7½ x 38 y Carlito''s A 9¼ x 47."}]',
  `gamme_de` = '[{"name":"Opus X","color":"#8B0000","force":"Full","story":"1995 lanciert, die große dominikanische Zigarre. Deckblatt Château de la Fuente — eine eigene Plantage, vertrauliche Produktion. Espresso, roter Pfeffer, goldene Zeder, Karamell. Die Perfección (doppeltes Figurado) ist die begehrteste Form. Unstete Verfügbarkeit und ein Wiederverkaufspreis, der den Listenpreis um ein Mehrfaches übersteigt: eine der spekulativsten Zigarren des Marktes.","vitolas":["Double Corona","Perfección No.1","Perfección No.2","Fuente Fuente","BBMF","Angel''s Share"],"wrapper":"Château de la Fuente (Dominikanische Republik)"},{"name":"Don Carlos","color":"#A0522D","force":"Medium-Full","story":"Eine Hommage an den Vater, Carlos Fuente Sr. Medium bis kräftig, Kamerun-Deckblatt über dominikanischem Tabak. Der Ausgleichspunkt des Hauses — weniger rar als die Opus X, zugänglicher, von einer Gleichmäßigkeit, die Liebhaber seit den 1970er-Jahren verfolgen. Kaffee, Leder, milde Gewürze. Das Eye of the Shark, ein Figurado, ist das Format, das sich das Haus für seine meisterwarteten Ausgaben vorbehält.","vitolas":["Robusto","No.1","No.2","No.3","Eye of the Shark"],"wrapper":"Kamerun"},{"name":"Hemingway","color":"#8B4513","force":"Medium","story":"In den 1980er-Jahren lanciert, in den Formaten Perfecto und Classico. Sie trägt den Namen des Schriftstellers, der in Kuba lebte — eine Hommage des Hauses, ohne dass ihm eine besondere Vorliebe für Zigarren belegt wäre. Der Einstieg zu Arturo Fuente: mild, cremig, ohne Härte. Die Masterpiece mit neun Zoll ist die längste Zigarre der Serie.","vitolas":["Classic","Short Story","Best Seller","Masterpiece","Signature"],"wrapper":"Kamerun"},{"name":"Añejo","color":"#722F37","force":"Medium-Full","story":"Deckblatt Connecticut Broadleaf Maduro, in Cognacfässern gereift — eine Premiere bei der Lancierung 1999. Cognac, belgische Schokolade, Cashew. Die Añejo No.77 Shark, ein Figurado, ist die Vitola, auf die die Anhänger des Hauses warten.","vitolas":["No.46","No.48","No.50","No.55","No.60","No.77 Shark"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Casa Cuba","color":"#8B5A2B","force":null,"wrapper":"Havana aus Ecuador","vitolas":[],"story":"Ende 2013 in begrenzter Zuteilung an Einzelhändler auf den Markt gebracht, sagt Cigar Coop, und von arturofuente.com als letzte Mischung des verstorbenen Carlos Fuente Sr. vorgestellt, gedacht als Erinnerung an die Zigarren, die er in jungen Jahren mit seinem Vater drehte und rauchte, mit kubanischem Tabak. Deckblatt Havana aus Ecuador über Umblatt und longfiller, beide dominikanisch und aus kubanischer Saat, gerollt in der Tabacalera A. Fuente y Cia. Die Formate tragen die Namen kubanischer Dominosteine: Doble Dos 6¾ x 42, Doble Tres 5½ x 44, Doble Cinco 5 x 50, Doble Seis 6 x 52, Doble Cuatro 4½ x 54 und Divine Inspiration 6⅛ x 47. Stärke von Cigar Coop 2014 als medium beschrieben, im letzten Drittel auf medium-full ansteigend, und von einem Einzelhändler im Oktober 2026 als medium-full."},{"name":"Fuente Fuente OpusX The Lost City","color":"#A0522D","force":"Medium-Full","wrapper":"Dominikanische Republik","vitolas":[],"story":"Edition von OpusX, deren Tabak, vollständig dominikanisch, im Sommer 2004 auf dem Château de la Fuente für die Dreharbeiten zum Film The Lost City (erschienen 2005, Regie: Andy Garcia) gepflanzt wurde und danach fünf Jahre gereift ist, laut fuenteagedselection.com, die sie als medium bis kräftig bezeichnet. Gerollt in der Tabacalera A. Fuente; eine Meldung vom Juni 2024 ordnet sie der jährlichen Zuteilung Aged Selection zu, die an Einzelhändler geliefert wird. Formate: Robusto 5¼ x 50, Double Robusto 5¾ x 52, Toro 6¾ x 48, Lancero 7½ x 38 und Carlito''s A 9¼ x 47."}]',
  `gamme_zh` = '[{"name":"Opus X","color":"#8B0000","force":"Full","story":"1995 年问世的多米尼加名作。茄衣来自 Château de la Fuente——一片独立的种植园，产量秘而不宣。浓缩咖啡、红胡椒、金色雪松、焦糖。双头收尖的 Perfección 最受追捧。供货飘忽，转售价数倍于目录价：市场上投机性最强的雪茄之一。","vitolas":["Double Corona","Perfección No.1","Perfección No.2","Fuente Fuente","BBMF","Angel''s Share"],"wrapper":"Château de la Fuente（多米尼加）"},{"name":"Don Carlos","color":"#A0522D","force":"Medium-Full","story":"向父亲卡洛斯·富恩特致敬。中偏浓，喀麦隆茄衣包多米尼加烟叶。这是这家老号的平衡点——不像 Opus X 那样难得，更容易入手，而它的稳定，爱好者从七十年代一路追到今天。咖啡、皮革、柔和香料。Eye of the Shark 是一款收尖形制，老号把它留给最受期待的出品。","vitolas":["Robusto","No.1","No.2","No.3","Eye of the Shark"],"wrapper":"喀麦隆"},{"name":"Hemingway","color":"#8B4513","force":"Medium","story":"推出于 1980 年代，采用 Perfectos 与 Classicos 两类形制。它取名自那位曾住在古巴的作家——这是老号的一份致敬，并没有材料证明他对雪茄有特别的偏好。这是进入富恩特的门：柔和、奶油感、不带侵略性。九英寸的 Masterpiece 是系列中最长的一支。","vitolas":["Classic","Short Story","Best Seller","Masterpiece","Signature"],"wrapper":"喀麦隆"},{"name":"Añejo","color":"#722F37","force":"Medium-Full","story":"康涅狄格宽叶马杜罗茄衣，在干邑桶中陈化——1999 年推出时尚属首创。干邑、比利时巧克力、腰果。收尖形制的 Añejo No.77 Shark，是这家老号的追随者们守候的那一款。","vitolas":["No.46","No.48","No.50","No.55","No.60","No.77 Shark"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Casa Cuba","color":"#8B5A2B","force":null,"wrapper":"厄瓜多尔Havana","vitolas":[],"story":"据Cigar Coop称，2013年末以限量配额形式面向零售商推出；arturofuente.com将其介绍为已故的Carlos Fuente Sr.的末款拼配，意在唤起他年轻时与父亲一起用古巴烟草卷制并吸食的雪茄。茄衣为厄瓜多尔Havana，内包叶与longfiller均产自多米尼加共和国，采用古巴种子，在Tabacalera A. Fuente y Cia卷制。规格以古巴多米诺骨牌的名称命名：Doble Dos 6¾ x 42、Doble Tres 5½ x 44、Doble Cinco 5 x 50、Doble Seis 6 x 52、Doble Cuatro 4½ x 54与Divine Inspiration 6⅛ x 47。力度在2014年被Cigar Coop称为medium，在末三分之一升至medium-full；2026年十月，一家零售商称其为medium-full。"},{"name":"Fuente Fuente OpusX The Lost City","color":"#A0522D","force":"Medium-Full","wrapper":"多米尼加共和国","vitolas":[],"story":"OpusX的一个版本，烟草全部产自多米尼加共和国，于2004年夏天在Château de la Fuente种植，用于拍摄电影The Lost City（2005年上映，由Andy Garcia执导），随后醇化五年，据fuenteagedselection.com所述；该网站称其力度为medium至浓郁。在Tabacalera A. Fuente卷制；2024年六月的一则快讯把它归入交付给零售商的年度配额Aged Selection。规格：Robusto 5¼ x 50、Double Robusto 5¾ x 52、Toro 6¾ x 48、Lancero 7½ x 38与Carlito''s A 9¼ x 47。"}]',
  `gamme_ar` = '[{"name":"Opus X","color":"#8B0000","force":"Full","story":"أُطلق عام 1995، وهو السيجار الدومينيكي الكبير. غلافه من « شاتو دي لا فوينتي » — مزرعة منفصلة وإنتاج سرّي. إسبريسّو، فلفل أحمر، أرز ذهبي، كراميل. وشكل البيرفيكسيون (فيغورادو مزدوج) هو الأكثر طلبًا. توافره متقلّب، وسعر إعادة بيعه يبلغ أضعاف سعر القائمة: من أكثر السيجارات مضاربةً في السوق.","vitolas":["Double Corona","Perfección No.1","Perfección No.2","Fuente Fuente","BBMF","Angel''s Share"],"wrapper":"Château de la Fuente (الجمهورية الدومينيكية)"},{"name":"Don Carlos","color":"#A0522D","force":"Medium-Full","story":"تحية إلى الأب، كارلوس فوينتي الأب. متوسط إلى قوي، غلاف كاميروني فوق تبغ دومينيكي. إنه نقطة التوازن لدى الدار: أقلّ ندرة من الـOpus X، وأسهل تناولًا، بثبات يتابعه المحبّون منذ السبعينيات. قهوة، جلد، توابل لطيفة. أما الـEye of the Shark، وهو شكل مدبَّب، فهو القياس الذي تحفظه الدار لأكثر إصداراتها ترقُّبًا.","vitolas":["Robusto","No.1","No.2","No.3","Eye of the Shark"],"wrapper":"كاميروني"},{"name":"Hemingway","color":"#8B4513","force":"Medium","story":"أُطلقت في ثمانينيات القرن الماضي، بشكلَي بيرفكتو وكلاسيكو. تحمل اسم الكاتب الذي عاش في كوبا — وهي تحية من الدار، دون أن يثبت له ذوق خاص بالسيجار. إنها مدخل أرتورو فوينتي: ناعمة، قشدية، بلا حِدّة. والـMasterpiece، بطول تسع بوصات، هو أطول سيجار في المجموعة.","vitolas":["Classic","Short Story","Best Seller","Masterpiece","Signature"],"wrapper":"كاميروني"},{"name":"Añejo","color":"#722F37","force":"Medium-Full","story":"غلاف كونيتيكت برودليف مادورو معتَّق في براميل كونياك — وكان ذلك سابقة عند إطلاقه عام 1999. كونياك، شوكولاتة بلجيكية، كاجو. أما الـAñejo No.77 Shark، ذو الشكل المدبَّب، فهو القياس الذي يترقّبه أتباع الدار.","vitolas":["No.46","No.48","No.50","No.55","No.60","No.77 Shark"],"wrapper":"Connecticut Broadleaf Maduro"},{"name":"Casa Cuba","color":"#8B5A2B","force":null,"wrapper":"Havana من الإكوادور","vitolas":[],"story":"أُطلقت في أواخر عام 2013 بحصة محدودة لتجار التجزئة، بحسب Cigar Coop، وتقدّمها arturofuente.com بوصفها آخر خلطة للراحل Carlos Fuente Sr.، صُمّمت لتستحضر السيجار الذي كان يلفّه ويدخّنه في شبابه مع والده، بتبغ كوبي. غلافها Havana من الإكوادور، على لفافة داخلية وlongfiller دومينيكانيين من بذور كوبية، لُفّت في Tabacalera A. Fuente y Cia. وتحمل المقاسات أسماء قطع الدومينو الكوبية: Doble Dos 6¾ x 42 وDoble Tres 5½ x 44 وDoble Cinco 5 x 50 وDoble Seis 6 x 52 وDoble Cuatro 4½ x 54 وDivine Inspiration 6⅛ x 47. وتُوصف القوة بأنها medium، وترتفع إلى medium-full في الثلث الأخير، لدى Cigar Coop عام 2014، وبأنها medium-full لدى تاجر تجزئة في أكتوبر 2026."},{"name":"Fuente Fuente OpusX The Lost City","color":"#A0522D","force":"Medium-Full","wrapper":"جمهورية الدومينيكان","vitolas":[],"story":"إصدار من OpusX، تبغه كله دومينيكاني، زُرع في صيف عام 2004 في Château de la Fuente لتصوير فيلم «المدينة المفقودة»، الذي صدر عام 2005 وأخرجه Andy Garcia، ثم عُتّق خمس سنوات، بحسب fuenteagedselection.com، التي تصفه بأنه من medium إلى قوي. لُفّ في Tabacalera A. Fuente؛ وتضعه برقية إخبارية صادرة في يونيو 2024 ضمن الحصة السنوية Aged Selection التي تُسلَّم إلى تجار التجزئة. المقاسات: Robusto 5¼ x 50 وDouble Robusto 5¾ x 52 وToro 6¾ x 48 وLancero 7½ x 38 وCarlito''s A 9¼ x 47."}]',
  `source` = IF(LOCATE('arturofuente.com « Casa Cuba | Arturo Fuente » (lue en octob', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'arturofuente.com « Casa Cuba | Arturo Fuente » (lue en octobre 2026 : dernier mélange de feu Carlos Fuente Sr. ; cape Havana d''Équateur, liant et longfiller dominicains de semence cubaine ; six formats, Doble Dos 42, Doble Tres 44, Doble Cinco 50, Doble Seis 52, Doble Cuatro 54, Divine Inspiration 47) ; arturofuente.com « Casa Cuba – a Carlos Fuente Sr. Original | Arturo Fuente » (lue en octobre 2026 : mélange destiné à rappeler les cigares que Carlos Fuente Sr. roulait et fumait jeune avec son père, avec du tabac cubain ; tailles nommées d''après les dominos cubains) ; cigar-coop.com « Cigar Review: Arturo Fuente Casa Cuba » (26 février 2014 : cape Havana d''Équateur, liant et longfiller dominicains, Tabacalera A. Fuente y Cia ; lancée fin 2013, allocation limitée aux détaillants ; force medium, medium-corsée au dernier tiers) ; cigarsdirect.com « Arturo Fuente Casa Cuba Doble Cinco Robusto » (lue en octobre 2026 : épuisée chez ce détaillant, force medium-corsée) ; fuenteagedselection.com « Fuente Fuente OpusX The Lost City » (lue en octobre 2026 : tabac dominicain, planté à l''été 2004 au Château de la Fuente pour le film The Lost City de 2005, vieilli cinq ans ; sept formats dont Robusto 5¼ x 50, Double Robusto 5¾ x 52, Toro 6¾ x 48, Lancero 7½ x 38, Carlito''s A 9¼ x 47 ; force medium à corsée) ; tobacconistofgreenwich.com « How Rare Is the Opus X Lost City and Who Makes It » (5 juin 2024 : cigares roulés à la Tabacalera A. Fuente, tabac planté et récolté en été, vieilli plus de cinq ans, medium à corsé) ; cigaraficionado.com « Aged Fuentes Arriving This Week » (17 juin 2024 : OpusX Lost City faite à la Tabacalera A. Fuente y Cia, dans l''allocation annuelle Aged Selection livrée ce mois-là ; tabac planté en juillet pendant le tournage au Château de la Fuente)')),
  `updated_at` = NOW()
 WHERE `name` = 'Arturo Fuente';

-- ── Ashton — paragraphe : Paradiso, gamme : San Cristobal ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Hors des États-Unis, la gamme San Cristobal d''Ashton, dont l', `history`) > 0, `history`, CONCAT(`history`, '

', 'Hors des États-Unis, la gamme San Cristobal d''Ashton, dont la fabrication est confiée en Nicaragua à la famille Garcia de My Father, à Estelí, se vend sous le nom Paradiso : un article de décembre 2015 l''explique par des raisons de marque. En octobre 2026, des détaillants allemands la proposent encore sous ce nom, en séries Paradiso by Ashton, Revelation, Quintessence et Elegancia. À ne pas confondre avec la marque cubaine San Cristóbal de La Habana.')),
  `history_en` = IF(LOCATE('Outside the United States, Ashton''s San Cristobal range, who', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'Outside the United States, Ashton''s San Cristobal range, whose manufacture is entrusted in Nicaragua to the Garcia family of My Father, in Estelí, is sold under the name Paradiso: an article of December 2015 explains it for brand reasons. In October 2026, German retailers still offer it under that name, in the series Paradiso by Ashton, Revelation, Quintessence and Elegancia. Not to be confused with the Cuban brand San Cristóbal de La Habana.')),
  `history_es` = IF(LOCATE('Fuera de los Estados Unidos, la gama San Cristobal de Ashton', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Fuera de los Estados Unidos, la gama San Cristobal de Ashton, cuya fabricación se confía en Nicaragua a la familia Garcia de My Father, en Estelí, se vende con el nombre Paradiso: un artículo de diciembre de 2015 lo explica por razones de marca. En octubre de 2026, minoristas alemanes siguen ofreciéndola con ese nombre, en las series Paradiso by Ashton, Revelation, Quintessence y Elegancia. No debe confundirse con la marca cubana San Cristóbal de La Habana.')),
  `history_de` = IF(LOCATE('Außerhalb der USA wird die Linie San Cristobal von Ashton, d', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Außerhalb der USA wird die Linie San Cristobal von Ashton, deren Herstellung in Nicaragua der Familie Garcia von My Father in Estelí anvertraut ist, unter dem Namen Paradiso verkauft: Ein Artikel vom Dezember 2015 erklärt das mit markenbezogenen Gründen. Im Oktober 2026 bieten deutsche Einzelhändler sie weiterhin unter diesem Namen an, in den Serien Paradiso by Ashton, Revelation, Quintessence und Elegancia. Nicht zu verwechseln mit der kubanischen Marke San Cristóbal de La Habana.')),
  `history_zh` = IF(LOCATE('在美国以外，Ashton的San Cristobal产品线在尼加拉瓜的制造委托给位于Estelí的My Father的G', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', '在美国以外，Ashton的San Cristobal产品线在尼加拉瓜的制造委托给位于Estelí的My Father的Garcia家族，以Paradiso之名销售：2015年十二月的一篇文章将此归因于品牌方面的原因。2026年十月，德国的零售商仍以此名供应，分为Paradiso by Ashton、Revelation、Quintessence与Elegancia几个系列。请勿与古巴品牌San Cristóbal de La Habana混淆。')),
  `history_ar` = IF(LOCATE('خارج الولايات المتحدة، يُباع خط San Cristobal من Ashton، الذ', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'خارج الولايات المتحدة، يُباع خط San Cristobal من Ashton، الذي أُوكل تصنيعه في نيكاراغوا إلى عائلة Garcia من My Father في Estelí، باسم Paradiso: يفسّر ذلك مقال صادر في ديسمبر 2015 بأسباب تتعلق بالعلامة. وفي أكتوبر 2026، لا يزال تجار تجزئة ألمان يعرضونه بهذا الاسم، ضمن سلاسل Paradiso by Ashton وRevelation وQuintessence وElegancia. ولا ينبغي الخلط بينه وبين العلامة الكوبية San Cristóbal de La Habana.')),
  `gamme` = '[{"name":"Ashton Classic","color":"#C9A96E","force":"Light-Medium","story":"La gamme fondatrice. Cape Connecticut Shade sur assemblage dominicain, roulée par Fuente. Notes de crème, vanille, céréales grillées. Régulière, élégante, sans surprise. Le format Magnum (52 x 127mm) est le plus demandé. L''Ashton Classic est le cigare qu''on offre quand on ne connaît pas les goûts de son invité.","vitolas":["No.1","No.2","Magnum","Churchill","Cordial","Panetela"],"wrapper":"Connecticut Shade"},{"name":"VSG — Virgin Sun Grown","color":"#8B0000","force":"Full","story":"Lancée en 1999 — l''autre Ashton. Cape d''Équateur cultivée en plein soleil, sur assemblage nicaraguayen et dominicain. Corsée : café noir, chocolat, poivre de Cayenne. La VSG révèle une maison capable de puissance quand elle choisit de l''exercer.","vitolas":["Torpedo","Robusto","Toro","Illuminado","Enchantment","Conquistador","Hero"],"wrapper":"Plein soleil d''Équateur"},{"name":"Cabinet Selection","color":"#A0522D","force":"Medium","story":"La gamme prestige — vieillie douze à vingt-quatre mois de plus en boîtes de cèdre espagnol après roulage. Cape Connecticut Shade. Notes de noisette affinée, miel de montagne, cèdre blanc. Complexe sans être exigeante : c''est exactement ce qu''elle cherche à être.","vitolas":["No.1","No.2","No.3","No.6","No.7","No.8","No.10"],"wrapper":"Connecticut Shade"},{"name":"San Cristobal","color":"#6B4226","force":null,"wrapper":"Équateur, selon la ligne","vitolas":[],"story":"Gamme nicaraguayenne lancée en 2007 avec José « Pepin » Garcia, faite par la famille Garcia à l''usine My Father d''Estelí. Quintessence, cape Habano Rosado d''Équateur sur longfillers nicaraguayens, est dite medium-corsée par Ashton Distributors, en six formats ; Golden Hour, annoncée aux détaillants en avril 2026 et montrée au PCA, ajoute six formats sous cape Habano d''Équateur, sur liant nicaraguayen et tripe des fermes Garcia, d''après Cigar Coop."}]',
  `gamme_en` = '[{"name":"Ashton Classic","color":"#C9A96E","force":"Light-Medium","story":"The founding range. Connecticut Shade wrapper over a Dominican blend, rolled by Fuente. Cream, vanilla, toasted cereal. Consistent, elegant, without surprises. The Magnum (52 x 127mm) is the most asked for. The Ashton Classic is the cigar you offer when you do not know your guest''s tastes.","vitolas":["No.1","No.2","Magnum","Churchill","Cordial","Panetela"],"wrapper":"Connecticut Shade"},{"name":"VSG — Virgin Sun Grown","color":"#8B0000","force":"Full","story":"Launched in 1999 — the other Ashton. Ecuadorian sun-grown wrapper over a Nicaraguan-Dominican blend. Full-bodied: black coffee, chocolate, cayenne pepper. The VSG reveals a house capable of power when it chooses to exercise it.","vitolas":["Torpedo","Robusto","Toro","Illuminado","Enchantment","Conquistador","Hero"],"wrapper":"Ecuadorian Sun-Grown"},{"name":"Cabinet Selection","color":"#A0522D","force":"Medium","story":"The prestige range — aged a further twelve to twenty-four months in Spanish cedar boxes after rolling. Connecticut Shade wrapper. Refined hazelnut, mountain honey, white cedar. Complex without being demanding: that is exactly what it sets out to be.","vitolas":["No.1","No.2","No.3","No.6","No.7","No.8","No.10"],"wrapper":"Connecticut Shade"},{"name":"San Cristobal","color":"#6B4226","force":null,"wrapper":"Ecuador, depending on line","vitolas":[],"story":"A Nicaraguan range launched in 2007 with José « Pepin » Garcia, made by the Garcia family at the My Father factory in Estelí. Quintessence, with an Ecuadorian Habano Rosado wrapper over Nicaraguan longfillers, is called medium-full by Ashton Distributors, in six formats; Golden Hour, announced to retailers in April 2026 and shown at the PCA, adds six formats under an Ecuadorian Habano wrapper, over a Nicaraguan binder and a filler from the Garcia farms, according to Cigar Coop."}]',
  `gamme_es` = '[{"name":"Ashton Classic","color":"#C9A96E","force":"Light-Medium","story":"La gama fundacional. Capa Connecticut Shade sobre ligada dominicana, liada por Fuente. Crema, vainilla, cereal tostado. Regular, elegante, sin sorpresas. El Magnum (52 x 127mm) es el más pedido. El Ashton Classic es el puro que se ofrece cuando no se conocen los gustos del invitado.","vitolas":["No.1","No.2","Magnum","Churchill","Cordial","Panetela"],"wrapper":"Connecticut Shade"},{"name":"VSG — Virgin Sun Grown","color":"#8B0000","force":"Full","story":"Lanzada en 1999: el otro Ashton. Capa ecuatoriana sun-grown sobre liga nicaragüense-dominicana. Con cuerpo: café negro, chocolate, pimienta de Cayena. La VSG revela una casa capaz de potencia cuando decide ejercerla.","vitolas":["Torpedo","Robusto","Toro","Illuminado","Enchantment","Conquistador","Hero"],"wrapper":"De sol de Ecuador"},{"name":"Cabinet Selection","color":"#A0522D","force":"Medium","story":"La gama prestigio, envejecida doce a veinticuatro meses más en cajas de cedro español tras el liado. Capa Connecticut Shade. Avellana afinada, miel de montaña, cedro blanco. Compleja sin ser exigente: es exactamente lo que busca ser.","vitolas":["No.1","No.2","No.3","No.6","No.7","No.8","No.10"],"wrapper":"Connecticut Shade"},{"name":"San Cristobal","color":"#6B4226","force":null,"wrapper":"Ecuador, según la línea","vitolas":[],"story":"Gama nicaragüense lanzada en 2007 con José « Pepin » Garcia, hecha por la familia Garcia en la fábrica My Father de Estelí. Quintessence, con capa Habano Rosado de Ecuador sobre longfillers nicaragüenses, es descrita como medium-full por Ashton Distributors, en seis formatos; Golden Hour, anunciada a los minoristas en abril de 2026 y presentada en la PCA, añade seis formatos bajo capa Habano de Ecuador, sobre capote nicaragüense y tripa de las fincas Garcia, según Cigar Coop."}]',
  `gamme_de` = '[{"name":"Ashton Classic","color":"#C9A96E","force":"Light-Medium","story":"Die Gründungsserie. Deckblatt Connecticut Shade über einer dominikanischen Mischung, von Fuente gerollt. Sahne, Vanille, geröstetes Getreide. Gleichmäßig, elegant, ohne Überraschungen. Das Magnum (52 x 127 mm) wird am häufigsten verlangt. Die Ashton Classic ist die Zigarre, die man anbietet, wenn man den Geschmack seines Gastes nicht kennt.","vitolas":["No.1","No.2","Magnum","Churchill","Cordial","Panetela"],"wrapper":"Connecticut Shade"},{"name":"VSG — Virgin Sun Grown","color":"#8B0000","force":"Full","story":"1999 lanciert — der andere Ashton. Ecuadorianisches Sun-Grown-Deckblatt über einer nicaraguanisch-dominikanischen Mischung. Kräftig: schwarzer Kaffee, Schokolade, Cayennepfeffer. Die VSG zeigt ein Haus, das Kraft aufbringen kann, wenn es das will.","vitolas":["Torpedo","Robusto","Toro","Illuminado","Enchantment","Conquistador","Hero"],"wrapper":"Sonnenanbau aus Ecuador"},{"name":"Cabinet Selection","color":"#A0522D","force":"Medium","story":"Die Prestige-Serie — nach dem Rollen weitere zwölf bis vierundzwanzig Monate in Kisten aus spanischer Zeder gereift. Deckblatt Connecticut Shade. Verfeinerte Haselnuss, Berghonig, weiße Zeder. Komplex, ohne fordernd zu sein: genau das will sie sein.","vitolas":["No.1","No.2","No.3","No.6","No.7","No.8","No.10"],"wrapper":"Connecticut Shade"},{"name":"San Cristobal","color":"#6B4226","force":null,"wrapper":"Ecuador, je nach Linie","vitolas":[],"story":"Nicaraguanische Linie, 2007 mit José « Pepin » Garcia auf den Markt gebracht, gefertigt von der Familie Garcia in der Fabrik My Father in Estelí. Quintessence, Deckblatt Habano Rosado aus Ecuador über nicaraguanischem longfiller, wird von Ashton Distributors als medium-full bezeichnet, in sechs Formaten; Golden Hour, im April 2026 Einzelhändlern angekündigt und auf der PCA gezeigt, ergänzt sechs Formate mit Deckblatt Habano aus Ecuador, über nicaraguanischem Umblatt und einer Einlage von den Garcia-Farmen, laut Cigar Coop."}]',
  `gamme_zh` = '[{"name":"Ashton Classic","color":"#C9A96E","force":"Light-Medium","story":"创立之初的系列。康涅狄格阴植茄衣，包裹多米尼加配方，由富恩特卷制。奶油、香草、烘烤谷物。稳定、优雅、没有意外。Magnum（52 x 127 毫米）是最常被点到的规格。当你不清楚客人的口味时，递上的就是这一支阿什顿。","vitolas":["No.1","No.2","Magnum","Churchill","Cordial","Panetela"],"wrapper":"Connecticut Shade"},{"name":"VSG — Virgin Sun Grown","color":"#8B0000","force":"Full","story":"1999 年推出——另一个面貌的 Ashton。厄瓜多尔日光茄衣，包裹尼加拉瓜与多米尼加的配方。厚实浓郁：黑咖啡、巧克力、卡宴辣椒。VSG 揭示了这家老号在愿意时同样能拿出力度。","vitolas":["Torpedo","Robusto","Toro","Illuminado","Enchantment","Conquistador","Hero"],"wrapper":"厄瓜多尔日光种植"},{"name":"Cabinet Selection","color":"#A0522D","force":"Medium","story":"旗舰系列——卷好之后，还要在西班牙雪松木盒里多陈化十二到二十四个月。康涅狄格阴植茄衣。细化的榛子、山地蜂蜜、白雪松。复杂却不费力，这正是它想要成为的样子。","vitolas":["No.1","No.2","No.3","No.6","No.7","No.8","No.10"],"wrapper":"Connecticut Shade"},{"name":"San Cristobal","color":"#6B4226","force":null,"wrapper":"厄瓜多尔，视产品线而定","vitolas":[],"story":"2007年与José « Pepin » Garcia合作推出的尼加拉瓜产品线，由Garcia家族在Estelí的My Father工厂制作。Quintessence的茄衣为厄瓜多尔Habano Rosado，覆于尼加拉瓜longfiller之上，据Ashton Distributors称力度为medium-full，共六种规格；Golden Hour于2026年四月向零售商宣布，并在PCA上亮相，新增六种规格，茄衣为厄瓜多尔Habano，内包叶为尼加拉瓜产，茄芯来自Garcia农场，据Cigar Coop称。"}]',
  `gamme_ar` = '[{"name":"Ashton Classic","color":"#C9A96E","force":"Light-Medium","story":"المجموعة المؤسِّسة. غلاف كونيتيكت شيد فوق خلطة دومينيكية، تُلفّ عند فوينتي. قشدة، فانيليا، حبوب محمّصة. ثابتة، أنيقة، بلا مفاجآت. والقياس Magnum (52 × 127 مم) هو الأكثر طلبًا. الـAshton Classic هو السيجار الذي تُقدّمه حين لا تعرف ذوق ضيفك.","vitolas":["No.1","No.2","Magnum","Churchill","Cordial","Panetela"],"wrapper":"Connecticut Shade"},{"name":"VSG — Virgin Sun Grown","color":"#8B0000","force":"Full","story":"أُطلقت عام 1999 — وجه آخر لأشتون. غلاف إكوادوري مزروع تحت الشمس فوق خلطة نيكاراغوية-دومينيكية. ممتلئة الجسم: قهوة سوداء، شوكولاتة، فلفل كايين. تكشف الـVSG عن دار قادرة على القوّة متى شاءت.","vitolas":["Torpedo","Robusto","Toro","Illuminado","Enchantment","Conquistador","Hero"],"wrapper":"مزروع في الشمس من الإكوادور"},{"name":"Cabinet Selection","color":"#A0522D","force":"Medium","story":"مجموعة المقام الرفيع — تُعتَّق بعد اللفّ من اثني عشر إلى أربعة وعشرين شهرًا إضافية في علب من الأرز الإسباني. غلاف كونيتيكت شيد. بندق مصفّى، عسل جبلي، أرز أبيض. معقّدة دون أن تكون متطلّبة: وهذا بالضبط ما تريد أن تكونه.","vitolas":["No.1","No.2","No.3","No.6","No.7","No.8","No.10"],"wrapper":"Connecticut Shade"},{"name":"San Cristobal","color":"#6B4226","force":null,"wrapper":"الإكوادور، بحسب الخط","vitolas":[],"story":"خط نيكاراغوي أُطلق عام 2007 مع José « Pepin » Garcia، صنعته عائلة Garcia في مصنع My Father في Estelí. أما Quintessence، بغلاف Habano Rosado من الإكوادور على longfiller نيكاراغوي، فتصفها Ashton Distributors بأنها medium-full، بستة مقاسات؛ وGolden Hour، التي أُعلن عنها لتجار التجزئة في أبريل 2026 وعُرضت في PCA، تضيف ستة مقاسات بغلاف Habano من الإكوادور، على لفافة داخلية من نيكاراغوا وحشوة من مزارع Garcia، بحسب Cigar Coop."}]',
  `mentions` = '["Paradiso"]',
  `source` = IF(LOCATE('cigarjournal.com « Paradiso (US: San Cristóbal) Revelation P', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigarjournal.com « Paradiso (US: San Cristóbal) Revelation Prophet… » (15 décembre 2015 : Paradiso, nom de San Cristóbal d''Ashton hors des États-Unis, pour des raisons de marque ; produit par José « Pepin » Garcia, My Father Cigars, au Nicaragua ; cape d''Équateur, liant et tripe du Nicaragua pour la Revelation) ; noblego.de « Paradiso by Ashton Zigarren online bei Noblego kaufen » (lue en octobre 2026, en allemand : famille García à Estelí ; cape Oscuro d''Équateur, liant et tripe du Nicaragua ; ligne sortie en 2007 avec José « Pepin » García ; la plupart des formats en stock) ; cigarworld.de « Paradiso: Zigarren kaufen » (lue en octobre 2026, version anglaise du site : quatre séries, By Ashton, Revelation, Quintessence et Elegancia, classées Nicaragua) ; cigaraficionado.com « San Cristobal » (page de marque, lue en octobre 2026 : marque datée de 2007, faite par la famille Garcia à l''usine My Father d''Estelí) ; ashtondistributors.com « San Cristobal Quintessence » (lue en octobre 2026 : cape Habano Rosado d''Équateur, longfillers nicaraguayens ; six formats, Belicoso, Churchill, Corona Gorda, Gordo, Robusto, Toro ; force Medium-Full) ; cigar-coop.com « Ashton to Introduce San Cristobal Golden Hour » (2 avril 2026 : cape Habano d''Équateur, liant nicaraguayen, tripe de fermes Garcia à Condega, Estelí, Jalapa et Namanji, faite à l''usine My Father d''Estelí ; six formats ; montrée au PCA d''avril 2026)')),
  `updated_at` = NOW()
 WHERE `name` = 'Ashton';

-- ── Casa de Alegria — paragraphe : La Chaveta ──
UPDATE `brands` SET
  `history` = IF(LOCATE('En octobre 2026, la Tabacalera Casa de Alegria roule aussi L', `history`) > 0, `history`, CONCAT(`history`, '

', 'En octobre 2026, la Tabacalera Casa de Alegria roule aussi La Chaveta, marque de Patricia et Marc Benden, qui dirigent Cigarworld : apparue à la fin de l''été 2025 et vendue, dit Cigarworld, exclusivement dans sa boutique en ligne, elle est roulée à Estelí par Ralf Westerwick, dit Smokersplanet.de. Sa ligne White, douce, est sous cape Connecticut Shade ; sa ligne Black, plus corsée, sous une cape foncée de type Criollo ; toutes deux sur tripe de tabacs nicaraguayens d''Estelí, de Jalapa et de Condega, en Minuto, Perla, Robusto et Toro.')),
  `history_en` = IF(LOCATE('In October 2026, the Tabacalera Casa de Alegria also rolls L', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'In October 2026, the Tabacalera Casa de Alegria also rolls La Chaveta, a brand of Patricia and Marc Benden, who run Cigarworld: it appeared at the end of summer 2025 and is sold, says Cigarworld, exclusively in its online shop, and is rolled in Estelí by Ralf Westerwick, says Smokersplanet.de. Its White line, mild, has a Connecticut Shade wrapper; its Black line, stronger, a dark Criollo-type wrapper; both over a filler of Nicaraguan tobaccos from Estelí, Jalapa and Condega, in Minuto, Perla, Robusto and Toro.')),
  `history_es` = IF(LOCATE('En octubre de 2026, la Tabacalera Casa de Alegria también tu', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'En octubre de 2026, la Tabacalera Casa de Alegria también tuerce La Chaveta, marca de Patricia y Marc Benden, que dirigen Cigarworld: aparecida a finales del verano de 2025 y vendida, dice Cigarworld, exclusivamente en su tienda en línea, la tuerce en Estelí Ralf Westerwick, dice Smokersplanet.de. Su línea White, suave, lleva capa Connecticut Shade; su línea Black, más fuerte, una capa oscura de tipo Criollo; ambas sobre tripa de tabacos nicaragüenses de Estelí, de Jalapa y de Condega, en Minuto, Perla, Robusto y Toro.')),
  `history_de` = IF(LOCATE('Im Oktober 2026 rollt die Tabacalera Casa de Alegria auch La', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Im Oktober 2026 rollt die Tabacalera Casa de Alegria auch La Chaveta, eine Marke von Patricia und Marc Benden, die Cigarworld leiten: Sie erschien Ende des Sommers 2025 und wird, so Cigarworld, ausschließlich im eigenen Online-Shop verkauft; gerollt wird sie in Estelí von Ralf Westerwick, so Smokersplanet.de. Ihre Linie White, mild, hat ein Deckblatt Connecticut Shade; ihre Linie Black, kräftiger, ein dunkles Deckblatt vom Typ Criollo; beide über einer Einlage aus nicaraguanischen Tabaken aus Estelí, Jalapa und Condega, in Minuto, Perla, Robusto und Toro.')),
  `history_zh` = IF(LOCATE('2026年十月，Tabacalera Casa de Alegria还卷制La Chaveta，这是Patricia与M', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', '2026年十月，Tabacalera Casa de Alegria还卷制La Chaveta，这是Patricia与Marc Benden的品牌，二人管理Cigarworld：该品牌于2025年夏末问世，据Cigarworld称仅在其网上商店出售，由Ralf Westerwick在Estelí卷制，据Smokersplanet.de称。其White系列口感温和，茄衣为Connecticut Shade；Black系列力度更强，茄衣为深色Criollo类型；两者均以来自Estelí、Jalapa与Condega的尼加拉瓜烟草作茄芯，规格有Minuto、Perla、Robusto与Toro。')),
  `history_ar` = IF(LOCATE('في أكتوبر 2026، تلفّ Tabacalera Casa de Alegria أيضًا La Cha', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'في أكتوبر 2026، تلفّ Tabacalera Casa de Alegria أيضًا La Chaveta، وهي علامة تعود إلى Patricia وMarc Benden، اللذين يديران Cigarworld: ظهرت في نهاية صيف عام 2025 وتُباع، بحسب Cigarworld، حصرًا في متجرها الإلكتروني، ويلفّها في Estelí Ralf Westerwick، بحسب Smokersplanet.de. أما خطها White، الخفيف، فبغلاف Connecticut Shade؛ وخطها Black، وهو أقوى من White، بغلاف داكن من نوع Criollo؛ وكلاهما على حشوة من تبغ نيكاراغوي من Estelí وJalapa وCondega، بمقاسات Minuto وPerla وRobusto وToro.')),
  `mentions` = '["Rosa Nicaragua","La Chaveta"]',
  `source` = IF(LOCATE('smokersplanet.de « La Chaveta: Cigarworlds Premium-Cigarren ', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'smokersplanet.de « La Chaveta: Cigarworlds Premium-Cigarren aus Nicaragua » (septembre 2025, en allemand : marque de Patricia et Marc Benden, direction de Cigarworld ; roulée par Ralf Westerwick à la Tabacalera Casa de Alegria d''Estelí ; ligne White, cape Connecticut Shade, liant et tripe du Nicaragua, mild ; Perla, Robusto et Toro) ; blog.cigarworld.de « La Chaveta: Unsere neue Premium-Zigarre aus Nicaragua » (22 septembre 2025, en allemand : marque de Patricia et Marc Benden ; Ralf Westerwick, un Allemand qui dirige une tabacalera à Estelí ; tripe de tabacs nicaraguayens d''Estelí, de Jalapa et de Condega ; mild et très aromatique ; Perla, Robusto, Toro) ; cigarworld.de « La Chaveta » (lue en octobre 2026, version anglaise du site : lignes White et Black, quatre formats chacune, Minuto, Perla, Robusto et Toro ; White sous cape Connecticut, Black sous cape foncée H.-Criollo, plus forte ; tripe d''Estelí, de Jalapa et de Condega ; vendue exclusivement dans la boutique ; sortie à la fin de l''été 2025 ; en stock)')),
  `updated_at` = NOW()
 WHERE `name` = 'Casa de Alegria';

-- ── Cohiba USA — paragraphe : Silencio ──
UPDATE `brands` SET
  `history` = IF(LOCATE('En octobre 2026, la version américaine de Cohiba se vend en ', `history`) > 0, `history`, CONCAT(`history`, '

', 'En octobre 2026, la version américaine de Cohiba se vend en Europe sous le nom Silencio, que STG, dont General Cigar fait partie depuis 2010, a choisi pour elle, dit Sean Williams, maître assembleur chez STG, en novembre 2022. Deux lignes y ont été lancées, Red Dot, qui fait 60 % de ses ventes selon lui, et Black ; Cigarworld liste sous Silencio les séries Red Dot, Black, Los Rios, Blue, Riviera et Series M. Aux États-Unis, Silencio est le nom du mélange signature de Williams.')),
  `history_en` = IF(LOCATE('In October 2026, the American version of Cohiba is sold in E', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'In October 2026, the American version of Cohiba is sold in Europe under the name Silencio, which STG, of which General Cigar has been part since 2010, chose for it, says Sean Williams, master blender at STG, in November 2022. Two lines were launched there, Red Dot, which makes up 60% of its sales according to him, and Black; Cigarworld lists under Silencio the series Red Dot, Black, Los Rios, Blue, Riviera and Series M. In the United States, Silencio is the name of Williams''s signature blend.')),
  `history_es` = IF(LOCATE('En octubre de 2026, la versión estadounidense de Cohiba se v', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'En octubre de 2026, la versión estadounidense de Cohiba se vende en Europa con el nombre Silencio, que STG, de la que General Cigar forma parte desde 2010, eligió para ella, dice Sean Williams, maestro mezclador en STG, en noviembre de 2022. Allí se lanzaron dos líneas, Red Dot, que representa el 60 % de sus ventas según él, y Black; Cigarworld enumera bajo Silencio las series Red Dot, Black, Los Rios, Blue, Riviera y Series M. En Estados Unidos, Silencio es el nombre de la mezcla de firma de Williams.')),
  `history_de` = IF(LOCATE('Im Oktober 2026 wird die amerikanische Version von Cohiba in', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Im Oktober 2026 wird die amerikanische Version von Cohiba in Europa unter dem Namen Silencio verkauft, den STG, zu dem General Cigar seit 2010 gehört, für sie gewählt hat, sagt Sean Williams, Master Blender bei STG, im November 2022. Zwei Linien wurden dort eingeführt, Red Dot, die nach seinen Angaben 60 % des Absatzes ausmacht, und Black; Cigarworld führt unter Silencio die Serien Red Dot, Black, Los Rios, Blue, Riviera und Series M auf. In den USA ist Silencio der Name der Signature-Mischung von Williams.')),
  `history_zh` = IF(LOCATE('2026年十月，Cohiba的美国版本在欧洲以Silencio之名销售，该名称由STG为其选定（General Ciga', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', '2026年十月，Cohiba的美国版本在欧洲以Silencio之名销售，该名称由STG为其选定（General Cigar自2010年起隶属STG），据STG调配大师Sean Williams于2022年十一月所述。当地推出了两个产品线：Red Dot（据他所说占其销量的60%）与Black；Cigarworld在Silencio名下列出Red Dot、Black、Los Rios、Blue、Riviera与Series M几个系列。在美国，Silencio是Williams的招牌拼配之名。')),
  `history_ar` = IF(LOCATE('في أكتوبر 2026، تُباع النسخة الأمريكية من Cohiba في أوروبا ب', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'في أكتوبر 2026، تُباع النسخة الأمريكية من Cohiba في أوروبا باسم Silencio، الذي اختارته لها STG، التي تضم General Cigar منذ عام 2010، بحسب Sean Williams، خبير المزج الرئيسي في STG، في نوفمبر 2022. وأُطلق هناك خطان: Red Dot، الذي يشكّل 60% من مبيعاته بحسب قوله، وBlack؛ وتُدرج Cigarworld تحت Silencio السلاسل Red Dot وBlack وLos Rios وBlue وRiviera وSeries M. أما في الولايات المتحدة فإن Silencio هو اسم الخلطة المميِّزة الخاصة بـ Williams.')),
  `mentions` = '["Silencio"]',
  `source` = IF(LOCATE('cigars-connect.com « The World of Silencio » (2 novembre 202', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigars-connect.com « The World of Silencio » (2 novembre 2022 : Silencio, nom choisi pour commercialiser la marque Cohiba américaine en Europe ; deux lignes lancées, Red Dot, 60 % des ventes selon Sean Williams, et Black ; Williams, maître assembleur de Silencio, arrivé chez STG en 2016 ; aux États-Unis, Silencio est son cigare signature) ; cigarworld.de « Silencio » (lue en octobre 2026, version anglaise du site : séries Red Dot, Black, Los Rios, Blue, Riviera et Series M ; certains articles marqués abandonnés) ; en.wikipedia.org « Scandinavian Tobacco Group » (lue en octobre 2026 : fusion du 26 avril 2010 entre Scandinavian Tobacco Group AB et les activités cigares et tabac à pipe de Swedish Match AB, filiales américaines General Cigar et Cigars International comprises)')),
  `updated_at` = NOW()
 WHERE `name` = 'Cohiba USA';

-- ── Davidoff — gamme : Back2Back ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Signature Series","color":"#C9A96E","force":"Medium","story":"La gamme fondatrice — Anniversario No.1 et No.2, lancés à Cuba en 1968. Depuis le transfert en République Dominicaine, les Anniversario dominicains sont devenus leur propre référence de finesse. Notes de fleurs blanches, céréales grillées, bois de santal. L''incarnation du luxe sans ostentation.","vitolas":["Anniversario No.1","Anniversario No.2","2000","3000","4000","5000"],"wrapper":"Dominicaine"},{"name":"Winston Churchill","color":"#8B6914","force":"Medium-Full","story":"Lancée en 2013, hommage au plus grand fumeur du XXe siècle. Collaboration avec la famille Churchill, autorisation officielle d''utiliser le nom et les archives photographiques. Plus corsée que la gamme classique Davidoff — un virage stylistique majeur. Notes de cuir, bois fumé, épices orientales. La Late Hour est la version nocturne, plus intense encore.","vitolas":["Toro","Robusto","Churchill","The Original","The Late Hour","The Statesman"],"wrapper":"Plein soleil d''Équateur"},{"name":"Nicaragua","color":"#8B2500","force":"Full","story":"Lancée en 2016, rupture stylistique totale. Davidoff explore le tabac nicaraguayen — le plus corsé de son catalogue. Notes de chocolat noir, café, cuir tanné. La gamme Nicaragua démontre que la maison genevoise peut naviguer dans toutes les intensités sans perdre son exigence de régularité.","vitolas":["Box Pressed Toro","Box Pressed Robusto","Box Pressed Torpedo"],"wrapper":"Nicaragua"},{"name":"Colorado","color":"#A0522D","force":"Medium","story":"Cape oscuro d''Équateur sur dominicain. La gamme intermédiaire entre la finesse de la Signature et la puissance de la Nicaragua. Notes de noisette, café au lait, épices légères. C''est celle qu''on trouve le plus souvent dans les lounges européens — accessible, régulière, gratifiante.","vitolas":["Robusto","Churchill","Toro"],"wrapper":"Colorado d''Équateur"},{"name":"Cusano","color":"#C9A96E","force":"Mild-Medium","story":"Une marque rachetée en juin 2009 à la famille Chiusano, après Camacho fin 2008 — le groupe achetait un accès au marché américain par le bas de la gamme de prix. Le recensement de cet atlas la prenait pour une maison.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Back2Back","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade, Nicaragua","vitolas":[],"story":"Reprise du Room101 Big Payback — d''après un article de juillet 2018, Matt Booth a gardé les noms de Room101 et Davidoff les assemblages — avec les artistes new-yorkais UR NY (Fernando Romero et Mike Baca), qui signent les boîtes ; présentée à l''IPCPR en juillet 2018 selon cet article, lancée début octobre 2018 selon Corona Cigar Co., qui range les deux versions en force légère à moyenne. Deux versions, Connecticut (cape Connecticut Shade d''Équateur, liant mexicain, tripes dominicaines) et Nicaragua (puro), en 5 x 50, 6 x 60 et 7 x 70, roulées à la main à Diadema Cigars de Honduras ; en octobre 2026, Corona Cigar Co. propose encore le Connecticut 7 x 70, le 6 x 60 est épuisé."}]',
  `gamme_en` = '[{"name":"Signature Series","color":"#C9A96E","force":"Medium","story":"The founding range — Anniversario No.1 and No.2, launched in Cuba in 1968. Since the Dominican transfer, these have become their own reference of finesse. Notes of white flowers, toasted grain, sandalwood. The incarnation of luxury without ostentation.","vitolas":["Anniversario No.1","Anniversario No.2","2000","3000","4000","5000"],"wrapper":"Dominican"},{"name":"Winston Churchill","color":"#8B6914","force":"Medium-Full","story":"Launched in 2013, tribute to the greatest smoker of the 20th century. Official collaboration with the Churchill family. Bolder than the classic Davidoff range — a major stylistic shift. Notes of leather, smoky wood, oriental spices. The Late Hour is the nocturnal, even more intense version.","vitolas":["Toro","Robusto","Churchill","The Original","The Late Hour","The Statesman"],"wrapper":"Ecuadorian Sun-Grown"},{"name":"Nicaragua","color":"#8B2500","force":"Full","story":"Launched 2016, total stylistic break. Davidoff explores Nicaraguan tobacco — the boldest in its catalog. Notes of dark chocolate, coffee, tanned leather. The Nicaragua range proves the Geneva house can navigate all intensities without sacrificing its demand for consistency.","vitolas":["Box Pressed Toro","Box Pressed Robusto","Box Pressed Torpedo"],"wrapper":"Nicaraguan"},{"name":"Colorado","color":"#A0522D","force":"Medium","story":"Ecuadorian oscuro wrapper over Dominican. The middle range between Signature finesse and Nicaragua power. Notes of hazelnut, café au lait, light spices. The best-seller in European lounges — accessible, consistent, rewarding.","vitolas":["Robusto","Churchill","Toro"],"wrapper":"Ecuadorian Colorado"},{"name":"Cusano","color":"#C9A96E","force":"Mild-Medium","story":"A brand bought in June 2009 from the Chiusano family, after Camacho in late 2008 — the group was buying access to the American market through the low end of the price range. This atlas''s census took it for a house.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Back2Back","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade, Nicaragua","vitolas":[],"story":"A take-over of the Room101 Big Payback — according to an article from July 2018, Matt Booth kept the Room101 names and Davidoff the blends — with the New York artists UR NY (Fernando Romero and Mike Baca), who sign the boxes; presented at the IPCPR in July 2018 according to that article, launched in early October 2018 according to Corona Cigar Co., which rates both versions as mild to medium in strength. Two versions, Connecticut (Ecuadorian Connecticut Shade wrapper, Mexican binder, Dominican filler) and Nicaragua (puro), in 5 x 50, 6 x 60 and 7 x 70, hand-rolled at Diadema Cigars de Honduras; in October 2026, Corona Cigar Co. still offers the Connecticut 7 x 70, while the 6 x 60 is sold out."}]',
  `gamme_es` = '[{"name":"Signature Series","color":"#C9A96E","force":"Medium","story":"La gama fundadora: Anniversario No.1 y No.2, lanzados en Cuba en 1968. Desde el traslado a la República Dominicana, los Anniversario dominicanos se han convertido en su propia referencia de finura. Flores blancas, cereales tostados, sándalo. La encarnación del lujo sin ostentación.","vitolas":["Anniversario No.1","Anniversario No.2","2000","3000","4000","5000"],"wrapper":"Dominicana"},{"name":"Winston Churchill","color":"#8B6914","force":"Medium-Full","story":"Lanzada en 2013, homenaje al mayor fumador del siglo XX. Colaboración con la familia Churchill, con autorización oficial para usar el nombre y los archivos fotográficos. Más fuerte que la gama clásica de Davidoff, un giro estilístico mayor. Cuero, madera ahumada, especias orientales. La Late Hour es la versión nocturna, más intensa aún.","vitolas":["Toro","Robusto","Churchill","The Original","The Late Hour","The Statesman"],"wrapper":"De sol de Ecuador"},{"name":"Nicaragua","color":"#8B2500","force":"Full","story":"Lanzada en 2016, ruptura estilística total. Davidoff explora el tabaco nicaragüense, el más fuerte de su catálogo. Chocolate negro, café, cuero curtido. La gama Nicaragua demuestra que la casa ginebrina puede navegar por todas las intensidades sin renunciar a su exigencia de regularidad.","vitolas":["Box Pressed Toro","Box Pressed Robusto","Box Pressed Torpedo"],"wrapper":"Nicaragua"},{"name":"Colorado","color":"#A0522D","force":"Medium","story":"Capa oscuro de Ecuador sobre dominicano. La gama intermedia entre la finura de Signature y la potencia de Nicaragua. Avellana, café con leche, especias ligeras. La más vendida en los lounges europeos: accesible, regular, gratificante.","vitolas":["Robusto","Churchill","Toro"],"wrapper":"Colorado de Ecuador"},{"name":"Cusano","color":"#C9A96E","force":"Mild-Medium","story":"Una marca comprada en junio de 2009 a la familia Chiusano, tras Camacho a finales de 2008 — el grupo compraba un acceso al mercado estadounidense por la parte baja de los precios. El censo de este atlas la tomaba por una casa.","vitolas":[],"wrapper":"No divulgada"},{"name":"Back2Back","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade, Nicaragua","vitolas":[],"story":"Retoma del Room101 Big Payback —según un artículo de julio de 2018, Matt Booth conservó los nombres de Room101 y Davidoff las mezclas— con los artistas neoyorquinos UR NY (Fernando Romero y Mike Baca), que firman las cajas; presentada en el IPCPR en julio de 2018 según ese artículo, lanzada a principios de octubre de 2018 según Corona Cigar Co., que sitúa las dos versiones en una fuerza ligera a media. Dos versiones, Connecticut (capa Connecticut Shade de Ecuador, capote mexicano, tripa dominicana) y Nicaragua (puro), en 5 x 50, 6 x 60 y 7 x 70, enrolladas a mano en Diadema Cigars de Honduras; en octubre de 2026, Corona Cigar Co. todavía ofrece el Connecticut 7 x 70, mientras que el 6 x 60 está agotado."}]',
  `gamme_de` = '[{"name":"Signature Series","color":"#C9A96E","force":"Medium","story":"Die Gründungsserie — Anniversario No.1 und No.2, 1968 auf Kuba lanciert. Seit dem Umzug in die Dominikanische Republik sind die dominikanischen Anniversario zu ihrem eigenen Maßstab an Finesse geworden. Weiße Blüten, geröstetes Getreide, Sandelholz. Die Verkörperung von Luxus ohne Zurschaustellung.","vitolas":["Anniversario No.1","Anniversario No.2","2000","3000","4000","5000"],"wrapper":"Dominikanisch"},{"name":"Winston Churchill","color":"#8B6914","force":"Medium-Full","story":"2013 lanciert, eine Hommage an den größten Raucher des 20. Jahrhunderts. Zusammenarbeit mit der Familie Churchill, mit offizieller Erlaubnis zur Nutzung des Namens und der Fotoarchive. Kräftiger als die klassische Davidoff-Serie — eine erhebliche stilistische Wende. Leder, Rauchholz, orientalische Gewürze. Die Late Hour ist die nächtliche, noch intensivere Fassung.","vitolas":["Toro","Robusto","Churchill","The Original","The Late Hour","The Statesman"],"wrapper":"Sonnenanbau aus Ecuador"},{"name":"Nicaragua","color":"#8B2500","force":"Full","story":"2016 lanciert, ein völliger Stilbruch. Davidoff erkundet den nicaraguanischen Tabak — den kräftigsten des Katalogs. Zartbitterschokolade, Kaffee, gegerbtes Leder. Die Nicaragua-Serie zeigt, dass das Genfer Haus alle Intensitäten befahren kann, ohne seinen Anspruch auf Gleichmäßigkeit aufzugeben.","vitolas":["Box Pressed Toro","Box Pressed Robusto","Box Pressed Torpedo"],"wrapper":"Nicaragua"},{"name":"Colorado","color":"#A0522D","force":"Medium","story":"Ecuadorianisches Oscuro-Deckblatt über Dominikanischem. Die Serie zwischen der Finesse der Signature und der Kraft der Nicaragua. Haselnuss, Milchkaffee, leichte Gewürze. Die meistverkaufte in europäischen Lounges — zugänglich, gleichmäßig, befriedigend.","vitolas":["Robusto","Churchill","Toro"],"wrapper":"Colorado aus Ecuador"},{"name":"Cusano","color":"#C9A96E","force":"Mild-Medium","story":"Eine Marke, im Juni 2009 von der Familie Chiusano gekauft, nach Camacho Ende 2008 — der Konzern kaufte sich Zugang zum amerikanischen Markt über das untere Preissegment. Die Zählung dieses Atlas hielt sie für ein Haus.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Back2Back","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade, Nicaragua","vitolas":[],"story":"Übernahme des Room101 Big Payback – laut einem Artikel vom Juli 2018 behielt Matt Booth die Namen von Room101 und Davidoff die Mischungen – gemeinsam mit den New Yorker Künstlern UR NY (Fernando Romero und Mike Baca), die die Schachteln signieren; auf der IPCPR im Juli 2018 vorgestellt, so dieser Artikel, und Anfang Oktober 2018 auf den Markt gebracht, so Corona Cigar Co., das beide Versionen als leicht bis mittelkräftig einstuft. Zwei Versionen, Connecticut (Deckblatt Connecticut Shade aus Ecuador, mexikanisches Umblatt, dominikanische Einlage) und Nicaragua (puro), in 5 x 50, 6 x 60 und 7 x 70, von Hand gerollt bei Diadema Cigars de Honduras; im Oktober 2026 bietet Corona Cigar Co. weiterhin den Connecticut 7 x 70 an, der 6 x 60 ist ausverkauft."}]',
  `gamme_zh` = '[{"name":"Signature Series","color":"#C9A96E","force":"Medium","story":"奠基系列——Anniversario No.1 与 No.2，1968 年在古巴问世。自迁往多米尼加以来，多米尼加版的 Anniversario 已自成细腻的标杆。白花、烤谷物、檀香。这是不事张扬的奢华的化身。","vitolas":["Anniversario No.1","Anniversario No.2","2000","3000","4000","5000"],"wrapper":"多米尼加"},{"name":"Winston Churchill","color":"#8B6914","force":"Medium-Full","story":"2013 年推出，向二十世纪最著名的烟客致敬。与丘吉尔家族合作，获正式授权使用其姓名与照片档案。比大卫杜夫的经典系列更浓厚——一次重大的风格转向。皮革、烟熏木、东方香料。Late Hour 是它的夜间版本，更为强烈。","vitolas":["Toro","Robusto","Churchill","The Original","The Late Hour","The Statesman"],"wrapper":"厄瓜多尔日光种植"},{"name":"Nicaragua","color":"#8B2500","force":"Full","story":"2016 年推出，是一次彻底的风格断裂。大卫杜夫转向尼加拉瓜烟叶——其目录中最浓烈的一种。黑巧克力、咖啡、鞣制皮革。Nicaragua 系列证明这家日内瓦老号能够驾驭各种强度，而不放弃它对稳定性的要求。","vitolas":["Box Pressed Toro","Box Pressed Robusto","Box Pressed Torpedo"],"wrapper":"尼加拉瓜"},{"name":"Colorado","color":"#A0522D","force":"Medium","story":"厄瓜多尔深色茄衣，内裹多米尼加烟叶。介于 Signature 的细腻与 Nicaragua 的力度之间的中间系列。榛子、欧蕾咖啡、轻盈香料。它是欧洲雪茄馆里最畅销的一款——平易、稳定、令人满足。","vitolas":["Robusto","Churchill","Toro"],"wrapper":"厄瓜多尔 Colorado"},{"name":"Cusano","color":"#C9A96E","force":"Mild-Medium","story":"2009年6月从基乌萨诺家族买下的品牌，紧随2008年底的 Camacho——集团借低价位打入美国市场。本图集的普查曾把它当作一家公司。","vitolas":[],"wrapper":"未公开"},{"name":"Back2Back","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade，Nicaragua","vitolas":[],"story":"接手Room101 Big Payback——据2018年七月的一篇文章，Matt Booth保留了Room101的名称，Davidoff保留了拼配——并与纽约艺术家团队UR NY（Fernando Romero和Mike Baca）合作，他们在雪茄盒上署名；据该文章，于2018年七月在IPCPR上亮相，而据Corona Cigar Co.，于2018年十月初推出，该公司将两个版本都归为烟力轻至中等。共两个版本：Connecticut（厄瓜多尔Connecticut Shade茄衣，墨西哥茄套，多米尼加茄芯）与Nicaragua（puro），规格为5 x 50、6 x 60和7 x 70，由Diadema Cigars de Honduras手工卷制；2026年十月，Corona Cigar Co.仍在销售Connecticut 7 x 70，6 x 60已售罄。"}]',
  `gamme_ar` = '[{"name":"Signature Series","color":"#C9A96E","force":"Medium","story":"المجموعة المؤسِّسة — أنيفيرساريو No.1 وNo.2، أُطلقتا في كوبا عام 1968. ومنذ الانتقال إلى جمهورية الدومينيكان، صارت الأنيفيرساريو الدومينيكية مرجعًا في الرهافة بذاتها. زهور بيضاء، حبوب محمّصة، خشب الصندل. إنها تجسيد للترف من غير استعراض.","vitolas":["Anniversario No.1","Anniversario No.2","2000","3000","4000","5000"],"wrapper":"دومينيكي"},{"name":"Winston Churchill","color":"#8B6914","force":"Medium-Full","story":"أُطلقت عام 2013 تحيةً لأشهر مدخّني القرن العشرين. بالتعاون مع عائلة تشرشل، وبإذن رسمي باستخدام الاسم والأرشيف المصوَّر. أقوى من مجموعة دافيدوف الكلاسيكية — منعطف أسلوبيّ كبير. جلد، خشب مدخَّن، توابل شرقية. أما الـLate Hour فهي النسخة الليلية، وهي أشدّ.","vitolas":["Toro","Robusto","Churchill","The Original","The Late Hour","The Statesman"],"wrapper":"مزروع في الشمس من الإكوادور"},{"name":"Nicaragua","color":"#8B2500","force":"Full","story":"أُطلقت عام 2016، وهي قطيعة أسلوبية تامّة. تستكشف دافيدوف التبغ النيكاراغوي — الأقوى في قائمتها. شوكولاتة داكنة، قهوة، جلد مدبوغ. تُثبت مجموعة نيكاراغوا أن الدار الجنيفية قادرة على الإبحار في كل درجات الشدّة دون أن تتخلّى عن صرامتها في الانتظام.","vitolas":["Box Pressed Toro","Box Pressed Robusto","Box Pressed Torpedo"],"wrapper":"نيكاراغوي"},{"name":"Colorado","color":"#A0522D","force":"Medium","story":"غلاف أوسكورو إكوادوري فوق تبغ دومينيكي. المجموعة الوسطى بين رهافة السيغنتشر وقوّة نيكاراغوا. بندق، قهوة بالحليب، توابل خفيفة. وهي الأكثر مبيعًا في صالات أوروبا — في المتناول، منتظمة، مُرضية.","vitolas":["Robusto","Churchill","Toro"],"wrapper":"Colorado من الإكوادور"},{"name":"Cusano","color":"#C9A96E","force":"Mild-Medium","story":"علامةٌ اشتُريت في حزيران/يونيو 2009 من عائلة كيوزانو، بعد Camacho في أواخر 2008 — كانت المجموعة تشتري منفذًا إلى السوق الأمريكية من أسفل سلّم الأسعار. وكان إحصاء هذا الأطلس يحسبها دارًا.","vitolas":[],"wrapper":"غير معلن"},{"name":"Back2Back","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade، Nicaragua","vitolas":[],"story":"استئناف لـ Room101 Big Payback — بحسب مقال من يوليو 2018، احتفظ Matt Booth بأسماء Room101 بينما احتفظت Davidoff بالتوليفات — بالتعاون مع الفنانين النيويوركيين UR NY (Fernando Romero وMike Baca)، اللذين يوقّعان العلب؛ قُدّم في IPCPR في يوليو 2018 بحسب ذلك المقال، وأُطلق في مطلع أكتوبر 2018 بحسب Corona Cigar Co.، التي تصنّف النسختين ضمن قوة خفيفة إلى متوسطة. نسختان: Connecticut (الغلاف الخارجي Connecticut Shade من الإكوادور، رابط مكسيكي، حشوة دومينيكانية) وNicaragua (puro)، بمقاسات 5 x 50 و6 x 60 و7 x 70، تُلَفّ يدويًا في Diadema Cigars de Honduras؛ وفي أكتوبر 2026 ما زالت Corona Cigar Co. تعرض Connecticut 7 x 70، بينما نفد 6 x 60."}]',
  `source` = IF(LOCATE('cigar-coop.com « Cigar News: Davidoff Lauches Back2Back Bran', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « Cigar News: Davidoff Lauches Back2Back Brand at 2018 IPCPR » (juillet 2018 : Back2Back appartient à Davidoff, reprise du Room101 Big Payback dont Davidoff garde les assemblages et Matt Booth les noms ; artwork des artistes UR NY ; deux blends, Connecticut Shade équatorien sur liant mexicain et tripes dominicaines, et puro nicaraguayen, en 5 x 50, 6 x 60 et 7 x 70 ; fabriquée à Diadema Cigars de Honduras, S.A. ; présentée à l''IPCPR) ; stogiepress.com « Cigar Review: Davidoff Back2Back Nicaragua » (31 mai 2019 : roulée à la main à Diadema Cigars de Honduras, S.A., au Honduras) ; coronacigar.com « Back2Back Urny Connecticut » (octobre 2026 : lancée début octobre 2018 par Davidoff et UR NY, force légère à moyenne, Connecticut Shade équatorien, liant mexicain, tripes dominicaines ; 7 x 70 en stock, 6 x 60 épuisé)')),
  `updated_at` = NOW()
 WHERE `name` = 'Davidoff';

-- ── Don Diego — paragraphe : Playboy ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Le nom Playboy est celui du magazine, pas celui de la maison', `history`) > 0, `history`, CONCAT(`history`, '

', 'Le nom Playboy est celui du magazine, pas celui de la maison. Playboy by Don Diego a été lancé en 1996 lors d''un événement au Playboy Mansion ; Playboy a ensuite eu des cigares en nom propre, dont Cigarworld classe une série, introduite le 25 mai 2009, en République dominicaine, entièrement à la main.')),
  `history_en` = IF(LOCATE('The name Playboy is that of the magazine, not that of the co', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'The name Playboy is that of the magazine, not that of the company. Playboy by Don Diego was launched in 1996 at an event at the Playboy Mansion; Playboy subsequently had cigars under its own name, among them one series, introduced on 25 May 2009, which Cigarworld classifies under the Dominican Republic, entirely handmade.')),
  `history_es` = IF(LOCATE('El nombre Playboy es el de la revista, no el de la casa. Pla', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'El nombre Playboy es el de la revista, no el de la casa. Playboy by Don Diego se lanzó en 1996 durante un evento en la Playboy Mansion; Playboy tuvo después puros con su propio nombre, entre ellos una serie, introducida el 25 de mayo de 2009, que Cigarworld clasifica en la República Dominicana, enteramente a mano.')),
  `history_de` = IF(LOCATE('Der Name Playboy ist der des Magazins, nicht der des Hauses.', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Der Name Playboy ist der des Magazins, nicht der des Hauses. Playboy by Don Diego wurde 1996 bei einer Veranstaltung in der Playboy Mansion eingeführt; Playboy hatte anschließend Zigarren unter eigenem Namen, darunter eine Serie, eingeführt am 25. Mai 2009, die Cigarworld der Dominikanischen Republik zuordnet, vollständig von Hand gefertigt.')),
  `history_zh` = IF(LOCATE('Playboy这个名称属于杂志，而不属于这家公司。Playboy by Don Diego于1996年在Playboy ', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', 'Playboy这个名称属于杂志，而不属于这家公司。Playboy by Don Diego于1996年在Playboy Mansion举办的一场活动上推出；此后Playboy有了以自身名义发行的雪茄，其中Cigarworld将一个系列（2009年五月25日推出）归入多米尼加共和国，完全手工制作。')),
  `history_ar` = IF(LOCATE('اسم Playboy هو اسم المجلة، وليس اسم الشركة. أُطلق Playboy by', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'اسم Playboy هو اسم المجلة، وليس اسم الشركة. أُطلق Playboy by Don Diego في عام 1996 خلال فعالية في Playboy Mansion؛ ثم صارت لدى Playboy بعد ذلك سيجارات باسمها الخاص، منها سلسلة، قُدّمت في 25 مايو 2009، تصنّفها Cigarworld ضمن جمهورية الدومينيكان، مصنوعة بالكامل يدويًا.')),
  `mentions` = '["Playboy"]',
  `source` = IF(LOCATE('cigaraficionado.com « Playboy By Don Diego Cigars at Fantasy', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigaraficionado.com « Playboy By Don Diego Cigars at Fantasy Party » (20 septembre 2006 : Playboy by Don Diego lancé en 1996 lors d''un événement au Playboy Mansion) ; cigarworld.de « Playboy » (octobre 2026 : série Playboy classée République dominicaine, introduite le 25 mai 2009, entièrement à la main) ; altadisusa.com « Cigars » (octobre 2026 : liste des marques d''Altadis USA avec Don Diego et sans Playboy ; les adresses altadisusa.com/cigars/don-diego/playboy-don-diego et playboy-don-diego2 renvoient une erreur 404) ; cigar-coop.com « Kingmakers Announces Playboy Cigar Collection » (8 janvier 2026 : Kingmakers annonce une collection Playboy, Toro 6 x 54 roulé à Estelí ; Playboy a eu des cigares d''abord sous Don Diego d''Altadis, puis en nom propre) ; cigardojo.com « Playboy Reenters the Cigar Space Through New Partnership with Kingmakers » (janvier 2026 : la sortie coïncide avec la réintroduction du magazine Playboy)')),
  `updated_at` = NOW()
 WHERE `name` = 'Don Diego';

-- ── Drew Estate — gamme : Ambrosia, Blackened, Chateau Real, Factory Smokes ──
UPDATE `brands` SET
  `gamme` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"La gamme infusée qui a fait connaître la maison — arômes de thé, herbes botaniques, essence florale. Format Robusto (54 x 127mm). Cape d''Indonésie sur un assemblage que Drew Estate ne détaille pas. C''est le cigare qui a fait entrer dans le genre des fumeurs que la puissance des assemblages traditionnels aurait écartés. Contesté chez les puristes, adoré de ses amateurs.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonésie"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"L''autre visage de Drew Estate — le plus sérieux, le plus recherché. Cape Connecticut Broadleaf Habano sur triple ligero nicaraguayen. Notes de café ristretto, cacao amer, mûre. La Flying Pig, perfecto court et trapu, est le format le plus rare et le plus cher de la gamme.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Créée par les torcedores eux-mêmes — les ouvriers de l''usine voulaient un cigare aussi bon que la Liga Privada à un prix qu''ils pouvaient payer. Assemblage proche du No.9, sous une cape d''Équateur moins coûteuse. Notes de chocolat, café, poivre.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Équateur"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"Le cigare de Willy Herrera, l''assembleur d''El Titan de Bronze à Miami engagé en 2011, lancé au début de 2013 sur une recette composée lors de sa première visite à Estelí. Le recensement de cet atlas le prenait pour une maison.","vitolas":[],"wrapper":"Habano d''Équateur"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"Du tabac de Kentucky séché à la fumée de bois, comme celui des pipes, dans un cigare roulé à Estelí. Une ligne, pas une maison.","vitolas":[],"wrapper":"Kentucky séché au feu"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013 — le cigare que les rouleurs se font, dit la maison : broadleaf, rustique, un seul format au départ.","vitolas":[],"wrapper":"Broadleaf du Connecticut"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015 — la version corsée d''Herrera Estelí, cape San Andrés.","vitolas":[],"wrapper":"San Andrés (Mexique)"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Ligne infusée : selon Corona Cigar Co., des épices d''Europe et d''Asie du Sud-Est, du vin et du rhum sur des tabacs du Honduras et du Nicaragua, avec, d''après CigarPlace, quatre mois d''infusion puis un vieillissement en armoires de cèdre. En octobre 2026, Corona Cigar Co. en affiche sept déclinaisons (Kaya, Mother Earth, Nectar, Spice Torpedo, Spice Triple Corona, Vann Reef, Clove Tiki) sous des capes Connecticut Shade, Habano, Sumatra ou Cameroun, Cigars Direct donne le cigarillo Clove Tiki roulé à la main, et le catalogue en ligne de Drew Estate ne la liste pas."},{"name":"Blackened","color":"#4A3728","force":null,"wrapper":"San Andrés, Connecticut Shade","vitolas":[],"story":"Collaboration entre Drew Estate, James Hetfield (Metallica) et Rob Dietrich (whisky Blackened), dit la maison. La M81, sortie le 18 octobre 2022 d''après un article de presse, associe une cape San Andrés maduro à un liant Connecticut Broadleaf maduro, en Corona, Robusto, Toro et Corona Doble ; la S84 Shade to Black, début 2024 selon Corona Cigar Co., passe à une cape Connecticut Shade d''Équateur, et drewestate.com présente ces deux expressions en octobre 2026."},{"name":"Chateau Real","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"Lancée en 2006, quand la maison faisait ses débuts dans le cigare non infusé, puis abandonnée, elle a été annoncée de retour le 9 novembre 2023 en Connecticut Shade sur liant et tripes nicaraguayens, pour les détaillants en ligne du réseau Drew Diplomat. Drew Estate y a ajouté un Habano pour Cigars International en août 2024 et un Maduro San Andrés pour ses comptes DDDP le 1er novembre 2024, tous roulés à La Gran Fabrica en Robusto, Toro et Churchill ; en octobre 2026, la page produits de drewestate.com ne la liste pas parmi ses lignes."},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Cigares vendus en bottes de 20 ou 25 : communiqué de la maison du 29 juin 2018, présentation à l''IPCPR en juillet 2018, quatre déclinaisons (Sweet à cape Habano, Maduro, Shade, Sun Grown) sur liant et tripes d''Indonésie, roulées à La Gran Fabrica en Robusto, Toro, Churchill et Gordito. En octobre 2026, drewestate.com la présente avec Maduro, Sweet, Shade et Sun Grown."}]',
  `gamme_en` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"The infused best-seller — aromas of tea, botanical herbs, floral essence. Robusto format (54 x 127mm). The cigar that introduced millions of Americans to cigars without intimidating them with traditional blend power. Indonesian wrapper over Drew Estate proprietary blend. Controversial among purists, adored by fans.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonesian"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"The other face of Drew Estate — the most serious, the most sought after. Connecticut Broadleaf Habano wrapper over Nicaraguan triple ligero. Ristretto coffee, bitter cocoa, blackberry. The Flying Pig, a short stubby perfecto, is the rarest and dearest shape in the range.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Created by the torcedores themselves — factory workers who wanted a cigar as good as Liga Privada at an accessible price. Blend close to the No.9, less expensive Ecuadorian wrapper. Notes of chocolate, coffee, pepper. The most successful worker rebellion in the industry.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Ecuadorian"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"Willy Herrera''s cigar — the El Titan de Bronze blender from Miami, hired in 2011 — launched in early 2013 on a recipe composed during his first visit to Estelí. This atlas''s census took it for a house.","vitolas":[],"wrapper":"Ecuadorian Habano"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"Kentucky tobacco cured over wood smoke, as for pipes, in a cigar rolled in Estelí. A line, not a house.","vitolas":[],"wrapper":"Fire-cured Kentucky"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013 — the cigar rollers make for themselves, the house says: broadleaf, rustic, a single size at first.","vitolas":[],"wrapper":"Connecticut broadleaf"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015 — the full-bodied version of Herrera Estelí, San Andrés wrapper.","vitolas":[],"wrapper":"San Andrés (Mexico)"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Infused line: according to Corona Cigar Co., spices from Europe and South-East Asia, wine and rum on tobaccos from Honduras and Nicaragua, with, according to CigarPlace, four months of infusion followed by ageing in cedar cabinets. In October 2026, Corona Cigar Co. lists seven versions of it (Kaya, Mother Earth, Nectar, Spice Torpedo, Spice Triple Corona, Vann Reef, Clove Tiki) under Connecticut Shade, Habano, Sumatra or Cameroon wrappers, Cigars Direct gives the Clove Tiki cigarillo as hand-rolled, and Drew Estate''s online catalogue does not list it."},{"name":"Blackened","color":"#4A3728","force":null,"wrapper":"San Andrés, Connecticut Shade","vitolas":[],"story":"A collaboration between Drew Estate, James Hetfield (Metallica) and Rob Dietrich (Blackened whisky), says the company. The M81, released on 18 October 2022 according to a press article, pairs a maduro San Andrés wrapper with a maduro Connecticut Broadleaf binder, in Corona, Robusto, Toro and Corona Doble; the S84 Shade to Black, in early 2024 according to Corona Cigar Co., switches to an Ecuadorian Connecticut Shade wrapper, and drewestate.com presents these two expressions in October 2026."},{"name":"Chateau Real","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"Launched in 2006, when the company was making its debut in non-infused cigars, then abandoned, it was announced as returning on 9 November 2023 in Connecticut Shade over a Nicaraguan binder and filler, for the online retailers of the Drew Diplomat network. Drew Estate added to it a Habano for Cigars International in August 2024 and a San Andrés Maduro for its DDDP accounts on 1 November 2024, all rolled at La Gran Fabrica in Robusto, Toro and Churchill; in October 2026, the products page of drewestate.com does not list it among its lines."},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Cigars sold in bundles of 20 or 25: press release from the company dated 29 June 2018, presentation at the IPCPR in July 2018, four versions (Sweet with a Habano wrapper, Maduro, Shade, Sun Grown) on an Indonesian binder and filler, rolled at La Gran Fabrica in Robusto, Toro, Churchill and Gordito. In October 2026, drewestate.com presents it with Maduro, Sweet, Shade and Sun Grown."}]',
  `gamme_es` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"El superventas infusionado: aromas de té, hierbas botánicas, esencia floral. Robusto (54 x 127mm). El puro que introdujo a millones de estadounidenses en el cigarro sin asustarlos con la potencia de las ligas tradicionales. Capa indonesia sobre liga propia de Drew Estate. Controvertido entre los puristas, adorado por sus fieles.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonesia"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"La otra cara de Drew Estate: la más seria, la más buscada. Capa Connecticut Broadleaf Habano sobre triple ligero nicaragüense. Café ristretto, cacao amargo, mora. La Flying Pig, un perfecto corto y rechoncho, es el formato más raro y más caro de la gama.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Creada por los propios torcedores: los obreros de la fábrica querían un puro tan bueno como Liga Privada a precio accesible. Liga cercana a la del No.9, capa ecuatoriana más económica. Chocolate, café, pimienta. La revuelta obrera más lograda del sector.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Ecuador"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"El puro de Willy Herrera, el ligador de El Titan de Bronze en Miami contratado en 2011, lanzado a principios de 2013 con una receta compuesta en su primera visita a Estelí. El censo de este atlas lo tomaba por una casa.","vitolas":[],"wrapper":"Habano de Ecuador"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"Tabaco de Kentucky curado al humo de leña, como el de las pipas, en un puro liado en Estelí. Una línea, no una casa.","vitolas":[],"wrapper":"Kentucky curado al fuego"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013 — el puro que los torcedores se hacen, dice la casa: broadleaf, rústico, un solo formato al principio.","vitolas":[],"wrapper":"Broadleaf de Connecticut"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015 — la versión fuerte de Herrera Estelí, capa San Andrés.","vitolas":[],"wrapper":"San Andrés (México)"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Línea infusionada: según Corona Cigar Co., especias de Europa y del Sudeste Asiático, vino y ron sobre tabacos de Honduras y Nicaragua, con, según CigarPlace, cuatro meses de infusión y después una maduración en armarios de cedro. En octubre de 2026, Corona Cigar Co. muestra siete variantes de ella (Kaya, Mother Earth, Nectar, Spice Torpedo, Spice Triple Corona, Vann Reef, Clove Tiki) con capas Connecticut Shade, Habano, Sumatra o Cameroun, Cigars Direct indica que el cigarillo Clove Tiki está enrollado a mano, y el catálogo en línea de Drew Estate no la incluye."},{"name":"Blackened","color":"#4A3728","force":null,"wrapper":"San Andrés, Connecticut Shade","vitolas":[],"story":"Colaboración entre Drew Estate, James Hetfield (Metallica) y Rob Dietrich (whisky Blackened), dice la casa. La M81, que salió el 18 de octubre de 2022 según un artículo de prensa, combina una capa San Andrés maduro con un capote Connecticut Broadleaf maduro, en Corona, Robusto, Toro y Corona Doble; la S84 Shade to Black, a principios de 2024 según Corona Cigar Co., pasa a una capa Connecticut Shade de Ecuador, y drewestate.com presenta estas dos expresiones en octubre de 2026."},{"name":"Chateau Real","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"Lanzada en 2006, cuando la casa debutaba en el puro sin infusión, y luego abandonada, se anunció su regreso el 9 de noviembre de 2023 en Connecticut Shade sobre capote y tripa nicaragüenses, para los minoristas en línea de la red Drew Diplomat. Drew Estate le añadió un Habano para Cigars International en agosto de 2024 y un Maduro San Andrés para sus cuentas DDDP el 1 de noviembre de 2024, todos enrollados en La Gran Fabrica en Robusto, Toro y Churchill; en octubre de 2026, la página de productos de drewestate.com no la incluye entre sus líneas."},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Puros vendidos en bundles de 20 o 25: comunicado de la casa del 29 de junio de 2018, presentación en el IPCPR en julio de 2018, cuatro versiones (Sweet con capa Habano, Maduro, Shade, Sun Grown) sobre capote y tripa de Indonesia, enrolladas en La Gran Fabrica en Robusto, Toro, Churchill y Gordito. En octubre de 2026, drewestate.com la presenta con Maduro, Sweet, Shade y Sun Grown."}]',
  `gamme_de` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"Der infundierte Bestseller — Tee, botanische Kräuter, blumige Essenz. Robusto (54 x 127 mm). Die Zigarre, die Millionen Amerikaner an die Zigarre heranführte, ohne sie mit der Kraft traditioneller Mischungen zu erschrecken. Indonesisches Deckblatt über hauseigener Drew-Estate-Mischung. Umstritten bei Puristen, geliebt von ihren Anhängern.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"Indonesien"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"Das andere Gesicht von Drew Estate — das ernsteste, das begehrteste. Deckblatt Connecticut Broadleaf Habano über nicaraguanischem Triple Ligero. Ristretto, bittere Kakao, Brombeere. Die Flying Pig, ein kurzes, gedrungenes Perfecto, ist das seltenste und teuerste Format der Serie.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"Von den Torcedores selbst geschaffen — die Arbeiter der Fabrik wollten eine Zigarre so gut wie die Liga Privada zu zugänglichem Preis. Mischung nah am No.9, günstigeres ecuadorianisches Deckblatt. Schokolade, Kaffee, Pfeffer. Die gelungenste Arbeiterrevolte der Branche.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"Ecuador"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"Die Zigarre von Willy Herrera, dem 2011 engagierten Blender von El Titan de Bronze in Miami, Anfang 2013 lanciert nach einem Rezept aus seinem ersten Besuch in Estelí. Die Zählung dieses Atlas hielt sie für ein Haus.","vitolas":[],"wrapper":"Ecuadorianisches Habano"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"Kentucky-Tabak, über Holzrauch getrocknet wie für Pfeifen, in einer in Estelí gerollten Zigarre. Eine Linie, kein Haus.","vitolas":[],"wrapper":"Feuergetrockneter Kentucky"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013 — die Zigarre, die sich die Roller selbst machen, sagt das Haus: Broadleaf, rustikal, anfangs ein einziges Format.","vitolas":[],"wrapper":"Connecticut-Broadleaf"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015 — die kräftige Version von Herrera Estelí, San-Andrés-Deckblatt.","vitolas":[],"wrapper":"San Andrés (Mexiko)"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Infundierte Linie: laut Corona Cigar Co. Gewürze aus Europa und Südostasien, Wein und Rum auf Tabaken aus Honduras und Nicaragua, dazu laut CigarPlace vier Monate Infusion und anschließend Reifung in Zedernholzschränken. Im Oktober 2026 führt Corona Cigar Co. sieben Varianten davon auf (Kaya, Mother Earth, Nectar, Spice Torpedo, Spice Triple Corona, Vann Reef, Clove Tiki) mit Deckblättern Connecticut Shade, Habano, Sumatra oder Cameroun; Cigars Direct nennt das Zigarillo Clove Tiki handgerollt, und der Online-Katalog von Drew Estate führt die Linie nicht auf."},{"name":"Blackened","color":"#4A3728","force":null,"wrapper":"San Andrés, Connecticut Shade","vitolas":[],"story":"Zusammenarbeit von Drew Estate, James Hetfield (Metallica) und Rob Dietrich (Whisky Blackened), sagt das Haus. Die M81, laut einem Presseartikel am 18. Oktober 2022 erschienen, kombiniert ein Deckblatt San Andrés maduro mit einem Umblatt Connecticut Broadleaf maduro, in Corona, Robusto, Toro und Corona Doble; die S84 Shade to Black, Anfang 2024 laut Corona Cigar Co., wechselt zu einem Deckblatt Connecticut Shade aus Ecuador, und drewestate.com präsentiert diese beiden Ausführungen im Oktober 2026."},{"name":"Chateau Real","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"Im Jahr 2006 eingeführt, als das Haus seine Anfänge bei nicht infundierten Zigarren machte, dann aufgegeben, wurde sie am 9. November 2023 als Rückkehr angekündigt, in Connecticut Shade auf nicaraguanischem Umblatt und nicaraguanischer Einlage, für die Online-Händler des Netzes Drew Diplomat. Drew Estate fügte einen Habano für Cigars International im August 2024 und einen Maduro San Andrés für seine DDDP-Konten am 1. November 2024 hinzu, alle gerollt bei La Gran Fabrica in Robusto, Toro und Churchill; im Oktober 2026 führt die Produktseite von drewestate.com sie nicht unter ihren Linien auf."},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Zigarren, verkauft in Bundles zu 20 oder 25: Pressemitteilung des Hauses vom 29. Juni 2018, Vorstellung auf der IPCPR im Juli 2018, vier Varianten (Sweet mit Deckblatt Habano, Maduro, Shade, Sun Grown) auf Umblatt und Einlage aus Indonesien, gerollt bei La Gran Fabrica in Robusto, Toro, Churchill und Gordito. Im Oktober 2026 präsentiert drewestate.com die Linie mit Maduro, Sweet, Shade und Sun Grown."}]',
  `gamme_zh` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"浸香系列的畅销之作——茶、植物香草、花香精油。罗布图规格（54 x 127 毫米）。正是这支雪茄让数百万美国人接触雪茄，而不必先被传统配方的力度吓退。印尼茄衣，内裹 Drew Estate 自有配方。纯粹派对它争议不断，拥趸却爱之如命。","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"印尼"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"Drew Estate 的另一副面孔——最正经，也最抢手。康涅狄格宽叶哈瓦那茄衣，内裹尼加拉瓜三重利赫罗。里斯特雷托咖啡、苦可可、黑莓。短而粗壮的 Flying Pig 是全系中最稀有也最昂贵的规格。","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"由卷制师们自己创制——厂里的工人想要一支像 Liga Privada 一样好、价格却够得着的雪茄。配方接近 No.9，改用更便宜的厄瓜多尔茄衣。巧克力、咖啡、胡椒。这是行业里最成功的一场工人起义。","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"厄瓜多尔"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"威利·埃雷拉的雪茄——他是迈阿密 El Titan de Bronze 的调配师，2011年受聘——2013年初推出，配方在他首次造访埃斯特利时调成。本图集的普查曾把它当作一家公司。","vitolas":[],"wrapper":"厄瓜多尔 Habano"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"像烟斗烟草那样用木柴烟熏干燥的肯塔基烟叶，卷进一支埃斯特利制作的雪茄。是一条线，不是一家公司。","vitolas":[],"wrapper":"烟熏干燥的肯塔基烟叶"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013年——公司说这是卷工给自己做的雪茄：broadleaf，粗犷，起初只有一种尺寸。","vitolas":[],"wrapper":"康涅狄格 broadleaf"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015年——Herrera Estelí 的浓烈版，圣安德烈斯茄衣。","vitolas":[],"wrapper":"圣安德烈斯（墨西哥）"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","wrapper":"未公开","vitolas":[],"story":"浸渍型系列：据Corona Cigar Co.称，在洪都拉斯和尼加拉瓜的烟草上使用来自欧洲和东南亚的香料、葡萄酒和朗姆酒，另据CigarPlace称，浸渍四个月，随后在雪松木柜中陈化。2026年十月，Corona Cigar Co.列出该系列的七款（Kaya、Mother Earth、Nectar、Spice Torpedo、Spice Triple Corona、Vann Reef、Clove Tiki），茄衣为Connecticut Shade、Habano、Sumatra或Cameroun；Cigars Direct称Clove Tiki小雪茄为手工卷制；Drew Estate的在线目录未列出该系列。"},{"name":"Blackened","color":"#4A3728","force":null,"wrapper":"San Andrés，Connecticut Shade","vitolas":[],"story":"Drew Estate、James Hetfield（Metallica）与Rob Dietrich（Blackened威士忌）的合作作品，据该公司称。M81据一篇媒体文章于2022年十月18日推出，搭配San Andrés maduro茄衣与Connecticut Broadleaf maduro茄套，有Corona、Robusto、Toro和Corona Doble规格；S84 Shade to Black据Corona Cigar Co.于2024年初推出，改用厄瓜多尔Connecticut Shade茄衣，drewestate.com于2026年十月展示这两款。"},{"name":"Chateau Real","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"于2006年推出，当时该公司刚开始涉足非浸渍雪茄，后被放弃；2023年十一月9日宣布回归，采用Connecticut Shade茄衣，配尼加拉瓜茄套和茄芯，面向Drew Diplomat网络的线上零售商。Drew Estate又为Cigars International添加了一款Habano（2024年八月），并为其DDDP账户添加了一款Maduro San Andrés（2024年十一月1日），均在La Gran Fabrica卷制，规格为Robusto、Toro和Churchill；2026年十月，drewestate.com的产品页面未将其列入其产品系列。"},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"雪茄以每束20或25支的bundles形式出售：该公司于2018年六月29日发布新闻稿，并于2018年七月在IPCPR上亮相，共四款（Sweet配Habano茄衣、Maduro、Shade、Sun Grown），茄套和茄芯均来自印度尼西亚，在La Gran Fabrica卷制，规格为Robusto、Toro、Churchill和Gordito。2026年十月，drewestate.com展示该系列，含Maduro、Sweet、Shade和Sun Grown。"}]',
  `gamme_ar` = '[{"name":"ACID Kuba Kuba","color":"#7B1FA2","force":"Medium","story":"الأكثر مبيعًا بين المنقوعات — شاي، أعشاب نباتية، خلاصة زهرية. روبوستو (54 × 127 مم). السيجار الذي عرّف ملايين الأمريكيين على التدخين دون أن يُفزعهم بقوّة الخلطات التقليدية. غلاف إندونيسي فوق خلطة خاصة بـDrew Estate. مثير للجدل عند المتشدّدين، محبوب عند أنصاره.","vitolas":["Kuba Kuba","Blondie","Dirty Rat","Deep Dish","Krush"],"wrapper":"إندونيسي"},{"name":"Liga Privada No.9","color":"#1C0A00","force":"Full","story":"الوجه الآخر لـDrew Estate — الأكثر جدّية والأكثر طلبًا. غلاف كونيتيكت برودليف هابانو فوق ليغيرو نيكاراغوي ثلاثي. قهوة ريستريتو، كاكاو مرّ، توت أسود. أما الـFlying Pig، وهو بيرفيكتو قصير ممتلئ، فأندر قياسات المجموعة وأغلاها.","vitolas":["Toro","Robusto","Flying Pig","Petit Lancero","No.9 Perfecto"],"wrapper":"Connecticut Broadleaf Habano"},{"name":"Undercrown","color":"#8B4513","force":"Full","story":"أنشأها اللافّون أنفسهم — أراد عمّال المصنع سيجارًا بجودة الليغا بريفادا وبسعر في المتناول. خلطة قريبة من الـNo.9، بغلاف إكوادوري أقلّ كلفة. شوكولاتة، قهوة، فلفل. أنجح ثورة عمالية في هذه الصناعة.","vitolas":["Toro","Robusto","Corona Viva","Flying Pig","Shade","Sun Grown"],"wrapper":"إكوادوري"},{"name":"Herrera Estelí","color":"#8B5A2B","force":"Medium","story":"سيجار ويلي إيريرا، مزّاج El Titan de Bronze في ميامي الذي استُقدم سنة 2011، أُطلق في مطلع 2013 على وصفة رُكّبت في زيارته الأولى لإستيلي. وكان إحصاء هذا الأطلس يحسبه دارًا.","vitolas":[],"wrapper":"هابانو إكوادوري"},{"name":"Kentucky Fire Cured","color":"#3A2A1E","force":"Medium-Full","story":"تبغ كنتاكي مجفَّف على دخان الخشب كتبغ الغليون، في سيجار يُلفّ في إستيلي. خطٌّ لا دار.","vitolas":[],"wrapper":"كنتاكي مجفَّف بالنار"},{"name":"Nica Rustica","color":"#3A2A1E","force":"Full","story":"2013 — السيجار الذي يصنعه اللفّافون لأنفسهم، كما تقول الدار: برودليف، خشن، قياس واحد في البداية.","vitolas":[],"wrapper":"برودليف كونيتيكت"},{"name":"Herrera Estelí Norteño","color":"#4A3728","force":"Full","story":"2015 — النسخة القويّة من Herrera Estelí، غلاف سان أندريس.","vitolas":[],"wrapper":"سان أندريس (المكسيك)"},{"name":"Ambrosia","color":"#C9A96E","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"خط مُنقَع: بحسب Corona Cigar Co.، توابل من أوروبا وجنوب شرق آسيا ونبيذ ورم على أنواع تبغ من هندوراس ونيكاراغوا، مع أربعة شهور من النقع ثم تعتيق في خزائن من خشب الأرز بحسب CigarPlace. وفي أكتوبر 2026 تعرض Corona Cigar Co. سبعة إصدارات منه (Kaya وMother Earth وNectar وSpice Torpedo وSpice Triple Corona وVann Reef وClove Tiki) بأغلفة خارجية Connecticut Shade أو Habano أو Sumatra أو Cameroun، وتذكر Cigars Direct أن سيجاريلو Clove Tiki ملفوف يدويًا، ولا يدرجه فهرس Drew Estate على الإنترنت."},{"name":"Blackened","color":"#4A3728","force":null,"wrapper":"San Andrés، Connecticut Shade","vitolas":[],"story":"تعاون بين Drew Estate وJames Hetfield (Metallica) وRob Dietrich (ويسكي Blackened)، كما تقول الشركة. أما M81، التي صدرت في 18 أكتوبر 2022 بحسب مقال صحفي، فتجمع بين غلاف خارجي San Andrés maduro ورابط Connecticut Broadleaf maduro، بمقاسات Corona وRobusto وToro وCorona Doble؛ وتنتقل S84 Shade to Black، في مطلع 2024 بحسب Corona Cigar Co.، إلى غلاف خارجي Connecticut Shade من الإكوادور، ويعرض drewestate.com هذين الإصدارين في أكتوبر 2026."},{"name":"Chateau Real","color":"#C9A96E","force":null,"wrapper":"Connecticut Shade","vitolas":[],"story":"أُطلقت في 2006، حين كانت الشركة في بداياتها مع السيجار غير المنقوع، ثم تُركت، ثم أُعلن عن عودتها في 9 نوفمبر 2023 بغلاف Connecticut Shade على رابط وحشوة من نيكاراغوا، لتجار التجزئة عبر الإنترنت في شبكة Drew Diplomat. وأضافت Drew Estate إليها Habano لصالح Cigars International في أغسطس 2024 وMaduro San Andrés لحسابات DDDP لديها في 1 نوفمبر 2024، وكلها ملفوفة في La Gran Fabrica بمقاسات Robusto وToro وChurchill؛ وفي أكتوبر 2026 لا تدرجها صفحة المنتجات في drewestate.com ضمن خطوطها."},{"name":"Factory Smokes","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"سيجار يُباع في bundles من 20 أو 25: بيان صحفي من الشركة بتاريخ 29 يونيو 2018، وعرض في IPCPR في يوليو 2018، وأربعة إصدارات (Sweet بغلاف Habano وMaduro وShade وSun Grown) على رابط وحشوة من إندونيسيا، ملفوفة في La Gran Fabrica بمقاسات Robusto وToro وChurchill وGordito. وفي أكتوبر 2026 يعرضها drewestate.com مع Maduro وSweet وShade وSun Grown."}]',
  `source` = IF(LOCATE('drewestate.com « Blackened » (octobre 2026 : collaboration d', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'drewestate.com « Blackened » (octobre 2026 : collaboration de James Hetfield, Rob Dietrich et Jonathan Drew ; deux expressions, Blackened M81 maduro et Blackened S84 shade) ; cigarslover.com « Blackened Cigars M81 By Drew Estate » (18 octobre 2022, date de sortie donnée par la page : M81 à cape San Andrés maduro, liant Connecticut River Valley Broadleaf maduro, tripes du Nicaragua et de Pennsylvanie ; Corona, Robusto, Toro, Corona Doble ; Drew Estate fabricant) ; coronacigar.com « Blackened S84 » (octobre 2026 : S84 début 2024, cape Connecticut Shade d''Équateur, liant Connecticut Broadleaf maduro, tripes du Nicaragua et de Pennsylvanie) ; drewestate.prezly.com « Upgrade your Bundle Game with Factory Smokes by Drew Estate » (29 juin 2018 : quatre déclinaisons Sweet, Maduro, Shade, Sun Grown, liant et tripes d''Indonésie, bottes de 20 ou 25, roulées à La Gran Fabrica Drew Estate, présentées à l''IPCPR en juillet 2018) ; drewestate.com « Factory Smokes » (octobre 2026 : quatre déclinaisons Maduro, Sweet, Shade, Sun Grown) ; drewestate.com « Products » (octobre 2026 : la page liste Liga Privada, Undercrown, Nica Rustica, Blackened, Herrera Estelí, Factory Smokes, ACID, Kentucky Fire Cured et d''autres lignes ; ni Ambrosia, ni Chateau Real, ni MUWAT n''y figurent parmi les lignes listées) ; cigar-coop.com « Cigar News: Drew Estate Brings Back Chateau Real as Online Retailer Offering » (9 novembre 2023 : Chateau Real lancée en 2006 puis abandonnée, de retour pour les détaillants en ligne Drew Diplomat, Connecticut Shade sur liant et tripes nicaraguayens, La Gran Fabrica, Robusto, Toro, Churchill) ; drewestate.prezly.com « Drew Estate Builds on Chateau Real Brand with Cigars International Exclusive Habano Expression » (1er août 2024 : Chateau Real Habano, liant indonésien, tripes des États-Unis et du Nicaragua, La Gran Fabrica, exclusivité Cigars International) ; drewestate.prezly.com « Drew Estate Launches Chateau Real Maduro for DDDP Accounts » (1er novembre 2024 : Chateau Real Maduro, cape San Andrés, liant indonésien, tripes des États-Unis et du Nicaragua, La Gran Fabrica, réservée aux comptes DDDP) ; coronacigar.com « Drew Estate Cigars Online: Ambrosia Blends » (octobre 2026 : sept déclinaisons Kaya, Mother Earth, Nectar, Spice Torpedo, Spice Triple Corona, Vann Reef, Clove Tiki ; capes Connecticut Shade, Habano, Sumatra, Cameroun ; épices, vin et rhum, tabacs du Honduras et du Nicaragua) ; coronacigar.com « Ambrosia Spice Torpedo (6 x 54) » (octobre 2026 : force moyenne, fabricant Drew Estate, en stock) ; cigarplace.biz « Ambrosia Cigars by Drew Estate » (octobre 2026 : quatre mois d''infusion puis armoires de cèdre ; corps moyen) ; cigarsdirect.com « Drew Estate Ambrosia Clove Tiki » (octobre 2026 : cigarillo Clove Tiki roulé à la main, fabriqué au Nicaragua, en stock)')),
  `updated_at` = NOW()
 WHERE `name` = 'Drew Estate';

-- ── E.P. Carrillo — paragraphe : EPC, Gilbert de Montsalvat, Conspiracy ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Deux autres noms passent par Casa Carrillo, nom que Tabacale', `history`) > 0, `history`, CONCAT(`history`, '

', 'Deux autres noms passent par Casa Carrillo, nom que Tabacalera La Alianza porte depuis février 2024, sans être de la maison. Gilbert de Montsalvat est la marque de Raymondo Bernasconi (The Royal Cigar Company, Bâle), lancée officiellement le 1er avril 2008 ; selon Zigarren.Zone, l''édition 15 Years (juin 2024) y est roulée sur un assemblage d''Ernesto Perez-Carrillo, alors que la ligne Signature (2023) sort de Tabacalera Diaz Cabrera, chez Eladio Diaz. Conspiracy appartient à Quality Importers Trading Company ; l''expédition a commencé en août 2024. EPC est le sigle sous lequel Cigarworld classe le catalogue de la maison.')),
  `history_en` = IF(LOCATE('Two other names go through Casa Carrillo, the name that Taba', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'Two other names go through Casa Carrillo, the name that Tabacalera La Alianza has carried since February 2024, without belonging to the company. Gilbert de Montsalvat is the brand of Raymondo Bernasconi (The Royal Cigar Company, Basel), officially launched on 1 April 2008; according to Zigarren.Zone, the 15 Years edition (June 2024) is rolled there on a blend by Ernesto Perez-Carrillo, whereas the Signature line (2023) comes out of Tabacalera Diaz Cabrera, at Eladio Diaz. Conspiracy belongs to Quality Importers Trading Company; shipping began in August 2024. EPC is the abbreviation under which Cigarworld classifies the company''s catalogue.')),
  `history_es` = IF(LOCATE('Otros dos nombres pasan por Casa Carrillo, nombre que Tabaca', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Otros dos nombres pasan por Casa Carrillo, nombre que Tabacalera La Alianza lleva desde febrero de 2024, sin ser de la casa. Gilbert de Montsalvat es la marca de Raymondo Bernasconi (The Royal Cigar Company, Basilea), lanzada oficialmente el 1 de abril de 2008; según Zigarren.Zone, la edición 15 Years (junio de 2024) se enrolla allí sobre una mezcla de Ernesto Perez-Carrillo, mientras que la línea Signature (2023) sale de Tabacalera Diaz Cabrera, en casa de Eladio Diaz. Conspiracy pertenece a Quality Importers Trading Company; el envío comenzó en agosto de 2024. EPC es la sigla con la que Cigarworld clasifica el catálogo de la casa.')),
  `history_de` = IF(LOCATE('Zwei weitere Namen laufen über Casa Carrillo, den Namen, den', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Zwei weitere Namen laufen über Casa Carrillo, den Namen, den Tabacalera La Alianza seit Februar 2024 trägt, ohne zum Haus zu gehören. Gilbert de Montsalvat ist die Marke von Raymondo Bernasconi (The Royal Cigar Company, Basel), offiziell am 1. April 2008 auf den Markt gebracht; laut Zigarren.Zone wird die Edition 15 Years (Juni 2024) dort auf einer Mischung von Ernesto Perez-Carrillo gerollt, während die Linie Signature (2023) aus Tabacalera Diaz Cabrera bei Eladio Diaz stammt. Conspiracy gehört Quality Importers Trading Company; der Versand begann im August 2024. EPC ist das Kürzel, unter dem Cigarworld den Katalog des Hauses einordnet.')),
  `history_zh` = IF(LOCATE('另有两个名称要经过Casa Carrillo，这是Tabacalera La Alianza自2024年二月起使用的名称', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', '另有两个名称要经过Casa Carrillo，这是Tabacalera La Alianza自2024年二月起使用的名称，但它们并不属于该公司。Gilbert de Montsalvat是Raymondo Bernasconi（The Royal Cigar Company，巴塞尔）的品牌，于2008年四月1日正式推出；据Zigarren.Zone，15 Years版本（2024年六月）在那里以Ernesto Perez-Carrillo的拼配卷制，而Signature系列（2023年）则出自Tabacalera Diaz Cabrera，在Eladio Diaz处。Conspiracy属于Quality Importers Trading Company；发货于2024年八月开始。EPC是Cigarworld用来归类该公司产品目录的缩写。')),
  `history_ar` = IF(LOCATE('هناك اسمان آخران يمرّان عبر Casa Carrillo، وهو الاسم الذي تح', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'هناك اسمان آخران يمرّان عبر Casa Carrillo، وهو الاسم الذي تحمله Tabacalera La Alianza منذ فبراير 2024، دون أن يكونا من الشركة. Gilbert de Montsalvat هي علامة Raymondo Bernasconi (The Royal Cigar Company، بازل)، أُطلقت رسميًا في 1 أبريل 2008؛ وبحسب Zigarren.Zone، يُلَفّ إصدار 15 Years (يونيو 2024) هناك على توليفة Ernesto Perez-Carrillo، بينما يخرج خط Signature (2023) من Tabacalera Diaz Cabrera لدى Eladio Diaz. تعود ملكية Conspiracy إلى Quality Importers Trading Company؛ وبدأ الشحن في أغسطس 2024. EPC هو الاختصار الذي تصنّف به Cigarworld كتالوج الشركة.')),
  `mentions` = '["Black Swan","EPC","Gilbert de Montsalvat","Conspiracy"]',
  `source` = IF(LOCATE('premiumcigars.org « Casa Carrillo: A Factory''s Evolution » (', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'premiumcigars.org « Casa Carrillo: A Factory''s Evolution » (20 février 2024, date du changement de nom : Tabacalera La Alianza devient Casa Carrillo) ; zigarren.zone « Gilbert de Montsalvat 15 years » (25 juin 2024 : édition 15 Years, Gran Toro, 2 000 boîtes de 15, roulée à Casa Carrillo, ex-Tabacalera La Alianza, assemblage d''Ernesto Perez-Carrillo) ; zigarren.zone « Gilbert de Montsalvat SIGNATURE Pre-Release at The Chedi Andermatt » (3 avril 2023 : Raymondo Bernasconi propriétaire de la marque et de The Royal Cigar Company à Bâle ; marque officiellement fondée le 1er avril 2008) ; cigarslover.com « Gilbert de Montsalvat presents new Signature line at the Chedi Andermatt » (mars 2023 : ligne Signature, assemblage d''Eladio Diaz, fabriquée à Tabacalera Diaz Cabrera, Santiago de los Caballeros) ; cigar-coop.com « Conspiracy Cigars » (8 août 2024 : Quality Importers Trading Company possède la marque, expédition commencée, fabriquée à Casa Carrillo) ; stogiepress.com « Cigar News: Quality Importers Trading Company Collaborate With The Carrillo Family to Create CONSPIRACY® CIGARS » (18 mars 2024 : Conspiracy assemblée et roulée par EPC Cigars à Casa Carrillo, Ernesto Perez Carrillo Jr. et III) ; cigarworld.de « EPC » (octobre 2026 : catalogue E.P. Carrillo regroupé sous le sigle EPC, fabriqué à Tabacalera La Alianza)')),
  `updated_at` = NOW()
 WHERE `name` = 'E.P. Carrillo';

-- ── El Titan de Bronze — paragraphe : Altezas Reales 1871 ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Altezas Reales 1871 est la marque de Rafael Cifuentes III, a', `history`) > 0, `history`, CONCAT(`history`, '

', 'Altezas Reales 1871 est la marque de Rafael Cifuentes III, arrière-petit-fils de Ramón Cifuentes Llano, ancien propriétaire de la fabrique Partagás. Présentée en septembre 2023 à Dadeland, en Floride, elle est roulée à Miami dans cette manufacture : cape Habano d''Équateur sur liant et tripe nicaraguayens, en Robusto, Corona et Toro, avec un tirage annoncé de 1 000 boîtes par format. Cifuentes dit s''être inspiré des Partagás des années 1990, surtout du Serie D No. 4 ; il distribue la marque par sa société, Flor de Tabacos La Lealtad. En octobre 2026, Luxury Cigar Club affiche tous les formats épuisés.')),
  `history_en` = IF(LOCATE('Altezas Reales 1871 is the brand of Rafael Cifuentes III, gr', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'Altezas Reales 1871 is the brand of Rafael Cifuentes III, great-grandson of Ramón Cifuentes Llano, former owner of the Partagás factory. Presented in September 2023 at Dadeland, in Florida, it is rolled in Miami in this factory: Ecuadorian Habano wrapper over Nicaraguan binder and filler, in Robusto, Corona and Toro, with an announced run of 1 000 boxes per size. Cifuentes says he drew his inspiration from the Partagás of the 1990s, especially the Serie D No. 4; he distributes the brand through his company, Flor de Tabacos La Lealtad. In October 2026, Luxury Cigar Club shows all sizes as sold out.')),
  `history_es` = IF(LOCATE('Altezas Reales 1871 es la marca de Rafael Cifuentes III, bis', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Altezas Reales 1871 es la marca de Rafael Cifuentes III, bisnieto de Ramón Cifuentes Llano, antiguo propietario de la fábrica Partagás. Presentada en septiembre de 2023 en Dadeland, en Florida, se enrolla en Miami en esta fábrica: capa Habano de Ecuador sobre capote y tripa nicaragüenses, en Robusto, Corona y Toro, con una tirada anunciada de 1 000 cajas por formato. Cifuentes dice haberse inspirado en los Partagás de la década de 1990, especialmente en el Serie D No. 4; distribuye la marca a través de su empresa, Flor de Tabacos La Lealtad. En octubre de 2026, Luxury Cigar Club muestra todos los formatos agotados.')),
  `history_de` = IF(LOCATE('Altezas Reales 1871 ist die Marke von Rafael Cifuentes III, ', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Altezas Reales 1871 ist die Marke von Rafael Cifuentes III, Urenkel von Ramón Cifuentes Llano, dem früheren Eigentümer der Fabrik Partagás. Im September 2023 in Dadeland in Florida vorgestellt, wird sie in Miami in dieser Fabrik gerollt: Deckblatt Habano aus Ecuador auf nicaraguanischem Umblatt und nicaraguanischer Einlage, in Robusto, Corona und Toro, mit einer angekündigten Auflage von 1 000 Schachteln pro Format. Cifuentes sagt, er habe sich an den Partagás der 1990er Jahre orientiert, besonders am Serie D No. 4; er vertreibt die Marke über seine Firma Flor de Tabacos La Lealtad. Im Oktober 2026 zeigt Luxury Cigar Club alle Formate als ausverkauft.')),
  `history_zh` = IF(LOCATE('Altezas Reales 1871是Rafael Cifuentes III的品牌，他是Ramón Cifuente', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', 'Altezas Reales 1871是Rafael Cifuentes III的品牌，他是Ramón Cifuentes Llano的曾孙，后者是Partagás工厂的前任所有者。该品牌于2023年九月在佛罗里达州的Dadeland亮相，在迈阿密的这家工厂卷制：厄瓜多尔Habano茄衣，配尼加拉瓜茄套和茄芯，规格为Robusto、Corona和Toro，宣布的产量为每种规格1 000盒。Cifuentes表示，他的灵感来自1990年代的Partagás，尤其是Serie D No. 4；他通过自己的公司Flor de Tabacos La Lealtad销售该品牌。2026年十月，Luxury Cigar Club显示所有规格均已售罄。')),
  `history_ar` = IF(LOCATE('Altezas Reales 1871 هي علامة Rafael Cifuentes III، ابن حفيد ', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'Altezas Reales 1871 هي علامة Rafael Cifuentes III، ابن حفيد Ramón Cifuentes Llano، المالك السابق لمصنع Partagás. قُدّمت في سبتمبر 2023 في Dadeland بولاية فلوريدا، وتُلَفّ في ميامي في هذا المصنع: غلاف خارجي Habano من الإكوادور على رابط وحشوة من نيكاراغوا، بمقاسات Robusto وCorona وToro، مع إنتاج معلن قدره 1 000 علبة لكل مقاس. يقول Cifuentes إنه استلهم Partagás من عقد 1990، وخاصةً Serie D No. 4؛ ويوزّع العلامة عبر شركته Flor de Tabacos La Lealtad. وفي أكتوبر 2026 تعرض Luxury Cigar Club جميع المقاسات على أنها نافدة.')),
  `mentions` = '["Altezas Reales 1871"]',
  `source` = IF(LOCATE('cigaraficionado.com « Partagas Descendent Starts Altezas Rea', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigaraficionado.com « Partagas Descendent Starts Altezas Reales 1871 Brand » (15 septembre 2023 : Rafael Cifuentes III, arrière-petit-fils de Ramón Cifuentes Llano, ancien propriétaire de la fabrique Partagás ; lancement à Dadeland, Floride ; roulée à El Titan de Bronze, Miami ; cape Habano d''Équateur, tripe nicaraguayenne ; Robusto, Corona, Toro, 1 000 boîtes par format ; inspiration Partagás des années 1990 et Serie D No. 4 ; distribution par Flor de Tabacos La Lealtad) ; luxurycigarclub.com « Altezas Reales 1871 » (octobre 2026 : tous les formats épuisés ; cape Habano Claro d''Équateur, liant et tripe du Nicaragua ; produite à El Titan de Bronze, Miami)')),
  `updated_at` = NOW()
 WHERE `name` = 'El Titan de Bronze';

-- ── Les sceaux des champs touchés, calculés depuis les colonnes ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT '1502 Cigars' hote, 'gamme' champ
        UNION ALL SELECT 'A.J. Fernandez' hote, 'history' champ
        UNION ALL SELECT 'A.J. Fernandez' hote, 'gamme' champ
        UNION ALL SELECT 'Aganorsa Leaf' hote, 'history' champ
        UNION ALL SELECT 'Aganorsa Leaf' hote, 'gamme' champ
        UNION ALL SELECT 'Aging Room' hote, 'gamme' champ
        UNION ALL SELECT 'Aladino' hote, 'gamme' champ
        UNION ALL SELECT 'American Caribbean Cigars' hote, 'history' champ
        UNION ALL SELECT 'American Caribbean Cigars' hote, 'gamme' champ
        UNION ALL SELECT 'Arturo Fuente' hote, 'gamme' champ
        UNION ALL SELECT 'Ashton' hote, 'history' champ
        UNION ALL SELECT 'Ashton' hote, 'gamme' champ
        UNION ALL SELECT 'Casa de Alegria' hote, 'history' champ
        UNION ALL SELECT 'Cohiba USA' hote, 'history' champ
        UNION ALL SELECT 'Davidoff' hote, 'gamme' champ
        UNION ALL SELECT 'Don Diego' hote, 'history' champ
        UNION ALL SELECT 'Drew Estate' hote, 'gamme' champ
        UNION ALL SELECT 'E.P. Carrillo' hote, 'history' champ
        UNION ALL SELECT 'El Titan de Bronze' hote, 'history' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `maj` = NOW();

