UNION ALL SELECT '1502 Cigars', 'en', 'gamme Cachitos', JSON_CONTAINS(JSON_EXTRACT(`gamme_en`, '$[*].name'), '"Cachitos"') FROM `brands` WHERE `name` = '1502 Cigars'
