UNION ALL SELECT 'E.P. Carrillo', 'fr', 'source', LOCATE('premiumcigars.org « Casa Carrillo: A Factory''s Evolution » (', `source`) > 0 FROM `brands` WHERE `name` = 'E.P. Carrillo'
UNION ALL SELECT 'El Titan de Bronze', 'fr', 'paragraphe', LOCATE('Altezas Reales 1871 est la marque de Rafael Cifuentes III, a', `history`) > 0 FROM `brands` WHERE `name` = 'El Titan de Bronze'
UNION ALL SELECT 'El Titan de Bronze', 'en', 'paragraphe', LOCATE('Altezas Reales 1871 is the brand of Rafael Cifuentes III, gr', `history_en`) > 0 FROM `brands` WHERE `name` = 'El Titan de Bronze'
UNION ALL SELECT 'El Titan de Bronze', 'es', 'paragraphe', LOCATE('Altezas Reales 1871 es la marca de Rafael Cifuentes III, bis', `history_es`) > 0 FROM `brands` WHERE `name` = 'El Titan de Bronze'
UNION ALL SELECT 'El Titan de Bronze', 'de', 'paragraphe', LOCATE('Altezas Reales 1871 ist die Marke von Rafael Cifuentes III, ', `history_de`) > 0 FROM `brands` WHERE `name` = 'El Titan de Bronze'
UNION ALL SELECT 'El Titan de Bronze', 'zh', 'paragraphe', LOCATE('Altezas Reales 1871是Rafael Cifuentes III的品牌，他是Ramón Cifuente', `history_zh`) > 0 FROM `brands` WHERE `name` = 'El Titan de Bronze'
UNION ALL SELECT 'El Titan de Bronze', 'ar', 'paragraphe', LOCATE('Altezas Reales 1871 هي علامة Rafael Cifuentes III، ابن حفيد ', `history_ar`) > 0 FROM `brands` WHERE `name` = 'El Titan de Bronze'
UNION ALL SELECT 'El Titan de Bronze', '—', 'trouvable : Altezas Reales 1871', JSON_CONTAINS(`mentions`, '"Altezas Reales 1871"') FROM `brands` WHERE `name` = 'El Titan de Bronze'
UNION ALL SELECT 'El Titan de Bronze', 'fr', 'source', LOCATE('cigaraficionado.com « Partagas Descendent Starts Altezas Rea', `source`) > 0 FROM `brands` WHERE `name` = 'El Titan de Bronze';
SELECT (SELECT COUNT(*) FROM `translation_status` t JOIN `brands` b ON b.`name` = t.`entite_id` AND t.`entite` = 'brands'
         WHERE t.`source_hash` <> SHA1(CASE t.`champ` WHEN 'history' THEN b.`history` ELSE b.`gamme` END)
           AND t.`champ` IN ('history', 'gamme') AND b.`name` IN ('1502 Cigars','A.J. Fernandez','Aganorsa Leaf','Aging Room','Aladino','American Caribbean Cigars','Arturo Fuente','Ashton','Casa de Alegria','Cohiba USA','Davidoff','Don Diego','Drew Estate','E.P. Carrillo','El Titan de Bronze')) = 0 AS sceaux_a_jour,
       (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 250') AS journal_non_tronque;
